-- Ancient-Chinese-Allusion 典故库
SET NAMES utf8mb4;
INSERT INTO word_lib (word_id,word,word_type,pos,explain,example,tag_list,difficulty) VALUES
(8500000000000000000,'焚书坑儒',7,'典故','《史记·秦始皇本纪》载：秦始皇三十四年(公元前213年)，采纳丞相李斯的奏议，下令焚烧除秦记、医药、卜筮、种树书外的所有书籍;次年，侯生、卢生等儒生不愿为秦始皇求仙药，始皇大怒，在咸阳坑杀儒生四百六十余人，史称焚书坑儒。焚书坑儒1:后常用作统治者排斥异说残害文人、实行文化专制的典实。
儒硎1:泛指读书人遭受浩劫。
书劫1:诗书遭焚烧劫难。
坑儒1:指<u>秦始皇</u>坑杀儒生事，后亦泛指残害读书人。
扫除诗书1:指<u>秦始皇</u>焚书，实行愚民政策。
灭学1:指秦始皇焚毁先代典籍。
焚书1:指<u>秦始皇</u>焚烧诗书事。
祖龙之虐1:指<u>秦始皇</u>焚书坑儒。
秦坑1:指<u>秦始皇</u>坑儒事。泛指统治者对儒生的镇压手段。
秦氏灭学1:指<u>秦始皇</u>焚毁先代典籍。
秦火1:指<u>秦始皇</u>焚书事。也泛指统治者焚毁书籍的文化专制手段。
诗书炀1:指焚烧诗书，毁灭文化。','《〈尚书〉序》：“秦始皇灭先代典籍，焚书坑儒，天下学士逃难解散。”邹韬奋《思想犯罪》：“在我国历史上，压迫思想的模范人物殆莫善于焚书坑儒的秦始皇。”；《后汉书·申屠传》：“昔战国之世，处士横议，列国之王，至为拥篲先驱，卒有坑儒烧书之祸。”；《明成化说唱词话丛刊·花关索出身传》：“秦皇独霸诸侯城，焚典坑儒丧圣文。”；清李渔《奈何天·软诓》：“避秦翻恐被秦收，那焚坑法网难轻漏。”；《汉书·地理志下》：“昭王曾孙政(即秦始皇)并六国，称皇帝，负力怙威，燔书坑儒，自任私智。”；北周庾信《谢滕王集启》：“加以建邺阳九，劣免儒硎;江陵百六，几从士垅。”；明袁宏道《祇园理藏完》诗之二：“书劫何须怨祖龙，南寮师弟北师公。”；汉王充《论衡·死伪》：“秦始皇用李斯之议，燔烧诗书，后又坑儒。”清孔尚任《桃花扇·归山》：“无罪而杀，是坑儒根苗。”；宋苏轼《石鼓歌》：“扫除诗书诵法律，投弃俎豆陈鞭杻。当年何人佐祖龙，上蔡公子牵黄狗。”；汉蔡邕《宗庙迭毁议》：“左中郎将臣邕议，以为汉承秦灭学之后，宗庙之制，不用周礼。”南朝梁沈约《修定乐书疏》：“窃以秦代灭学，《乐经》残亡。”；明沈德符《野获编补遗·经传佚书》：“先秦徐福入海时，必携古经传同往，此时焚书事未起。”；《聊斋志异·书痴》：“异史氏曰：天下之物，积则招妒，好则生魔：女之妖，书之魔也。事近怪诞，治之未为不可;而祖龙之虐，不已惨乎!”；唐张说《奉晚宴两相及礼官丽正学士序》：“乃命学者缮落简，缉遗编，纂鲁壁之文章，缀秦坑之煨烬。”宋周密《齐东野语·杭学游士聚散》：“相与提携，莫蹈秦坑之祸。”；《隋书·律历志上》：“及秦氏灭学，其道浸微。”；唐孟郊《秋怀》诗之十五：“秦火不爇舌，秦火空爇文。”瞿秋白《赤都心史》三五：“心与智不调，请寻一桃源，避此秦火。”；元郝经《秋兴》诗：“六经依旧垂天地，千载秦灰散劫空。”蔡元培《致〈公言报〉并答林琴南君函》：“先是补山先生某日至学园，见焚字纸者，近取谛视，则先生之遗著在焉，审之则一半已付秦灰。”；柳亚子《次韵奉和陈叔老三绝》之一：“南社于今𠦜一年，新《南社集》未秦烟。”；清赵翼 《题棕亭见和长篇后即赠》诗：“岂无郢唱能飞雪，未到秦焚已化烟。”；清黄遵宪《感怀》诗：“劫灰出秦燔，六籍半残缺。”；宋叶適《魏华甫鹤山书院》诗：“曾经秦祸多散阙，郑笺毛传悲纷如。”；晋潘岳《西征赋》：“儒林填于坑阱，诗书炀而为烟。”','[]',2),
(8500000000000000001,'安乐窝',7,'典故','《宋史·邵雍传》：“初至洛，蓬荜环堵，不芘风雨，躬樵爨以事父母，虽平居屡空，而怡然有所甚乐，人莫能窥也……雍岁时耕稼，仅给衣食。名其居曰‘安乐窝’，因自号安乐先生。”安乐窝1:后以安乐窝指平凡而安闲舒适的住处。
康节行窝1:指<u>宋</u>人为接待<u>邵雍</u>仿其所居<u>安乐窝</u>而为之建造的居室。后因指可以小住的安适之所。<u>邵雍</u>，谧<u>康节</u>，故称。
尧夫安乐1:指<u>宋</u><u>邵雍</u>平凡而安逸舒适的住处。','宋戴复古《访赵东野》诗：“四山便是清凉国，一室可为安乐窝。”；清赵翼《赠王文园给谏》诗：“康节行窝争欲设，伯休入市共相亲。”；元张养浩《新水令·辞官》套曲：“有花有酒有行窝，无烦无恼无灾祸。”；尧夫，宋邵雍之字。清张文虎《梧桐树·题钱湛园小隐书窝图》套曲：“佳名谁领，便尧夫安乐，也难厮并。”；明凌云翰《苏武慢》词：“君实园中，尧夫窝内，独乐正同安乐。”','[]',2),
(8500000000000000002,'鲛人泣珠',7,'典故','旧题汉郭宪《洞冥记》卷二：“〔吠勒国人〕乘象入海底取宝，宿于鲛人之舍，得泪珠，则鲛所泣之珠也，亦曰泣珠。”晋张华《博物志》卷九：“南海外有鲛人，水居如鱼，不废织绩，其眼能泣珠。从水出，寓人家，积日卖绡。将去，从主人索一器，泣而成珠满盘，以与主人。”鲛人泣珠1:后以鲛人泣珠指传说中的鲛人流泪成珠。
泉客1:指鲛人。本作“渊客”，避<u>唐高祖</u><u>李渊</u>讳，改“泉客”。
感恩珠1:指报恩。
泉客泣1:指传说中鲛人流泪成珠，送给主人。
泉客泪1:谓伤离别。
泉客珠1:泛指珍珠。
泣珠1:指流泪成珠，受恩施报。
泣珠人1:指边远蛮夷之人。
泣珠客1:指<u>南海</u>鲛人。
泣珠报恩1:谓受恩施报。
泣珠鲛女1:指神话中能流泪成珠的鲛人。
海绡1:传说中鲛人所织龙纱。
灵鲛1:指鲛人。
蛟人泣1:谓流泪成珠。蛟，通“鲛”。
蛟人珠1:传说鲛人所泣之珠。亦喻似珠之物。
蛟女绢1:借指薄而坚韧的丝织品，也指生丝织物。蛟，通“鲛”。
蛟布1:传说鲛人所织的丝织品。蛟，通“鲛”。
蛟珠1:传说鲛人所泣之珠。亦喻似珠之物。蛟，通“鲛”。
蛟绡1:传说鲛人所织的丝织品。泛指绢帛。蛟，通“鲛”。亦喻轻烟细雨。
蛟绡纱1:传说鲛人所织的丝织品。蛟，通“鲛”。
鲛人1:指传说中的人鱼。
鲛人泣1:形容如珠之物。
鲛人泪1:指眼泪。
鲛人诉泣1:指流泪成珠。亦用以形容如泪珠之物。
鲛客泪1:喻雨珠。
鲛室1:指鲛人水中居室，或谓龙宫。
鲛工1:指神话传说中织制鲛绡的鲛人。
鲛帕1:指精美的手帕。
鲛泪1:指眼泪。
鲛珠1:传说中鲛人泪珠所化的珍珠。
鲛珠2:亦比喻眼泪或似珠之物。
鲛盘1:鲛人接泪成珠之盘。
鲛织1:指鲛绡。
鲛绡1:传说中鲛人所织的绡。借指薄绢，轻纱。
鲛绡2:亦指手帕、丝巾。
鲛馆1:指鲛人的居室。
龙绡1:因以“龙绡”指传说中鲛人所织的丝织品。亦比喻薄如鲛绡之物。','《镜花缘》二十回：“此地既无城郭，这些桑人都以桑林为居，以桑为食，又能吐丝，倒像鲛人泣珠光景。”；唐李瀚《蒙求》：“渊客泣珠，交甫解佩。”；唐中宗《石淙》诗：“水炫珠光遇泉客，岩悬石镜厌山精。”；晋左思《吴都赋》：“泉室潜织而卷绡，渊客慷慨而泣珠。”；唐李群玉《病起别主人》诗：“益愧千金少，情将一饭殊。恨无泉客泪，尽泣感恩珠。”泉客，鲛人的别称。；唐刘禹锡《武陵书怀五十韵》：“湘灵悲鼓瑟，泉客泣酬恩。”；唐李商隐《自桂林奉使江陵途中感怀寄献尚书》诗：“东道违宁久，西园望不禁。江生魂黯黯，泉客泪涔涔。”；唐杜甫《客从》诗：“客从南溟来，遗我泉客珠。”；明王世贞《送刘比部恤刑云贵》诗：“泣珠恩自远，祝网面仍开。”；唐王维《送李判官赴东江》诗：“遥知辨璧吏，恩到泣珠人。”；元宋无《公无渡河》诗：“河伯娶妇蛟龙宅，公无白璧献河伯，恐公身为泣珠客。”；唐李颀《鲛人歌》：“泣珠报恩君莫辞，今年相见明年期。”；柳亚子《新文坛杂咏·田汉》：“泣珠鲛女今何处?倘供诗人跃马来。”；唐李贺《秦王饮酒》诗：“花楼玉凤声娇狞，海绡红文香浅清，黄鹅跌舞千年觥。”；唐康翊仁《鲛人潜织》诗：“珠馆冯夷室，灵鲛信所潜。”；宋梅尧臣《王安之寄石榴》诗：“割之珠落盘，不待蛟人泣。”此用以咏石榴。；唐刘商《姑苏怀古送秀才下第归江南》诗：“兴来下笔到奇景，瑶盘迸洒蛟人珠。”；唐元稹《和乐天送客游岭南二十韵》：“贡兼蛟女绢，俗重语儿巾。”；南朝梁任昉《述异记》卷上：“扬州有蛇市，市人鬻珠玉，而杂货蛟布。蛟人，即泉先也，又名泉客。”；《孝经援神契》：“蛟珠，宋曰蛟鱼之珠，有光辉，可以饰旗。”宋梅尧臣《和江邻幾咏雪二十韵》：“云横冻鹏翼，霰集泣蛟珠。”此指霰。；唐罗隐《江南行》：“江烟湿雨蛟绡软，漠漠小山眉黛浅。”宋陆游《临别成都帐饮万里桥赠谭德称》诗：“美人再拜乞利市，醉墨飞落生蛟绡。”；南朝梁任昉《述异记》卷上：“南海出蛟绡纱，泉先潜织，一名龙纱。其价百余金，以为服，入水不濡。”；端木蕻良《女神》：“海的女神带着鲛人和蜃女，在绿色的云片里嬉戏。”；宋林景熙《荷珠》诗：“又疑罢织鲛人泣，碧洼融作水银汁。”；清曹溶《念奴娇·将赴云中留别胡彦远兼戏其卖药》词：“我亦北阮穷途，鲛人泪尽，双鬓多添白。”；宋葛长庚《贺新郎·雪》词：“扑落梅梢穿度竹，恐是鲛人诉泣。”按，此例是用以状雪。；元王恽《大雹行》：“又疑鲛人泉客泣相别，泪洒珠玑恣狼藉。”；宋梅尧臣《许昌晚晴》诗：“荷盛鲛客泪，蔓濯野人缨。”；唐杜甫《秋日夔府咏怀奉寄郑监李宾客一百韵》：“俗异邻鲛室，朋来坐马鞯。”宋苏轼《有美堂暴雨》诗：“唤起谪仙泉洒面，倒倾鲛室泻琼瑰。”；明唐寅《题画》诗：“渔翁稳作船头睡，梦入鲛宫白渺茫。”；唐皮日休《奉酬鲁望见答鱼笺之什》诗：“轻如隐起腻如饴，除却鲛工解制稀。”；《红楼梦》六二回：“〔湘云〕又用鲛帕包了一包芍药花瓣枕着。”；明王世贞《哭李于鳞一百二十韵》：“满掬挥鲛泪，轻裘渍酒绵。”；清刘大櫆《山中与诸昆及王设参谢师其夜韵》诗：“日落沉鲛珠，月升荐和璧。”；清黄遵宪《羊城感赋》之四：“祆庙火焚氛更恶，鲛人珠尽泪犹多。”；宋刘辰翁《宝鼎现·丁酉元夕》词：“灯前拥髻，暗滴鲛珠坠。”明唐顺之《送程翰林松溪谪居朝阳》诗之三：“朝阳何所似?云水日氤氲。白昼鲛珠落，青天蜃阁分。”；宋钱惟演《泪》诗之一：“鲛盘千点怨吞声，蜡炬风高翠箔轻。”；明唐顺之《送王翰林浙江兵备副使》诗：“帆樯万里输鲛织，楼阁三秋吐蜃云。”；宋周弼《二郎神·西施浣纱碛》词：“剪断鲛绡何人续，黯梦想、秋江风冷。”明高东嘉《泣颜回·春游》套曲：“见游人往来，贪欢笑，舞鲛绡，闹咳咳笑高。”；唐顾况《送从兄使新罗》诗：“帝女飞衔石，鲛人卖泪绡。”；唐温庭筠《张静婉采莲曲》：“掌中无力舞衣轻，剪断鲛鮹破春碧。”；唐李商隐《玄微先生》诗：“龙竹裁轻策，鲛丝熨下裳。”宋柳永《临江仙引》词：“鲛丝雾吐渐收，细腰无力转娇慵。”；宋陆游《钗头凤》词：“春如旧，人空瘦，泪痕红浥鲛绡透。”；唐杜甫《雨》诗：“鲛馆如鸣杼，樵舟岂伐枚?”；唐韦应物《鼋头山神女歌》：“阴深灵气静凝美，的砾龙绡杂琼珮。”宋辛弃疾《瑞鹤仙·赋梅》词：“玉肌瘦弱，更重重，龙绡衬着。”按，此指梅花的花瓣。','[]',2),
(8500000000000000003,'涸辙之鲋',7,'典故','《庄子·外物》：“庄周家贫，故往贷粟于监河侯。监河侯曰：‘诺。我将得邑金，将贷子三百金，可乎?’庄周忿然作色曰：‘周昨来，有中道而呼者。周顾视车辙中，有鲋鱼焉。周问之曰：“鲋鱼来!子何为者邪?”对曰：“我，东海之波臣也。君岂有斗升之水而活我哉?”周曰：“诺。我且南游吴越之王，激西江之水而迎子，可乎?”鲋鱼忿然作色曰：“吾失我常与，我无所处。吾得斗升之水然活耳，君乃言此，曾不如早索我于枯鱼之肆!”’”涸辙之鲋1:后以涸辙之鲋比喻处于困境急待援助的人或物。
牛蹄中鱼1:处在牛蹄踏出的小水坑里的鱼。喻指濒临绝境。
东溟臣1:比喻陷于困境亟待解救的人。
救涸1:谓救助急须救助之难。
斗升水1:喻微薄的俸禄。
斗水1:喻指少量的资助。
斗水活鳞1:比喻得到微薄的资助而解救眼前的危急。
枯涸1:指困境。亦指陷入困境者。
枯鱼之肆1:卖干鱼的店铺。比喻死境、绝境。
枯鱼涸辙1:喻指急待救助的人陷于绝境。
波臣1:称水族。
波臣守辙1:指守困待援。
波臣槁1:谓身处困境，急待救援。
泥辙1:喻指失意落泊。
涸辙1:比喻困境。
涸鲋得水1:比喻绝处逢生，有所凭借。
溟鱼竭水1:喻身处困境，急待救援。
滞涸1:谓如涸辙之鱼，不能动弹。喻指窘困。
滞涸2:亦指窘困之境。
煦辙1:喻指援救处于困境者。
监河侯1:借指出贷钱物的人。
监河受贷粟1:指希望得到救济或资助。
监河贷1:指不能救急之贷。
穷鳞1:比喻身陷困境的人。
西江救涸辙1:谓远水不解近渴，无济于事。
西江润1:喻指解救危难的济助。
西江润涸辙1:喻指扶危济困，救人急难。
贷监河粟1:谓身处困境而乞援于吝于帮助的人。
辙鲋涸1:比喻身处危境，十分痛苦。
鲋处辙1:喻处于困境、绝境。','宋苏轼《乞开杭州西湖状》：“若一旦堙塞，使蛟龙鱼鳖，同为涸辙之鲋。”鲁迅《坟·娜拉走后怎样》：“但人不能饿着静候理想世界的到来，至少也得留一点残喘，正如涸辙之鲋，急谋升斗之水一样，就要这较为切近的经济权，一面再想别的法。”；清吴嘉纪《夏次公来东淘业盐赠诗》诗：“伏骥几曾忘道路，困鳞聊且就沾濡。”；明高启《送徐七山人》诗：“自笑失水鲋，空惭得云蛟。”；元曹文晦《水车歌》：“苏枯幸活庄子鲋，腾空如化琴高鲤。”；清褚人获《韩忠献喜雨诗》：“已发宋苗安在揠，再生庄鲋不虞枯。”；唐钱起《罢官后酬元校书见赠》诗：“宦名随落叶，生事感枯鱼。”；《玉支机》六回：“小弟异乡枯鲋，寄迹村蒙，自分孤生独死，不期偶遇管宗伯，只一见便尔垂青。”；《隋书·王孝籍传》：“伏惟明尚书公动哀矜之色，开宽裕之怀。咳唾足以活枯鳞，吹嘘可用飞穷羽。”；《剪灯新话·三山福地志》：“但愿捐斗水而活涸辙之枯。”；明张景《飞丸记·怜儒脱难》：“吹嘘一点灵犀热，涸辙枯鱼沐浩波。”；明张凤翼《红拂记·天开良佐》：“失林飞鸟无投处，涸辙穷鱼转困苦。”；唐王绩《薛记室收过庄见寻率题古意以赠》诗：“尔为背风鸟，我为涸辙鱼。”；唐李白《拟古》诗之五：“无事坐悲苦，块然涸辙鲋。”；明高启《送陈秀州》诗：“奈何不加怜，使作涸辙鳞?”；三国魏曹植《文帝诔》：“权若涸鱼，干腊矫鳞?”；北周庾信《拟咏怀》之一：“涸鲋常思水，惊飞每失林。”；唐骆宾王《畴昔篇》：“涸鳞去辙还游海，幽禽释网便翔空。”；清袁于令《西楼记·乘鸾》：“吾儿辙中涸鲋，得占龙头，皆因友资之益。”；唐窦常《酬舍弟牟秋日洛阳官舍寄怀十韵》：“思凌天际鹤，言甚辙中鱼。”；唐杜甫《奉赠萧十二使君》诗：“不达长卿病，从来原宪贫。监河受贷粟，一起辙中鳞。”；清黄遵宪《述闻》诗之四：“火焚祆庙连烽燧，辙涸羁臣乞海波。”；南朝陈徐陵《与王僧辩书》：“壤虫之比黄鹄，辙鲋之仰河宗。”唐孟郊《新卜清罗幽居奉献陆大夫》诗：“笼禽得高巢，辙鲋还层澜。”；《三国志·吕蒙传》：“今子太以旦夕之命，待不可望之救，犹牛蹄中鱼，冀赖江汉，其不可恃亦明矣。”；《孔丛子·连丛子下》：“且今已乏矣，而方须租入，是犹古人欲决江海以救牛蹄之鱼之类也。”；唐李白《赠友人》诗之三：“莫持西江水，空许东溟臣。”；唐杜甫《水宿遣兴寄呈群公》诗：“余波期救涸，费日苦轻赉。”；唐刘禹锡《送张盥赴举诗》：“乞取斗升水，因之云汉津。”；北魏李骞《赠亲友》诗：“监河爱斗水，苏子惜馀明。”《剪灯新话·三山福地志》：“但愿捐斗水而活涸辙之枯，下壶飧而救翳桑之饿。”；明徐复祚《一文钱》五出：“闻说道卢家广施，我挈儿女从乡来至，但只愿斗水活鳞，敢指望千金布地?”；唐元稹《酬许五康佐》诗：“枯涸方穷辙，生涯不系舟。”宋黄庭坚《黄颍州挽词》之一：“惠沫沾枯涸，忠规补过差。”；《晋书·闵王承传》：“足下若能卷甲电赴，犹或有济;若其狐疑，求我枯鱼之肆矣。”梁启超《生计学学说沿革小史》：“庸知一人之不利，驯至为一国之不利，一种之不利，并四万万人而将索诸枯鱼之肆耶!”；前蜀杜光庭《蜀王葛仙化祈雨醮词》：“生灵叹息，惧失于农功，沼沚鱼喁，将悬于枯肆。”；明汪廷讷《种玉记·奇术》：“枯鱼涸辙暂潜踪，大鹏何日天风送?”；宋叶绍翁《四朝闻见录·宁皇御舟》：“御鹢至沈于波臣。”清李渔《蜃中楼·幻因》：“终朝营海市，一旦付波臣。”；黄遵宪《七月二十一日外国联军入犯京师》诗：“波臣守辙还无恙，日驭挥戈岂有名?”；明徐渭《送某人之台州》诗：“木吏愁难付，波臣槁欲穿。”；唐孟郊《赠李观》诗：“昔为同恨客，今为独笑人。舍予在泥辙，飘迹上云津。”；唐王勃《秋日登洪府滕王阁饯别序》：“酌贪泉而觉爽，处涸辙以犹欢。”；宋沈辽《和张宝臣即元韵》：“枯辙不能活鲿鯋，骐骥垂耳伏盐车。”；梁启超《意大利建国三杰传》六节：“虽然，以当时久困地狱，渴望天日之意大利人，骤闻此语，殆如涸鲋得水，笼鸟脱樊，且距且跃，且汗且喘。”；《新唐书·契苾何力传》：“何力入延陀，如涸鱼得水，其脱必遽。”；宋唐庚《晚春寄友人》诗之二：“霜鹘空拳知有命，溟鱼竭水恐伤神。”；《后汉书·李固传》：“左右党进者，日有迁拜，守死善道者，滞涸穷路，而未有改敝立德之方。”李贤注：“滞涸穷路，以鱼为喻也。”；宋曾巩《乞登对状》：“赫然独断，察臣之本末;超然远御，收臣于滞涸。；唐骆宾王《上瑕丘韦明府启》：“游莲遇絏，悟宋玉之婴罗;在藻迷波，顾蒙庄之煦辙。”；宋陆游《莫笑银杯小答乔太傅》诗：“会当拂衣归故丘，代书贷粟监河侯。”；清朱奕恂《秋日杂感》诗：“监河赊许供江水，营室虚偿贷聘钱。”；唐杜甫《奉赠萧十二使君》诗：“监河受贷粟，一起辙中鳞。”；明许自昌《水浒记·周急》：“今日若得相怜，不使他监河望贷成虚哄，他情愿把女儿与押司呵，箕帚从容侧室中。”；宋周必大《次韵赵公直赏心亭醵今古风》','[]',2),
(8500000000000000004,'獬豸冠',7,'典故','《淮南子·主术训》：“楚文王好服獬冠，楚国效之。”高诱注：“獬豸之冠，如今御史冠。”汉蔡邕《独断》：“法冠，楚冠也……秦制执法服之。今御史廷尉监平服之，谓之獬豸冠。”《后汉书·舆服志下》：“法冠，一曰柱后。高五寸，以纚为展筩，铁柱卷，执法者服之，侍御史、廷尉正监平也。或谓之獬豸冠。獬豸，神羊，能别曲直，楚王尝获之，故以为冠。”刘昭注：“《异物志》曰：‘东北荒中有兽，名獬豸，一角，性忠，见人斗，则触不直者;闻人论，则咋不正者。’”獬豸冠1:因以法冠称獬豸冠，或借指御史等执法官吏，取其能严明执法、善断曲直邪正之意。
獬豸1:指传说中一种能以其独角辨别邪正的神羊。表示人君刑罚得中。
獬豸2:亦指獬豸冠。
冠獬豸1:指御史等执法官吏。
尧羊触邪1:指传说中<u>尧</u>时掌管刑狱的<u>皋繇</u>断狱，令神羊用角触有罪者。表示能明辨曲直邪正。
戴豸1:指任御史等执法官职。
獬豸触1:喻指弹奏邪恶之人。
神羊1:獬豸的别称。传说是一种能以其独角辨别邪正的神兽。
神羊触1:借指弹奏不法官吏。
触豸1:指传说中一种能以其独角辨别邪正的神兽。喻指为官清正，执法严明。
豸角1:喻指御史等执法官秉公执法的职权和威严。
铁豸1:指法冠。','唐韦縠《杜侍御送贡物戏赠》诗：“越人自贡珊瑚树，汉使何劳獬豸冠?”明无名氏《霞笺记·中丞训子》：“官居侍御立朝班，铁面丹心獬豸冠。”；唐柳宗元《为安南杨侍御祭张都护文》：“既受筐篚，载加命服。赐有楚冠，用惭豸角。”；北周庾信《燕射歌辞·徵调曲》之二：“曲轶无佞人可指，獬豸无繁刑可触。王道荡荡用无为，天下四人谁不足!”；元萨都剌《送张都台还京》诗：“忆昔中台簪獬豸，曾封直谏动銮舆。”；唐司空曙《九日送人》诗：“送人冠獬豸，值节佩茱萸。”；唐许棠《旅次滑台投献陆御史》诗：“霜台倚冠豸，赖许往来频。”；唐元稹《戒励风俗德音》：“苟非秦镜照胆，尧羊触邪，时君听之，安可不惑?”；唐许棠《送前汝州李侍御罢归宣城》诗：“吟诗早得名，戴豸又加荣。”；唐李商隐《寄太原卢司空》诗：“邪同獬豸触，乐伴凤凰听。”；唐权德舆《祭故薛殿中文》：“今则缪盩，天心茫茫。追维明灵，夙播馨芳。解巾秘府，累冠神羊。”宋梅尧臣《孙屯田召为御史》诗：“轻轩辞瑞翟，危弁学神羊。”；唐元稹《答姨兄胡灵之见寄五十韵》：“世道难于剑，谗言巧似笙。但憎心可转，不解跽如擎。始效神羊触，俄随雁旅征。”；唐元稹《送崔侍御之岭南二十韵》：“再砺神羊角，重开宪简函。”原注：“崔君前任已为御史。”；元傅若金《奉送达兼善御史赴河南》诗：“立朝防触豸，行路避乘骢。”；唐白居易《和李中丞与李给事山居》：“宪府触邪峨豸角，琐围驳正犯龙鳞。”；明无名氏《鸣凤记·鄢赵争宠》：“牙牌紫绶两垂腰，铁豸金章逞贵豪。”','[]',2),
(8500000000000000005,'乞巧',7,'典故','南朝梁宗懔《荆楚岁时记》：“七月七日为牵牛织女聚会之夜。是夕，人家妇女结彩缕，穿七孔针，或以金银鍮石为针，陈瓜果于庭中以乞巧，有喜子网于瓜上则以为符应。”乞巧1:谓旧俗农历七月七日夜(或七月六日)妇女在庭院向织女星乞求智巧。常用为咏七夕佳节之典。
穿针楼1:常用为咏七夕佳节之典。
乞巧楼1:指乞巧的彩楼。咏七夕佳节的典故。
乞巧穿针1:指妇女佳节乐事。
穿针1:指旧俗七月七日夜妇女穿七孔针向织女星乞求智巧。
穿针乞巧1:指七夕佳节。
穿针戏1:指旧俗七月七日夜妇女穿七孔针为戏，以为可从织女星求得智巧。','唐林杰《乞巧》诗：“家家乞巧望秋月，穿尽红线几万条。”宋苏轼《鹊桥仙·七夕和苏坚》词：“人生何处不儿嬉，看乞巧、朱楼彩舫。”；南朝梁庾肩吾《奉使江州舟中七夕》诗：“莫言相送浦，不及穿针楼。”；唐沈佺期《牛女》诗：“粉席秋期缓，针楼别怨多。”唐陈元初《忆长安·七夕》诗：“七夕针楼竞出，中元香供初移。”；宋钱惟演《戊申年七夕诗》：“欲闻天语犹嫌远，更结三层乞巧楼。”；元乔吉《金钱记》二折：“秋乞巧穿针会玉仙，冬赏雪观梅到玳筵。”；唐王勃《七夕赋》：“海人支石之机，江女穿针之阁。”；宋郭应祥《踏莎行·季巧席上赋》词：“渐永更筹，新凉气候，穿针乞巧看看又。”；唐沈亚之《为人撰乞巧文》：“邯郸人妓妇李容子，七夕祀织女，作穿针戏。”','[]',2),
(8500000000000000006,'绣衣持斧',7,'典故','《汉书·武帝纪》载：汉武帝天汉年间，民间起事者众，地方官督捕不力，因派遣直指使者暴胜之等着绣衣，持斧杖节，至各地巡捕群盗。绣衣持斧1:刺史、郡守以下因捕盗不力而伏法者多人。后因以绣衣持斧为皇帝特派的执法大员。
绣衣直指1:<u>汉</u>代官名。绣衣，表显贵;直指，谓处事无私。本由侍御使充任，故亦称“绣衣御使”、“绣衣使者”、“绣衣执法”等。
持斧翁1:御史的别称。
斧断1:指执法断案。
斧绣1:指巡视各地执法断案。
斧节1:皇帝特遣的执法大臣所持之物。斧象征执法大权，节表示使者身份。
暴斧1:本指<u>汉</u><u>暴胜之</u>绣衣持斧巡视州郡，执法严峻。比喻大权在握。
暴胜持斧1:指<u>汉</u><u>武帝</u>遣直指使者<u>暴胜之</u>衣绣衣，持斧杖节，至各地巡捕群盗。后用以为执法之典。
玉斧绣衣1:指御史官。
绣衣持节1:指皇帝特派的官员出使外国。','清赵翼《闻湖南军事告蒇诗以志喜》：“千里荆襄尚盗区，绣衣持斧未全诛。”；《续资治通鉴·元顺帝至正十九年》：“又有某绣使拜寇而乞生，某太守望敌而先退。”；宋杨万里《送周元吉显谟左司将漕湖北》诗之一：“绣斧光华谁不羡，一贤去国欠人留。”明章懋《与邓侍御书》：“迩闻绣斧南巡，而宿蠹潜奸，一时洗尽。”；唐卢照邻《〈乐府杂诗〉序》：“霜台有暇，文律动于京师;绣服无私，锦字飞于天下。”；《北史·高道穆传》：“臣虽愚短，守不假器，绣衣所指，冀以清肃。”；宋葛胜仲《临江仙》词：“九天持斧客，来作绣衣人。”；宋张孝祥《念奴娇·再和朱漕元顺》词：“绣衣使者，度郢中绝唱《阳春》《白雪》。”明王世贞《谢生歌七夕送脱屣老人谢榛》诗：“清霜倒飞鬼神哭，绣衣使者从天来。”；唐杜牧《许七侍御弃官东归寄赠十韵》：“天子绣衣吏，东吴美退居。”；元萨都剌《上内台治书阿鲁图立先茔石》诗：“獬豸峨冠侍紫皇，绣衣玉斧破炎荒。”；唐刘知幾《史通·辨职》：“虽地处禁中，而人同方外，可以养拙，可以藏愚，绣衣直指所不能绳。”；唐杜甫《两当县吴十侍御江上宅》诗：“借问持斧翁，几年长沙客?”仇兆鳌注引申涵光曰：“称御史为持斧翁，亦新。”；《梼杌闲评》八回：“本道昨过武当山下，有妇人称冤，系黄乡宦的媳妇，被钦差大臣程士宏无端陷害，全家冤惨已极，原呈在此，求大人斧断。”；元范梈《寄杜廉访使君》诗：“斧绣扬秋隼，泉阿达夜蛩。”；明李材《悬瓠城歌》：“煌煌日月焕斧节，惨惨风云动鞬䩨。”；明王世贞《哭李于麟一百二十韵》：“万蚁率归膻，暴斧犹拈手。”；唐李瀚《蒙求》：“暴胜持斧，张纲埋轮。”；清袁枚《寄西川方伯徐芷亭同年五十四韵》：“屏藩龙节重，玉斧绣衣鲜。”；宋刘一止《望明河·赠路侍郎使高丽》词：“万里勤劳，也等是壮年，绣衣持节。”','[]',2),
(8500000000000000007,'兰亭会',7,'典故','晋王羲之《兰亭集序》：“永和九年，岁在癸丑，暮春之初，会于会稽山阴之兰亭，修禊事也。群贤毕至，少长咸集……引以为流觞曲水，列坐其次，虽无丝竹管弦之盛，一觞一咏，亦足以畅叙幽情。”古代习俗农历三月上旬巳日(魏以后固定在三月三日)到水边洗濯沐浴，以驱除不祥，称修禊。王羲之、谢安、孙绰等四十一人上巳日在兰亭聚会，行修禊事，曲水流觞，饮酒赋诗。兰亭会1:<u>王羲之</u>为诗集作序，书法绝伦，后称《禊帖》。后因以兰亭会为高朋雅集、饮宴游乐的盛会之典。
羽觞随波1:谓注酒于杯，浮于水面，随波传送。羽觞，左右形如鸟翼的酒杯。一说，插羽于觞，促人速饮。
一觞一咏1:指边饮酒边吟诗或一杯酒一首诗。
修禊饮1:指古俗农历三月上旬巳日到水边洗濯，以驱除不祥，并饮酒嬉游的活动。
兰亭侣1:指<u>王羲之</u>、<u>谢安</u>等在<u>兰亭</u>集会的群贤。亦借指高朋酒友。
兰亭帖1:全称《兰亭集序帖》，别称《临河序帖》、《禊帖》。
兰亭豪逸1:指<u>兰亭</u>集会表现的豪情逸兴。
曲水流觞1:指古俗三月上巳日引曲水以流觞，围坐取饮为乐的故事。
永和1:代指<u>王羲之</u>等<u>山阴</u><u>兰亭</u>会。因其举行于<u>东晋</u><u>永和</u>九年，故称。
永和人1:指<u>东晋</u><u>王羲之</u>、<u>谢安</u>等在<u>山阴</u>聚会的群贤。因其举行于<u>永和</u>九年，故称。
泛曲水1:谓流觞取饮，相与为乐。
流觞故事1:指<u>王羲之</u>等<u>兰亭</u>会。
流觞高会1:指流杯曲水饮宴。
禊帖1:指<u>王羲之</u>手书《兰亭序》。为著名的行书法帖。
觞咏1:谓饮酒赋诗。
山阴兴21:指文人雅集，饮宴游乐的兴致。','唐柳宗元《韩漳州书报彻上人亡因寄二绝》之一：“他时若写兰亭会，莫画高僧支道林。”；唐李商隐《寄在朝郑曹独孤李四同年》诗：“不因醉本《兰亭》在，兼忘当年旧永和。”宋陆游《太平时》词：“临罢《兰亭》无一事，自修琴。”；唐王勃《滕王阁序》：“胜地不常，盛筵难再，兰亭已矣，梓泽丘墟。”；宋王庭珪《柳梢青·和张元晖清明》词：“兰亭丝竹，高会群贤，其人如玉。”；清吴雯《答李元升》诗：“已误兰亭修禊辰，归来芳草惜残春。”；宋陆游《简付十八官汉孺》诗：“兰亭修禊近，为记永和春。”；唐李商隐《令狐八拾遗绹见招送裴十四归华州》诗：“兰亭宴罢方回去，雪夜诗成道韫归。”；明瞿式耜《密之再次虞祠韵复再和》之一：“聊追洛社耆英会，绝胜兰亭觞咏时。”；唐李涉《送王六觐巢县叔父》诗之二：“长忆山阴旧会时，王家兄弟尽相随。”；唐独孤及《同徐侍郎五云溪新庭重阳宴集作》诗：“岂令永和人，独擅山阴游。”；宋贺铸《锦缠头》词：“旧说山阴禊事修，漫书茧纸叙清游，吴门千载更风流。”；唐许浑《和人贺杨仆射致政》：“岂同王谢山阴会，空叙流杯醉暮春。”；明杨慎《兰亭会》：“今日虽非洛邑，惟愿羽觞随波。”；宋叶梦得《虞美人·上巳席上》词：“茂林修竹山阴道，千载谁重到?半湖流水夕阳前，犹有一觞一咏似当年。”；宋柳永《如鱼水》词之一：“风淡淡，水茫茫，动一片晴光……紫薇郎，修禊饮，且乐仙乡。”；宋邓肃《浣溪沙》词之七：“已觉吹箫归碧落，从今禊饮笑山阴，金杯休惜十分深。”；清毛奇龄《上巳与故人》诗：“可怜修禊兰亭侣，正值流觞洛水边。”；是王羲之在兰亭宴集上写的序文。书法遒媚劲健，绝代更无，为历代最著名的行书法帖。法帖唐时为太宗所得。太宗死，以殉葬。存世者，唐摹墨迹以褚遂良“神龙本”为最著，石刻则首推欧阳询“定武本”。宋王安石《用前韵寄蔡天启》：“谁珍坛山刻，共赏《兰亭帖》。”；金段克己《鹧鸪天》词：“兰亭豪逸今陈迹，不醉东风待几时。”；宋王庭珪《柳梢青·和张元晖清明》词：“兰亭丝竹……曲水流觞，灯前细雨，檐花簌簌。”；宋苏轼《望江南·暮春》词：“曲水浪低蕉叶稳，舞雩风软纻罗轻。酣咏乐升平。”；清魏源《岱麓诸谷诗·岱谷陪尾山源》：“人间曲水觞，竟忘仙鬼宅。”；唐刘言史《上巳日陪襄阳李尚书宴光风亭》诗：“为报会稽亭上客，永和应不胜元和。”；唐李端《晚春过夏侯校书值其沈醉戏赠》诗：“人逢毂阳望，春似永和年。”；清周之琦《满江红》词：“长庆诗筒馀昨梦，永和禊饮成陈迹。”；唐独孤及《同徐侍郎王云溪新庭重阳宴集作》诗：“岂令永和人，独擅山阴游。”；宋苏轼《满江红·东武会流杯亭》词：“相将泛曲水，满城争出。君不见兰亭修禊事，当时座上皆豪逸。”；宋洪迈《满江红·立夏前一日借坡公韵》词：“修禊欢游今不讲，流觞故事何从觅?”；宋曹冠《夏初临·淳熙戊戌四月既望游涵碧》词：“流觞高会，不减兰亭;感怀书事，聊寄吟哦。”；宋周密《志雅堂杂钞·图画碑帖》：“龚圣予云：《禊帖》有大业间石本，其后有隋诸臣衔位。然则在智永未藏之先，此帖亦尝入御府。”清姚鼐《钱舜举萧翼赚兰亭图》诗：“越僧世得钟张法，头白朝朝摹《禊帖》。”；宋周密《齐东野语·〈禊序〉不入选帖》：“逸少《禊序》，高妙千古，而不入选。”宋楼钥《跋汪季路所藏修禊序》诗：“幼军草《禊序》，文采粲日星。”；唐韩愈《人日城南登高》诗：“令征前事为，觞咏新诗送。”清钮琇《觚賸续编·桃花园》：“有桃园十二亩，中坎小池，外环幽竹，春时花光灿照两岸，日与诸名人觞咏其中。”；唐卢纶《上巳日陪齐相公花楼宴》诗：“徒记山阴兴，祓禊乃为荣。”；唐罗隐《寄崔庆孙》诗：“交情淡薄应长在，俗态流离且勉旃。还拟山阴一乘兴，雪寒难得渡江船。”宋张孝祥《踏莎行》词：“山阴乘兴不须回，毗耶问疾难为对。”','[]',2),
(8500000000000000008,'萱草忘忧',7,'典故','《诗·卫风·伯兮》：“焉得谖草，言树之背。”毛传：“谖草令人忘忧。背，北堂也。”陆德明释文：“谖，本又作萱。”萱草忘忧1:古制，北堂为主妇居室，也是母亲居室，因以代指母亲。在北堂阶前种植萱草，象征母爱，故可忘忧。后遂用萱草忘忧为排解忧愁的典故。
萱花椿树1:椿长寿，因以指代父亲。“萱花椿树”则喻指父母。
北堂萱1:借指母亲。
忘忧1:萱草的代称。
无萱1:谓不能忘忧。
树萱1:本谓种植萱草，借指排遣忧愁。
椿庭萱草堂1:指父母。
椿萱并茂1:喻父母健在。
灵萱1:比喻母亲。
萱堂1:古制，北堂为主妇的居室，后因以“萱堂”指母亲的居室，并借以指母亲。
萱苏1:表示忘忧释劳。
萱草1:代指母亲。','汉蔡琰《胡笳十八拍》：“对萱草兮忧不忘，弹鸣琴兮情何伤。”《初学记》卷二七引三国魏王朗《与魏太子书》：“不遗惠书，所以慰沃，奉读欢笑，以藉饥渴。虽复萱草忘忧，皋苏释劳，无以加也。”三国魏嵇康《养生论》：“且豆令人重，榆令人瞑，合欢蠲忿，萱草忘忧，愚智所共知也。”；宋黄庭坚《满庭芳》词：“明眼空青，忘忧萱草，翠玉闲淡梳妆……难忘处，良辰美景，襟袖有余香。”；明汤显祖《牡丹亭·训女》：“祝萱花椿树，虽则是子生迟暮，守得见这蟠桃熟。”；明汤显祖《牡丹亭·闹殇》：“当今生花开一红，愿来生把萱椿再奉。”；宋王楙《野客丛书·萱堂桑梓》：“今人称母为北堂萱，盖祖《毛诗·伯兮》诗。”；唐陈子昂《魏氏园林人赋一物得秋亭萱草》诗：“忘忧谁见赏，空此北堂中。”元钱抱素《琐窗寒·题玉山草堂》词：“书带生香，忘忧弄色，四窗虚巧。”；南朝宋谢惠连《西陵遇风献康乐》诗：“积愤成疢痗，无萱将如何?”；南朝宋鲍照《代贫贱苦愁行》：“空庭惭树萱，药饵愧过客。”唐李白《送鲁郡刘长史迁弘农长史》诗：“托阴当树李，忘忧当树萱。”；元本高明《琵琶记·伯喈五娘相会》：“书，我只为你其中自有黄金屋，却教我撇却椿庭萱草堂。还思想，休休，毕竟是文章误我，我误爹娘。”；元本高明《琵琶记·伯喈夫妇上路回乡》：“女萝松柏望相依，况景入桑榆。他椿庭萱室齐倾弃，怎不想家山桃李?”；唐牟融《送徐浩》诗：“知君此去情偏切，堂上椿萱雪满头。”；明程登极等《幼学琼林·祖孙父子》：“父母俱存，谓之椿萱并茂;子孙发达，谓之兰桂腾芳。”；明杨珽《龙膏记·砥节》：“痛惊风大椿忽掊，恨临霜灵萱摧朽。”；宋叶梦得《再任后遣模归按视石林》诗：“白发萱堂上，孩儿更共怀。”元耶律楚材《祝忘忧居士寿》诗：“玉佩丁东照兰省，斑衣摇曳悦萱堂。”；元高文秀《襄阳会》二折：“你孩儿则要侍奉萱亲，修真养性。”明沈采《千金记·省女》：“感得萱亲言善，奈终身贫苦，衣食全悭。”；元本高明《琵琶记·丞相教女》：“堪哀，萱室先摧，叹妇仪姆教未曾谙解。”明陈汝元《金莲记·捷报》：“你公公还家有日，莫愁萱室之长孤。”；清黄景仁《念奴娇·送容甫归真州》词：“待有五湖三亩宅，多恐萱帏迟暮。”；明刘三吾《野庄赋》：“上奉萱闱兮下以友于。”清陈维崧《沁园春·题袁孝子重其负母看花图》词：“衣着斑斓，躬为痀偻，负得萱闱出北堂。”；南朝宋谢灵运《郡东山望溟海》诗：“萱苏始无慰，寂寞终可求。”南朝陈徐陵《〈玉台新咏〉序》：“庶得代彼萱苏，微蠲愁疾。”；明刘基《发安溪至青田戎事急不得留有感》诗：“朝原思脊令，夜船梦萱草。”明何景明《为李秀才寿母》诗：“梅花似白发，萱草亦朱颜。”','[]',2),
(8500000000000000009,'鞭尸',7,'典故','《史记·伍子胥列传》载：伍子胥的父兄被楚平王杀害，子胥逃到了吴国，立誓要报仇。他帮助吴王阖庐，屡败楚兵。“及吴兵入郢，伍子胥求昭王。既不得，乃掘楚平王墓，出其尸，鞭之三百，然后已。”鞭尸1:后遂以鞭尸为对有深仇大恨的人泄愤的典实。
鞭墓1:鞭墓，谓以鞭击墓。意在鞭挞死者，报仇雪恨。
掘墓鞭尸1:谓报仇雪恨。','唐元稹《楚歌》之三：“岂料奔吴士，鞭尸郢市门。”；清王昙《留侯祠》诗：“子胥鞭楚楚不绝，留侯入秦秦即灭。”；唐胡曾《咏史·柏举》诗：“谁料伍员入郢后，大开陵寝挞平王。”；元薛昂夫《朝天曲》曲：“伍员，报亲，多了鞭君忿。可怜悬首在东门，不见包胥恨。”；明高启《谒伍相祠》诗：“鞭尸楚墓生前孝，抉目吴门死后忠。”；唐李白《游溧阳北湖亭望瓦屋山怀古赠同旅》诗：“运开展宿愤，入楚鞭平王。”；明郑若庸《玉玦记·交兵》：“迁商鼎，鞭楚平，城鄢郢，除凶雪耻功全盛。”；元冯子振《鹦鹉曲》曲：“逃吴辞楚无家住，解宝剑赠津父。十年间隶越鞭荆，怒卷秋江潮雨。”；《后汉书·苏不韦传》：“〔伍子胥〕但鞭墓戮尸，以舒其愤，竟无手刃后主之报。”清顾炎武《子胥鞭平王之尸辩》：“盖止于鞭墓，而传者甚之以为鞭尸。”；柳亚子《是日适为“三一八”纪念节感赋一首》：“掘墓鞭尸公论在，休将宽纵误慈悲。”','[]',2),
(8500000000000000010,'圯桥进履',7,'典故','《史记·留侯世家》：“良(张良)尝闲从容步游下邳圯上，有一老父，衣褐，至良所，直堕其履圯下，顾为良曰：‘孺子，下取履!’良鄂然，欲殴之。为其老，强忍，下取履。父曰：‘履我!’良业为取履，因长跪履之。父以足受，笑而去。良殊大惊，随目之。父去里所，复还，曰：‘孺子可教矣。后五日平明，与我会此。’良因怪之。跪曰：‘诺。’五日平明，良往。父已先在，怒曰：‘与老人期，后，何也?’去，曰：‘后五日早会。’五日鸡鸣，良往。父又先在，复怒曰：‘后，何也?’去，曰：‘后五日复早来。’五日，良夜未半往。有顷，父亦来，喜曰：‘当如是。’出一编书，曰：‘读此则为王者师矣。后十年兴。十三年孺子见我济北，谷城山下黄石即我矣。’遂去，无他言，不复见。旦日视其书，乃《太公兵法》也。”“子房始所见下邳圯上老父与《太公书》者，后十三年从高帝过济北，果见谷城山下黄石，取而葆祠之。”圯桥进履1:后遂以圯桥进履称屈己尊老以求教益的典实。
黄石略1:指<u>黄石公</u>授与<u>张良</u>的兵书《黄石公三略》，即《太公兵法》。亦泛指兵书、兵法。
为人取履1:借指听人使唤。
书传圯上1:指传授兵法。
取履效子房1:谓如<u>汉</u><u>张良</u>那样敬老得益。
取履桥1:指发迹之前谦恭而受益之处。
受书黄石1:谓得到高人传受的奇书战策。
圯上1:指<u>张良</u>桥上进履受兵法事。
圯上之术1:泛指名师传授的兵法。
圯上老人1:指授<u>张良</u>兵法的圯上老父<u>黄石公</u>。
圯下传书1:指<u>黄石公</u>在圯桥传兵法于<u>张良</u>事。
圯桥1:指<u>张良</u>受《太公兵法》的桥。
圯桥书1:指<u>张良</u>在圯桥所得兵书。
圯桥授受1:指<u>张良</u>圯桥得<u>黄石公</u>传授的兵法事。
圯桥诺1:指答应在<u>圯桥</u>相会的诺言。
堕屦1:谓脱掉鞋子(让人穿以试尊老之志)。
子房鞋1:喻指贤人志士尚未显达。
孺子可教1:谓年轻人有出息，可以造就。
张良授策1:指<u>张良</u>在圯下接受<u>黄石公</u>所传的《太公兵法》。
授书黄石1:谓得到高人传授的兵法书。
授符黄石1:指<u>张良</u>得到<u>黄石公</u>送他的《太公兵法》。
谷城授策1:指<u>黄石公</u>在圯上授<u>张良</u>的兵书战策。
跪履1:表示向长者虔诚求教。
进履情1:谓屈己尊老以求教益的谦恭之情。
进黄公履1:为老者纳履，意谓尊老求教益。
黄石公1:指圯上授与<u>张良</u>《太公兵法》的老父。
黄石受书1:指<u>黄石公</u>授与<u>张良</u>兵书。泛指高人传授兵法。
黄石履1:喻指实现抱负、建立功勋的机遇。','清朱彝尊《彭城道中咏古》之二：“博浪飞椎后，圯桥进履年。”；北周庾信《周大将军怀德公吴明彻墓志铭》：“圯桥取履，早见兵书;竹林逢猿，遍知剑术。”；清吴伟业《又咏古》诗：“惜哉博浪椎，何如圯桥履?”；元贡师泰《晚泊邳州》诗：“白头老父相逢处，犹似圯桥授履还。”；明李东阳《张子房》诗：“博浪椎车亦壮哉，圯桥纳履大低回。”；唐李瀚《蒙求》：“子房取履，释之结袜。”；元无名氏《博望烧屯》：“能可学韩信般乞食，你也枉了似子房般进履。”；北周庾信《张良遇黄石公赞》：“张良取履，跪受无辞。兵书一卷，长者三期。”；清毛奇龄《题张舍人携琴图》诗：“桥边纳履贻书早，海上乘槎探石迟。”；明李贽《答袁石公》诗之五：“路逢进履者，定知过圯桥。”；元周德清《一枝花·遗张伯元》套曲：“大胸襟进履圯桥，壮游玩乘槎大海。”；清钱谦益《李太公寿》诗：“赤松黄石皆仙侣，进履桥边问子房。”；唐许浑《伤虞将军》诗：“对雪夜穷《黄石略》，望云秋计黑山程。”；宋辛弃疾《木兰花慢·席上送张仲固帅兴元》词：“一编书是帝王师，小试去征西。”；宋张孝祥《西江月·张钦夫寿》词：“已授一编圯下，却须三顾隆中。”；唐骆宾王《上司列太常伯启》诗：“道叶神交，黄石授帝师之略;德由天纵，白云降王辅之精。”；明唐寅《贫士吟》之三：“贫士居无半亩廛，圯桥拾得老人编。”；唐骆宾王《赋得白云抱幽石》诗：“讵知吴会影，长抱谷城文。”；唐李九龄《宿张正字别业》诗：“此时谁念孤吟客，唯有黄公一帙书。”；唐刘禹锡《郡内书情献裴侍中留守》诗：“兵符今奉黄公略，书殿曾随翠凤翔。”明汤式《一枝花·言志》套曲：“虽道是浅识，寡学，这几篇齐鲁论也不下黄公略。”；明陈子龙《壮游行》：“或授黄石书，且遇采药翁。”；唐李商隐《骄儿诗》：“穰苴《司马法》，张良黄石术。便为帝王师，不假更纤悉。”；唐骆宾王《久戍边城有怀京邑》诗：“战士青丝络，将军黄石符。”；唐聂夷中《胡无人行》：“不读战国书，不览黄石经。”；明袁宏道《相逢行》：“壁上荣启图，手里黄石编。”；宋刘克庄《水龙吟·方蒙仲王景长和余丙辰丁巳二词走笔答之》词之四：“老矣安能，为人取履，与人争屐。”；清陈三立《次韵再答义门》诗：“书传圯上此人去，锥处囊中相士谁?”；宋陆游《霜天杂兴》诗：“谷城黄石今安在，取履犹思效子房。”张良，字子房。；唐李德裕《奉送相公十八丈镇扬州》：“取履桥边啼鸟换，钓璜溪畔落花初。”；北周庾信《周柱国纥干弘神道碑》：“而受书黄石，意在王者之图;挥剑白猿，心存霸国之用。”；南朝宋傅亮《为宋公修张良庙教》：“交神圯上，道契商洛。”；南朝梁萧纲《华阳陶先生墓志铭》：“余昔在枌壤，早逢圯上之术;今簉元良，屡禀浮丘之教。”；宋苏轼《留侯论》：“子房以盖世之才，不为伊尹、太公之谋，而特出于荆轲、聂政之计，以侥幸于不死，此圯上老人之所为深惜也。”；金元好问《黄公庙》诗：“谁谓圯上人，异事惊竹素?”；宋苏轼《和致仕张郎中春昼》：“跪履数从圯下老，逸书闲问济南生。”；宋黄庭坚《赠黔南贾使君》诗：“少年圯下传书客，老去空同问道山。”；清张问陶《有感》诗：“挝翁骂酒空谗口，圯上传书气早驯。”；唐杨炯《右将军魏哲神道碑》：“吕望垂竿于渭涘，道峻匡周;张良授策于圯桥，功崇佐汉。”；唐李白《酬张卿夜宿南陵见赠》诗：“身为下邳客，家有圯桥书。”；宋苏轼《张竞辰永康所居万卷堂》诗：“留侯之孙书满腹，玉函宝方何用读。濠梁空复五车多，圯上从来一篇足。”；宋张孝祥《水调歌头·为总得居士寿》词：“隆中三顾客，圯上一编书。”；宋曾巩《孔教授张法曹以曾论荐特示长笺》诗：“绿发朱颜两少年，出伦清誉每相先。壁中字为时人考，圯上书从老父传。”；宋陈亮《子房贾生孔明魏徵何以学异端》：“子房为高帝谋臣，从容一发，动中机会，而尝超然于事物之外，此岂圯下兵法之所有哉?”；宋李义山《祝英台近·寿张路钤》词：“直须用了圯编，封侯万户，却归共、赤松翁约。”；清吴伟业《库公山》诗：“恨杀圯桥多授受，斗蛇刘项至今来。”；清顾炎武《子房》诗：“遂赴赤松要，无负圯桥诺。”；唐杜牧《中秋日拜起居表晨渡天津桥即事》诗：“迹留伤堕屦，恩在乐衔环。”；元马致远《拨不断》曲：“子房鞋，买臣柴，屠沽乞食为僚宰，版筑躬耕有将才。”；唐刘禹锡《澈上人文集纪》：“初，上人在吴兴居何山，与昼公为侣，时予方以两髦执笔砚，陪其吟咏，皆曰：‘孺子可教。’”；唐杨炯《唐右将军魏哲神道碑》：“张良授策于圯桥，功崇佐汉。”；柳亚子《哭熊味根烈士》诗：“贯日白虹天黯淡，授书黄石事荒唐。”；唐杜牧《题永崇西平王宅太尉愬院六韵》：“授符黄石老，学剑白猿翁。”；北周庾信《周上柱国齐王宪神道碑》：“则少有壮志，颇校兵书，玄水降灵，谷城授策……莫不吟诵在心，撰成于手。”；唐杜牧《洛中送冀处士东游》诗：“刘济愿跪履，田兴请建筹。”宋苏轼《和陶渊明读山海经》之十一：','[]',2),
(8500000000000000011,'井蛙',7,'典故','《庄子·秋水》：“井蛙不可以语于海者，拘于虚也。”又：“子独不闻夫坎井之蛙乎?谓东海之鳖曰：‘吾乐与!出跳梁乎井幹之上，入休乎缺甃之崖;赴水则接腋持颐，蹶泥则没足灭跗;还虷蟹与科斗，莫吾能若也。’……〔东海之鳖〕告之海曰：‘夫千里之远，不足以举其大;千仞之高，不足以极其深。禹之时，十年九潦，而水弗为加益;汤之时，八年七旱，而崖不为加损。夫不为顷久推移，不以多少进退者，此亦东海之大乐也。’于是坎井之蛙闻之，适适然惊，规规然自失也。”井蛙1:后因以井蛙比喻见闻狭隘、目光短浅的人。
井蛙醯鸡1:后因以“井蛙醯鸡”比喻见识短浅之人。
井坎1:浅井，废井。喻指很小的活动范围，狭隘的见闻。
井底鸣蛙1:比喻见识浅陋而又妄自尊大的人。
井管拘墟1:比喻浅陋、片面的见识。
井蛙之见1:比喻狭隘的见闻或浅陋的见识。
坎井1:浅井。借指很小的活动范围。表示见闻不广。
墟拘1:谓孤居一隅，见闻不广。
管窥蛙见1:比喻见识短浅，眼界狭窄。
蛙井喜1:喻识浅者沾沾自喜。
鳖岩之讥1:谓见笑于大方之家。','宋苏轼《辨道歌》：“吾恨尔见有所遮，海波或至惊井蛙。”；元王子一《误入桃源》一折：“他都是井中蛙妄称尊大，比周公不握发，比陈蕃不下榻。”；宋曾巩《贺克伏交阯表》：“唶海隅之昧俗，肆井底之狂谋。”；元关汉卿《裴度还带》二折：“如今有等轻薄之子，重色轻贤，真所谓井底之蛙耳。”；明陈汝元《金莲记·弹丝》：“妾阅人多矣，皆是井底虾蟆，未有中原麟凤。”；《东观汉记·马援传》：“子阳井底蛙耳!”明谢谠《四喜记·紫禁明扬》：“浅陋真如井底蛙。”；晋葛洪《抱朴子·论仙》：“况长生之事，世所希闻乎?望使必信，是令蚊虻负山，与井蟆论海也。”；汉桓宽《盐铁论·复古》：“宇宙之内，燕雀不知天地之高也;坎井之蛙，不知江海之大。”；清顾炎武《酬李处士因笃》诗：“自哂同坎蛙，难佐北溟浪。”；宋苏轼《南禅长老和诗不已故作六虫篇答之》：“那将坐井蛙，而比谈天衍。”；唐刘禹锡《送惟良上人》诗引：“信神与之而不能测神之所以付，信术通之而不能知术之所以至。浅哉余闻乎，曾井蛙醯鸡之不若也!”；宋王令《闻太学议》诗：“鮞虾陷井坎，莫与江海争。”；元无名氏《看钱奴》一折：“则你那自尊自贵无高下，真乃是井底鸣蛙。”；清李慈铭《越缦堂读书记·尚书集注音疏》：“巨儒著述，皆有本源，不得以井管拘墟，轻相訾议也。”；明沈德符《野获编·杂剧院本》：“予观此剧，尽有高出其上者。世人未曾遍观，逐队吠声，咤为绝唱，真井蛙之见耳。”郭沫若《屈原》二幕：“唉，那是客臣的井蛙之见喽，所谓‘情人眼里出西施’啦。”；清赵执信《始见海》诗：“半生在坎井，跬步临津涯。”；清赵翼《同北墅漱田观西洋乐器》诗：“始知天地大，到处有开辟。域中多墟拘，儒外有物格。”；清李渔《闲情偶寄·词曲上》：“〔予〕只以管窥蛙见之识，谬语同心;虚赤帜于词坛，以待将来作者。”；宋黄庭坚《次韵答邢敦夫》：“方求无津涯，不作蛙井喜。”；唐段成式《酉阳杂俎·酒食》：“常怀鲐腹之诮，每惧鳖岩之讥。”','[]',2),
(8500000000000000012,'贾女香',7,'典故','南朝宋刘义庆《世说新语·惑溺》：“韩寿美姿容，贾充辟以为掾。充每聚会，贾女于青琐中看，见寿，悦之，恒怀存想，发于吟咏。后婢往寿家，具述如此，并言女光丽。寿闻之心动，遂请婢潜修音问，及期往宿。寿蹻捷绝人，逾墙而入，家中莫知。自是充觉女盛自拂拭，悦畅有异于常。后会诸吏，闻寿有奇香之气，是外国所贡，一著人则历月不歇。充计武帝唯赐己及陈骞，馀家无此香，疑寿与女通……充乃取女左右婢考问，即以状对。充秘之，以女妻寿。”贾女香1:后以贾女香指馥郁的异香，或男女倾情之物。
偷香窃玉1:后因以“偷香窃玉”谓与女子偷情私通。
偷香1:谓女子爱悦男子，或谓与女子私通。
偷香韩寿1:指与女子偷情私通的人。
爱香韩寿1:泛指风流倜傥之人。
盗香1:谓男女私通情意。
窃香韩寿1:指与女子私通情爱的风流子。
窥青琐1:表示对意中人的爱慕。青琐，刻镂成格的窗户。
窥韩1:谓女子对意中人的倾慕。
贾氏窥帘1:形容女子对所爱之人倾心相慕。
贾袖传香1:喻指女子对恋人的私情。
青琐偷香1:指男女私情。
韩寿1:借称美男子。多指风流子弟。
韩寿偷香1:指男女倾情私合。
韩寿香1:指异香或男女定情之物。
香寄韩寿1:指男女私通。','宋黄庭坚《酴醾》诗：“汉宫娇额半涂黄，入骨浓薰贾女香。”；元周文质《蝶恋花·悟迷》套曲：“朱门深闭贾充香，兰房强揣郑生玉，青楼空掷潘安果。”；明阮大铖《燕子笺·伪缉》：“他打包家关节，盗贾家香，现有这女驼供状。”；元钱霖《台城路·次邵复孺韵》词：“花明柳暝，念贾箧香空，谢池诗冷。”；元石君宝《竹坞听琴》四折：“再不赴偷香窃玉期，再不事炼药烧丹教，从此后，无烦少恼。”；唐李端《妾薄命》诗：“折步教人学，偷香与客熏。”鲁迅《集外集拾遗·辩“文人无行”》：“轻薄、浮躁、酗酒、嫖妓而至于闹事，偷香而至于害人，这是古来之所谓‘文人无行’。”；《警世通言·宿香亭张浩遇莺莺》：“一夕东轩多少事，韩生虚负窃香名。”；元陈克明《粉蝶儿·怨别》套曲：“不弱如待月张生，偷香韩寿，谒浆崔护。”；明屠隆《昙花记·仇邪设谤》：“向月下花前，偷韩窥宋，荒淫不道。”；宋向子諲《清平乐·崖桂盛开戏呈韩叔夏司谏》词：“而今老我芗林，世间百不关心。独喜爱香韩寿，能来同醉花阴。”；清纪昀《阅微草堂笔记·槐西杂志三》：“济南宋青雷言，其乡民家一少年，与邻女相悦，时相窥也，久而微露盗香迹。”；元曾瑞《青杏子·骋怀》曲：“月宵花昼，大筵排回雪韦娘，小酌会窃香韩寿。”；明许自昌《水浒记·计迎》：“窥青琐，鳏鱼渴凤无如我。”；宋廖莹中《个侬》词：“语态眠情，感多情轻怜细阅，休问望宋墙高，窥韩路隔。”；金蔡松年《水龙吟·梁虎茵家以绛绡作荔枝戏作》词：“青琐窥韩，紫囊赌谢，属狂年少。”；唐李商隐《无题》诗之二：“贾氏窥帘韩掾少，宓妃留枕魏王才。”；明张凤翼《红拂记·掷家图国》：“道我似贾女私窥，忍捐恩负主，应猜做偷香情绪。”；宋史达祖《眼儿媚·代答》词：“期花等月，秦台吹玉，贾袖传香。”；唐杨巨源《独不见》诗：“香传贾娘手，粉离何郎面。”；明许自昌《水浒记·标目》：“红粉多情，青琐偷香巧。剑底风生，激得有家难奔。”；唐乔知之《倡女行》：“昨宵绮帐迎韩寿，今朝罗袖引潘郎。”唐罗虬《比红儿诗》之十七：“当时若是逢韩寿，未必埋踪在贾家。”；明沈鲸《双珠记·遇淫持正》：“不但偷铃，韩寿偷香，方法也是我教他的。”；宋李清照《多丽·咏白菊》词：“韩令偷香，徐娘傅粉，莫将比拟未新奇。”；后蜀欧阳炯《春光好》词：“虽似安仁掷果，未闻韩寿分香。”；唐李瀚《蒙求》：“韩寿窃香，王濛市帽。”；宋杨亿《无题》诗之二：“应知韩掾偷香夜，犹记潘郎掷果年。”；唐史凤《传香枕》诗：“韩寿香从何处传，枕边芳馥恋婵娟。”元王实甫《西厢记》一本二折：“张郎倘得相亲傍，乍相逢厌见何郎粉，看邂逅偷将韩寿香。”；宋周邦彦《风流子》词：“问甚时说与，佳音密耗，寄将秦镜，偷换韩香。”；北周庾信《燕歌行》：“盘龙明镜饷秦嘉，辟恶生香寄韩寿。”','[]',2),
(8500000000000000013,'宁戚饭牛',7,'典故','《吕氏春秋·举难》：“宁戚欲干齐桓公，穷困无以自进，于是为商旅，将任车以至齐，暮宿于郭门之外。桓公郊迎客，夜开门，辟任车，爝火甚盛，从者甚众。宁戚饭牛居车下，望桓公而悲，击牛角疾歌。桓公闻之，抚其仆之手曰：‘异哉!之歌者，非常人也!’命后车载之。”宁戚饭牛1:归，任之以事。
宁子商歌1:后以“宁子商歌”指寒士自求用世之歌。
东门牛1:写才士落魄。
单衣适至骭1:写贤才未遇，生活贫困。
南山戚1:慨叹生不逢时，怀才不遇。
南山粲1:代称《饭牛歌》。
叩牛角1:指寒士怀才求仕。
叩角哀1:喻指怀才不遇、无人赏识的悲哀。
叩角干齐1:指<u>宁戚</u>叩牛角而歌以求<u>齐君</u>的重用。借指寒士怀才求仕。
叹短衣1:谓贤士慨叹怀才不遇、不得世用。
吟白石1:指<u>宁戚</u>饭牛时所唱的歌，借以咏牛。
吹箫扣角1:指志士落难乞援。
夜饭牛1:借指贤士落魄失意。
宁戚击角1:借指才士自求君王重用。
宁戚叩歌1:借指贤士自求用世。
扣角行歌1: 谓贤士未遇、自求用世而发的悲歌。
扣角车前1:<u>宁戚</u>有意在<u>齐桓公</u>车前扣牛角而歌。指乞求出仕。
敲牛角1:指怀才不遇的失意伤叹。
歌牛下1:形容寒士悲歌以求世用。
牛角之歌1:扣牛角而悲歌，借指寒士自求用世。
白石烂1:谓山石洁白耀眼。
舍牛相齐1:谓舍弃贱业而居高位。
逢桓扣角1:谓贤才抓住机会打动君王以求用世。
饭牛1:指贤才屈身于卑贱之事。
饭牛客1:指怀才未遇的寒士。
饭牛怀白石1:喻寒士怀才希求用世。
饭牛歌1:本指<u>宁戚</u>为求得<u>齐桓公</u>重用，扣牛角而唱的歌。后借指寒士自求用世。
饭牛浩叹1:指寒士为怀才不遇而长叹。
饭牛自卖1:谓寒士自求用世。
齐歌入相1:谓唱饭牛歌悟主而得高位。亦用以咏牛。
康衢歌1:借指贤才未遇、自求用世而发的悲歌。
白石粲1:后因用以代称《饭牛歌》。','又《楚辞·离骚》“宁戚之讴歌兮”洪兴祖补注引《三齐记》载其歌曰：“南山矸，白石烂，生不遭尧与舜禅。短布单衣适至骭，从昏饭牛薄夜半。长夜漫漫何时旦?”后因以宁戚饭牛为不遇之士自求用世之典，亦用写怀才不遇，生活困苦。汉王褒《圣主得贤臣颂》：“百里自鬻，宁戚饭牛，离此患也。”唐元稹《放言》诗之四：“宁戚饭牛图底事，陆通歌凤亦无端。”；唐钱起《新丰主人》诗：“客里冯谖剑，歌中宁戚牛。”；唐元稹《酬翰林白学士代书一百韵》：“宁牛终夜永，潘鬓去年衰。”；三国魏曹植《七启》：“采英奇于仄陋，宣皇明于岩穴。此宁子商歌之秋，而吕望所以投纶而逝也。”；唐韩愈《驽骥》诗：“寄言同声子，为我商声讴。”；唐柳宗元《同刘二十八院长述旧言怀》诗：“东门牛屡饭，中散虱空爬。”；金元好问《麦叹》诗：“单衣适至骭，一剑又蒯缑。”；元傅若金《和赵德隆秋夕雨》：“既兴北风叹，亦抱南山戚。”；宋苏轼《乔太博见和复次韵答之》：“为君扣牛角，一咏南山粲。”；宋苏轼《乔太博见和复次韵》：“胡为守故丘，眷恋桑榆暖。为君叩牛角，一咏南山粲。”；明陈子龙《寄赠密之》诗：“叩牛还俊杰，牧豕更贤良。”；晋葛洪《抱朴子·博喻》：“博采之道弘，则异闻毕集;庭燎之耀辉，则奇士叩角。”；宋陆游《雨夜观史》诗：“未能剧论希扪虱，且复长歌学叩辕。”；闽徐夤《依韵赠严司直》：“歌残白石扣牛角，赋换黄金爱马卿。”；明刘基《咏史》之十八：“献玉鄙卞和，扣角羞宁戚。”；唐李郢《重阳日寄浙东诸从事》诗：“元瑜正及从军乐，宁戚谁怜叩角哀?”；《晋书·皇甫谧传》：“或叩角以干齐，或解褐以相秦。”；前蜀韦庄《东游远归》诗：“扣角干名计已疏，剑歌休恨食无鱼。”；唐杜甫《夜》诗：“独坐亲雄剑，哀歌叹短衣。”；元贡性之《牧牛图》诗：“邯郸城头征战息，宁戚徒劳吟白石。”；明王錂《春芜记·说剑》：“屠狗椎埋，混迹五陵年少;吹箫扣角，空悲此日英雄。”；宋陆游《信笔》诗之二：“少年醉眼傲王侯，末路悲歌夜饭牛。”；宋陆游《秋晚书怀》诗之一：“中夜饭牛初上阪，千年化鹤后还乡。”；《晋书·夏侯湛传》：“若乃伊尹负鼎以干汤，吕尚隐游以徼文，傅说操筑以寤主，宁戚击角以要君，此非仆所能也。”；唐李郢《重阳日寄浙东诸从事》诗：“元瑜正及从军乐，宁戚谁怜叩角哀。”唐李瀚《蒙求》：“伊尹负鼎，宁戚叩角。”；唐罗隐《投礼部郑员外启》：“所以宁戚叩歌，不惟长夜;魏舒对策，近至中年。”；宋陆游《与青城道人饮酒作》诗：“不作王猛傲睨坐扪虱，不作宁戚悲歌起饭牛。”；前蜀韦庄《云散》诗：“刘伶避世唯沉醉，宁戚伤时亦浩歌。”；唐许浑《送李文明下第鄜州觐兄》诗：“宁歌还夜苦，宋赋更秋悲。”；唐李白《笑歌行》：“宁武子，朱买臣，扣角行歌背负薪。”；清田茂遇《贫交行》：“君不见古来英雄不用为佣保，叩角行歌石皓皓。”；清钱谦益《次韵答士龙》：“扣角车前唯汝共，观鱼濠上与心违。”；唐李咸用《秋日送严湘侍御归京》诗：“谁听宁戚敲牛角，月落星稀一曲歌。”；唐高適《苦雪》诗之四：“安能羡鹏举，且欲歌牛下。”；唐韩愈《上兵部李侍郎书》：“夫牛角之歌，辞鄙而义拙;堂下之言，不书于传记。”；宋晁补之《满庭芳》词：“却笑当年牛下，轻自许、激烈寒讴。”；宋黄庭坚《次韵无咎阎子常携琴入村》：“明光昼开九门肃，不令高才牛下歌。”；亦以代称《饭牛歌》。唐李白《南奔书怀》诗：“遥夜何漫漫，空歌白石烂。宁戚未匡齐，陈平终佐汉。”；宋陆游《饭牛歌》诗：“人生得饱万事足，舍牛相齐何足言!”；明徐渭《与员外王公书》：“然逢桓扣角，实切于衷;遇盖弹刀，每兴愚抱。”；《汉书·公孙弘卜式儿宽传赞》：“卜式拔于刍牧，弘羊擢于贾竖，卫青奋于奴仆，日碑出于降虏，斯亦曩时版筑饭牛之朋已。”；宋刘克庄《贺新郎·王实之喜余出岭命爱姬歌新词以相劳辄次其韵》词：“彩笔掷还残锦去，愿今生来世无妖梦。且饭犊，莫吞凤。”；元李序《暮行大堤上》诗：“宁知饭牛客，郁郁心如灰。”；宋林景熙《潘山长入括》诗：“饭牛怀白石，访鹤入青田。”；宋陆游《羸卧》诗：“马上原无听鸡句，原头那有饭牛歌?”沈砺《送友北上》诗：“市上已无屠狗辈，车前试唱饭牛歌。”；唐鲍溶《秋思》诗：“徒为击角歌，且惭雕剑字。”；宋陆游《病起镜中见白发此去七十无十寒暑矣偶得长句》：“覆瓿书成空自苦，击辕歌罢遣谁听?”；元陈孚《出门别亲友》诗：“岂无叩牛歌，亦有扪虱谈。”；唐刘沧《汶阳客舍》诗：“思乡每读《登楼赋》，对月空吟叩角歌。”；唐骆宾王《上兖州刺史启》：“方结羡鱼之网，将谣叩角之词。”；唐钱起《秋馆言怀》诗：“日夕云台下，商歌空自悲。”；唐钱起《长安落第作》诗：“不遇张华识，空悲宁戚歌。”宋叶適《题贾俨不忘室》诗：“每识饭牛下，有作宁戚歌。”；清顾炎武《哭归高士》诗：“常为扣角歌，不作穷途哭。”；元刘诜《和张汉英见寿》：“富贵未来歌扣角，畸穷相对赋煎茶。”；唐陆','[]',2),
(8500000000000000014,'射石饮羽',7,'典故','《吕氏春秋·精通》：春秋楚“养由基射先(“兕”之误)，中石，矢乃饮羽，诚乎先也”。按，《韩诗外传》卷六载春秋“楚熊渠子夜行，寝石，以为伏虎，弯弓而射之，没金饮羽。下视，知其为石”。又《史记·李将军列传》载汉“广(李广)出猎，见草中石，以为虎而射之，中石没镞”。射石饮羽1:后以射石饮羽形容用心精诚或勇猛善射。
射虎1:后诗文中常以“射虎”形容英雄豪气。
中石饮羽1:形容力大善射。
将军射虎1:称扬勇武善射。
应弦饮羽1:形容箭术高超有力，武艺高强。
弦声裂石1:形容勇猛善射。
弯弓饮羽1:形容勇猛善射。
控弦贯石1:形容武艺高强，大力善射。
没石饮羽1:形容功力劲健精湛。
没羽之虎1:指大石。
疑虎将1:指<u>汉</u><u>李广</u>等。
石饮羽1:形容勇猛善射。
饮石1:谓箭射入石头。形容弓箭强劲。
饮羽1:箭深入所射物体。形容箭法高超。','；宋刘省斋《沁园春·赠较弓会诸友》词：“行藏事，笑不侯李广，射石夸雄。”；明高启《次韵答朱冠军游城西之作》诗：“醉归共射草中石，笑擘弓弦霹雳鸣。”；宋苏轼《江城子·密州出猎》词：“为报倾城随太守，亲射虎，看孙郎。”；宋辛弃疾《水调歌头·舟次扬州和杨济翁周显先韵》词：“今老矣，搔白首，过扬州……莫射南山虎，直觅富民侯。”；宋辛弃疾《水调歌头·提干李君索余赋秀野绿绕二诗》词：“插架牙签万轴，射虎南山一骑，容我揽须不?”；清邓显鹤《例授修职郎岁贡生邹君墓志铭》：“君试日，以‘中石饮羽’命题，备举熊渠、养由基、李广三事。”；宋吴则礼《江楼令·晚眺》词：“平生正被儒冠误。待闲看，将军射虎。”；清钱谦益《题画二首为傅右君·射虎图》诗：“应弦饮羽目一瞚，拉押雨血摧风毛。”；金元好问《东丹骑射》诗：“血毛不见南山虎，想得弦声裂石时。”；清梁清标《送萧都阃之云中》诗：“却敌吹笳刘越石，弯弓饮羽李将军。”；唐李德裕《与纥扢斯可汗书》：“汉北平太守，材气天下无双，结发事边，控弦贯石，自后子孙多习武略，代为将门。”；朱东润《古文四象论述评》：“明代何、李、李、王之论，自后人视之，诚不免为大言炎炎，然其没石饮羽之技，诚有令人为之舌挢而不下者。”；汉王充《论衡·儒增》：“或言没卫，或言饮羽，羽则卫，言不同耳。”又：“射似虎之石，矢入没卫，若射真虎之身，矢洞度乎?”；汉王充《论衡·儒增》：“儒书之言楚熊渠子、养由基、李广射寝石，矢没卫饮羽者，皆增之也。”；姚雪垠《李自成》三卷三六章：“《汉书》上说的‘没矢’，那‘矢’字是包括箭杆而言，箭羽也在其中。”；唐李白《豫章行》：“精感石没羽，岂云惮险艰?”清钱谦益《丙甲春就医秦淮寓丁家水阁绝句》之二十：“一矢花砖没羽新，诸天塔庙正嶙峋。”；宋王安石《酬王濬贤良松泉二诗·泉》：“没羽之虎行林间，箨龙失职因藏跧。”；唐韩琮《兴平县野中得落星石移置县斋》诗：“几逢疑虎将，应逐犯牛仙。”；南朝梁徐悱《白马篇》：“雄名盛李霍，壮气勇彭韩。能令石饮羽，复使发冲冠。”；唐李白《豫章行》诗：“精感石没羽，岂云惮险艰?”；南朝梁何逊《七召·佃游》：“割玉之刀，饮石之箭，置罗布其一目，罟网周其三面。”；唐崔元翰《奉和登玄武楼观射即事书怀赐孟涉应制》：“饮羽连百中，控弦逾六钧。”','[]',2),
(8500000000000000015,'隋珠弹雀',7,'典故','《庄子·让王》：“今且有人于此，以隋侯之珠弹千仞之雀，世必笑之。是何也?则其所用者重，而所要者轻也。”隋珠弹雀1:原谓用珍珠弹雀，后比喻做事不能权衡轻重，得不偿失。
明珠弹雀1:后以“明珠弹雀”谓得不偿失或使用不当。
弹雀1:喻大才小用，得不偿失。
珠弹1:指以珠弹射鸟雀。','晋葛洪《抱朴子·嘉遯》：“道存则尊，德胜则贵;隋珠弹雀，知者不为。”明张居正《与南台长言中不干外政》：“隋珠弹雀，群虎捕羊，殊可笑也。”；清黄遵宪《九姓渔船曲》：“张罗得鸟虽有缘，将珠抵鹊宁非误?”；清尤侗《饮高念东太史斋赋呈》诗：“谁忍荆玉刖，共惜隋珠弹。”；宋程正同《思越人·题挟弹人簇》词：“曾把隋珠抵鹊来，拓弓花下不虚开。醉馀戏把行人弹，堪笑齐王谩筑台。”；唐李白《送窦司马贬宜春》诗：“赵璧为谁点?隋珠枉被弹。”；《封神演义》十三回：“道兄，好好把那哪吒叫他出来见我，还是好面相看，万事俱息;若道兄隐护，只恐明珠弹雀，反为不美。”；清黄宗羲《〈淮安戴氏家谱〉序》：“天下之书，最不可信者有二：郡县之志也，氏族之谱也。郡县之志，狐貉口中之姓氏，子孙必欲探而出之，始以贿赂，继之恫喝。董狐、南史之笔，岂忍弹雀?”；明李东阳《送邵文敬知思南序》：“千金之剑不可锥履，径寸之珠不可弹爵。”；唐骆宾王《在江南赠宋五之问》诗：“弹随空被笑，献楚自多伤。”；唐骆宾王《帝京篇》：“侠客珠弹垂杨道，倡妇银钩采桑路。”','[]',2),
(8500000000000000016,'杯弓蛇影',7,'典故','汉应劭《风俗通义·怪神》：“予之祖父郴为汲令，以夏至日请见主簿杜宣，赐酒。时北壁上有悬赤弩，照于杯中，其形如蛇。宣畏恶之，然不敢不饮。其日便得胸腹痛切，妨损饮食，大用羸露，攻治万端，不为愈。后郴因事过至宣家，窥视，问其变故，云畏此蛇，蛇入腹中。郴还听事，思惟良久，顾见悬弩，必是也。则使门下史将铃下侍徐扶辇载宣于故处设酒，杯中故复有蛇。因谓宣：‘此壁上弩影耳，非有他怪。’宣意遂解，甚夷怿，由是瘳平。”类似故事又见《晋书·乐广传》。杯弓蛇影1:后因以杯弓蛇影喻疑神疑鬼，自相惊扰。
杯蛇鬼车1:后以指因疑虑惊恐而导致幻觉中出现的怪异之物。
市虎弓蛇1:喻指流言与怀疑。
广客蛇1:指胸腹之疾。
广客蛇影1:指疑神疑鬼，自相惊扰。
弓蛇影1:喻指疾病。
弓蛇杯酒1:借指虚幻之物。
弓蛇薏苡1:喻指虚妄无据、疑神疑鬼之事。
弓蛇误1:指人对事物的错觉。
弩影1:借指胸腹之疾。
影中蛇1:指虚惊之事。
影蛇1:比喻虚幻之事。
影里弓蛇1:喻疑神疑鬼。
影里杯蛇1:形容怀疑多端，自相惊扰。
悬蛇疾1:谓疑心病。
映弩1:形容心存疑虑，自相困扰。
杯中影1:喻指疾病。
杯底逢蛇1:指遇到令人疑惧的怪事。
杯弓市虎1:谓捕风捉影，疑虑重重，自相惊扰。
杯里无蛇1:谓无疑无惧，不惊不扰。
楚弓遗影1:比喻因某事造成的疑惧心理。
清樽照画蛇1:谓武臣赋闲，饮酒自适。
画蛇杯1:喻自疑自惊。
疑蛇1:借指引起疑虑之事。
移杯失画蛇1:比喻病愈。
酒中蛇1:指疾病。
酒中蛇2:亦指虚幻之事。
酒误蛇1:指生病。
雕弓照影1:指遭谗见弃而心有余悸。
雕弓蛇1:指疑惧虚惊。','清纪昀《阅微草堂笔记·如是我闻四》：“况杯弓蛇影，恍惚无凭，而点缀铺张，宛如目睹。”；明唐顺之《答王龙溪郎中书》：“若于此处稍参不破，则昔人所谓壁间蛇影，足以生疑而致病。”；明冯惟敏《折桂令·阅报除名》曲：“歧路亡羊，塞翁失马，弓影成蛇。”；清沈复《浮生六记·闺房记乐》：“余知沧浪亭畔素有溺鬼……不禁毛骨皆栗，急闭窗，携酒归房，一灯如豆，罗帐低垂，弓影杯蛇，惊神未定。”；明刘炳《鄱城归舟》诗：“弓影浮杯疑老病，鸡声牵梦动离愁。”；明陆采《怀香记·闻香致疑》：“疑事最关心，弓蛇杯影参。”；清无名氏《十醋记·起兵》：“我略沾濡御辇龙车，满朝臣杯影弓蛇。”；《花月痕》四五回：“杯影蛇弓魔入幻，帷灯匣剑鬼生疑。”；明归有光《与徐子与》：“以彼机穽可畏，不胜杯蛇之疑。”；《花月痕》五回：“杯蛇幻影，鬼蜮含沙。萦愁绪以回肠，蔓牵瓜落;拭泪珠而洗面，藕断丝长。”；《红楼梦》八九回：“一片疑心，竟成蛇影。”；《红楼梦》八九回回目：“人亡物在公子填词，蛇影杯弓颦卿绝粒。”；清纪昀《阅微草堂笔记·如是我闻四》：“况蛇杯弓影，恍惚无凭。”；《水浒传》九五回：“况我兵惊恐，凡杯蛇鬼车，风兵草甲，无非撼志之物。”；《世无匹》十一回：“市虎弓蛇，铄金销骨，舌端何处辨雌黄?”；宋刘筠《属疾》诗：“暂困秦王痔，无疑广客蛇。”；唐李瀚《蒙求》：“广客蛇影，殷师牛斗。”；明袁宏道《病中和黄道元至日禅寺梦愁诗》：“消愁莫问弓蛇影，对境聊观梦幻身。”；明杨珽《龙膏记·藏春》：“似江皋珠佩相投，又谁知是弓蛇杯酒无凭。”；清蒋士铨《水调歌头·沈维涓太守席上感事》词：“眼中咄咄怪事，谁可合时宜，几许弓蛇薏苡。”；元谢应芳《顾仲瑛临濠惠书诗代简》：“酒杯已辨弓蛇误，药杵无劳玉兔将。”；南朝梁简文帝《卧疾》诗：“沈疴类弩影，积弊似河鱼。”；明汤显祖《牡丹亭·闻喜》：“你香魂逗出了梦儿蝶，把亲娘肠断了影中蛇。”；元汪元亨《朝天子·归隐》曲：“酒杯中影蛇，枕头上梦蝶，二十载花开谢。”；清李渔《答王子立山人问病兼释致病之疑》诗：“良朋爱我翻成惑，影里弓蛇未是真。”；清袁龙《醉花阴·四十初度自嘲》套曲：“那更是烽火连年刚历劫，常似那影里杯蛇。”；唐苏颋《蜀城哭台州乐安少府》诗：“白头还作尉，黄绶固非才。可叹悬蛇疾，先贻问𫛳灾。”；北周庾信《卧疾穷愁》诗：“留蛇常疾首，映弩屡惊心。”；唐杜甫《风疾舟中伏枕书怀》诗：“疑惑尊中弩，淹留冠上簪。”尊，一本作“樽”。；明李东阳《次韵体斋病起见寄二首》之二：“疑蛇已辨杯中影，病鹤长怀海上心。”；宋苏轼《次韵钱舍人病起》：“床下龟寒且耐支，杯中蛇气未应衰。”；清赵翼《七十自述》诗：“水中见蟹犹生怒，杯底逢蛇得不惊。”；詧盦《学界风潮记·天津商学界之活动》：“同时传来上海有罢市之说，以致杯弓市虎，危机伺伏，人心恐惶，险状万分。”；清钱谦益《送马巽倩归会稽》诗：“杯里无蛇我所悉，水中有蟹哪能平?”；明许自昌《水浒记·感愤》：“楚弓遗影，楚弓遗影，虑祸甚关心。我起身得急了，把钊文袋遗失在房内，那金子倒也不打紧，晁保正与我那封书怎么泄漏得的!”；宋苏轼《书刘君射堂》诗：“而今白首闲骢马，只有清樽照画蛇。”；宋辛弃疾《水调歌头·再用韵呈南涧》词：“笑年来，蕉鹿梦，画蛇杯。”；北周庾信《周大将军赵公墓志铭》：“盗乌悬察，疑蛇立辨。”；唐李端《酬秘书元丞郊园卧疾见寄》诗：“撤枕销行蚁，移杯失画蛇。”；明高启《次韵杨礼曹雨中卧疾》之二：“何事一春频谒告，只应来辨酒中蛇。”；元乔吉《卖花声·悟世》曲：“富贵三更枕上蝶，功名两字酒中蛇。”；唐卫象《伤李端》诗：“人去门栖𫛳，灾成酒误蛇。”；宋辛弃疾《水调歌头·严子文同傅安道和盟鸥韵和以谢之》词：“雕弓挂壁无用，照影落清杯。”；宋辛弃疾《沁园春·城中诸公载酒入山余不得以止酒为解遂破戒一醉再用韵》词：“君言病岂无媒，似壁上雕弓蛇暗猜。”','[]',2),
(8500000000000000017,'樗栎',7,'典故','《庄子·逍遥游》：“吾有大树，人谓之樗，其大本拥肿而不中绳墨，其小枝卷曲而不中规矩，立之涂，匠者不顾。”又《人间世》：“匠石之齐，至于曲辕，见栎社树……曰：‘散木也，以为舟则沉，以为棺椁则速腐，以为器则速毁，以为门户则液樠，以为柱则蠹。是不材之木也，无所可用。’”樗栎1:后因以樗栎比喻劣材，无用之材。
樗栎2:亦用为自谦之词。
樗铅1:后因以“樗铅”比喻材劣不堪用。常为自谦之词。
不才樗1:喻劣材，无用之材。
寿栎1:老麻栎树。喻老而无用之材。用作谦词。
寿樗1:老臭椿木。喻老而无用之材。多用为谦词。
山中散木1:喻无用之材。
山樗1:喻无用之材。多用为谦词。
庄樗1:喻无用之材。因该典源自《庄子》，故称。
拥肿材1:指劣材，无用之材。
散木1:散木，本谓无用之木，多喻无才之人或全真养性、不为世用之人。
散材1:谓无用之木。多喻无用或不为世用之人。
散栎1:喻无用之人。
无材老樗1:喻无用之材。多用为谦词。
有樗不才1:喻指无用之人。多用为谦词。
木尽天年为不才1:指处世无能而得以全身的哲理。
材成拥肿1:谓成为无用之材。
樗散1:樗木材劣，多被搁置。比喻不为世用，投闲置散。
樗散2:亦用作谦词。
樗散材1:喻无用之材。
樗朽1:腐朽的樗木。喻无用之人。常用为自谦之词。
樗材1:喻无用之材。多用为谦词。
社木樗1:里中不材之木。喻无用之材。
社栎1:里中不材之木。喻无所可用。
社栎2:亦喻不材之人安全高寿。
社栎非材1:喻指无用之材。
类樗1:谓像樗。形容无才。
蟠木1:指盘曲而难以为器的树木。喻无用之材。亦用为自谦之辞。
蟠木朽株1:盘曲之木，朽烂之株。喻无用之材。亦用为自谦之辞。
散樗1:不成材的樗木。比喻无用之人。常用作自谦之词。
曲辕树1:喻因平庸而远祸者。','唐欧阳詹《寓兴》诗：“桃李有奇质，樗栎无妙姿。”；清徐宗麟《辞征》诗：“天纵深林老栎樗，惊看云壑驻安车。”；《陈书·蔡景历传》：“《云咸》斯奏，自辍《巴渝》，杞梓方雕，岂盼樗枥。”；《三国演义》三六回：“庶曰：‘某樗栎庸材，何敢当此重誉。’”；宋苏轼《和穆父新凉》：“常恐樗栎身，坐缠冠盖蔓。”；唐沈亚之《上使主第三书》：“诚以亚之樗铅之材，处不当任可逃，遭此众辱宜矣。”；清王夫之《后雁字诗》：“鲲鹏聊志怪，终是不才樗。”；宋陆游《吾年过八十》诗之二：“斧斤遗寿栎，云海寄冥鸿。”；清梁章鉅《归田琐记·张孟词贡士》：“华暂芬优钵，材偏耻寿樗。”；宋张炎《风入松·听琴中弹樵歌》词：“颇笑山中散木，翻怜爨下劳薪。”；宋无名氏《六州歌头·寿徐枢密》词：“想公门桃李，应不弃山樗，愿借嘘枯。”；宋杨亿《受诏修书述怀感事》诗：“虚名同郑璞，散质类庄樗。”；唐刘禹锡《洛中酬福建陆判官见赠》诗：“潦倒声名拥肿材，一生多故苦邅回。”；北周庾信《奉和法筵应诏》：“羁臣从散木，何以预中天?”唐戴叔伦《酬赠张众甫》诗：“野人无本意，散木任天材。”；唐施肩吾《玩手植松》诗：“今日散材遮不得，看看气色欲凌云。”宋苏轼《东山浮金堂戏作》诗：“我子乃散材，有如木轮囷。”；明唐顺之《天宁寺尘外楼》诗：“已甘散栎终年计，耻逐冥鸿万里腾。”；唐白居易《林下樗》诗：“知我无材老樗否，一枝不损尽天年。”；宋方岳《沁园春·和林教授》词：“子盍观夫，商丘之木，有樗不才。”；唐白居易《闲卧有所思》诗之二：“虫全性命缘无毒，木尽天年为不才。”；清董元恺《沁园春·青墩松》词：“叟号支离，材成拥肿，雨溜风吹饱雪霜。”；唐杜甫《送郑十八虔贬台州司户》诗：“郑公樗散鬓成丝，酒后常称老画师。”；《艺文类聚》卷三六引晋戴逵《闲游赞》：“栎散之质，不以斧斤致用。”《魏书·宗钦传》：“伊余栎散，才至庸微。遭缘幸会，忝与枢机。”；宋司马光《为庞相公谢官表》：“何意天恩横被，宸睠曲成，猥抡樗散之才，专委栋隆之任。”；宋李纲《建炎行》：“末言樗散材，初不堪梁柱。鼎颠将覆𫗧，栋桡必倾宇。”；明张四维《双烈记·策封》：“不意朝庭垂念老臣，复有封爵，樗朽何当，不免再整冠裳。”；清龚自珍《己亥杂诗》之五三：“半生中外小回翔，樗丑翻成恋太阳。挥手唐朝八司马，头衔老署退锋郎。”；元王逢《得尚书汪公凶问》诗：“樗材荷推奖，思报辑遗编。”；宋岳珂《桯史·周益公降官》：“臣有愧积中，无阶报上。省諐田里，视桑荫之几何;托命乾坤，比栎材而知免。”；姚锡钧《答亚子》诗之一：“我侪社木樗，于世良鲜补。”；宋李纲《谢琼林苑赐御宴表》：“伏念臣社栎散材，康瓠小器，力学粗知于忠义，逢时窃意于功名。”；宋陆游《园中作》诗：“万事谁能料，社栎老不僵。”又《野兴》诗：“社栎原当寿，江鸥岂易驯?”；五代徐铉《奉和宫傅相公怀旧见寄四十韵》：“云龙得路须腾跃，社栎非材合弃捐。”；明袁宏道《病起》诗：“不去终惭鹄，无才合类樗。”；唐孟郊《山老吟》：“蟠木为我身，始得令天年。”；唐钱起《山中春仲寄汝上王恒颍川沈冲》诗：“隐者守恬泊，春山日深净。谁知蟠木材，得性无人境。”；唐骆宾王《上李上常伯启》：“宾王蟠木朽株，散樗贱质，墙面难用，灰心易寒。”；唐虞世南《奉和幸江都应诏》“多幸沾行苇，无庸类散樗。”；北周庾信《和张侍中述怀》“虽欣曲辕树，犹惧雕陵鹊。”','[]',2),
(8500000000000000018,'黄河千年一清',7,'典故','《左传·襄公八年》：“子驷曰：《周诗》有之曰：‘俟河之清，人寿几何?’”晋王嘉《拾遗记·高辛》：“又有丹丘千年一烧，黄河千年一清，至圣之君，以为大瑞。”黄河千年一清1:后因以黄河千年一清指圣君在世的升平之瑞或喻时机难遇。
河清社鸣1:后因以“河清社鸣”为太平祥瑞的象征。
俟河之清1:谓等待<u>黄河</u>水由浊变清。比喻期望之事不可能实现或极难实现。
千年一清1:指吉祥的征兆。
河清1:喻指圣君临世，天下太平。
河清2:亦比喻时机难遇或极言历时之久。
河清人寿1:极言人之长寿。
河清圣1:指政治清明的帝王。
河清难俟1:比喻时久难以等待。
黄河清1:指政清君明、天下太平的祥瑞之兆。
黄河清2:亦喻指极难得、罕见的事。
河清三日1:后因以“河清三日”为升平祥瑞的预兆。','南朝梁费昶《行路难》诗：“黄河千年始一清，微躯再逢永无议。”；北周庾信《奉和平邺应诏》：“阵云千里散，黄河一代清。”；宋王禹偁《缴连寿宁节功德疏表》：“河清社鸣，千载启兴王之道;天长地久，万邦倾祝圣之心。”；汉张衡《思玄赋》：“系曰：天长地久岁不留，俟河之清祗怀忧。”；唐李白《西岳云台歌送丹丘子》：“荣光休气纷五彩，千年一清圣人在。”；唐张说《东都酺宴》诗：“人间知几代，今日见河清。”清顾炎武《五十初度时在昌平》诗：“远路不须愁日暮，老年终自望河清。”；唐张说《季春下旬诏宴薛王山池序》：“河清难得，人代几何?”明朱有燉《香囊怨》二折：“凭着我心志诚，身端正，便化作望夫石也，坚等到河清。”；清顾贞观《金缕曲·寄吴汉槎宁古塔以词代书》词之二：“但愿得、河清人寿。归日急翻行戍稿，把空名、料理传身后。”；唐韩偓《感事三十四韵》：“虽遇河清圣，惭非岳降贤。”；清钮琇《觚賸·序赋创格》：“然则人寿几何，河清难俟。”；清孔尚任《桃花扇·先声》：“蓂荚发，芝草生，海无波，黄河清。”；《宋史·包拯传》：“拯立朝刚毅，贵戚宦官，为之敛手，闻者皆惮之。人以包拯笑比黄河清。”；明张居正《承天大志纪赞·龙飞纪》：“吾圣主始生，此河清者三日。黄河清，圣人出，今果然矣。”','[]',2),
(8500000000000000019,'屈原沉湘',7,'典故','《史记·屈原贾生列传》载：楚国令尹子兰“使上官大夫短屈原于顷襄王，顷襄王怒而迁之。屈原至于江滨……乃作《怀沙》之赋”。“于是怀石遂自沉汨罗以死”。汨罗江乃湘江支流。屈原沉湘1:后因以谓忠贤之士含冤谪死。
湘累1:后因以“湘累”指<u>屈原</u>。
湘累2:亦借指被贬黜的人。
怀沙负石1:谓因忠愤抱石投水而死。
投汨1:指忠贤含冤自沉。
歌楚吊湘累1:谓追思忠直爱国之士。
沉湘1:指忠贤不为浊世所容，含冤而自戕。
湘累怨1:指忠鲠遭谗之悲。','唐邵谒《放歌行》：“屈原若不贤，焉得沉湘水?”；唐韩愈《陪杜侍御游湘西两寺独宿有题一首因献杨常侍》诗：“静思屈原沉，远忆贾谊贬。”；元谢应芳《绝句》：“屈原沉江死，扬雄投阁生。”；汉王褒《九怀·尊嘉》：“伍胥兮浮江，屈子兮沉湘。”；唐李贺《箜篌引》：“屈平沉湘不足慕，徐衍入海诚为愚。”；唐柳宗元《汨罗遇风》诗：“南来不作楚臣悲，重入修门自有期。”；元张鸣善《脱布衫过小梁州》曲：“悼后世，追前辈，对五月五日，歌楚些，吊湘累。”郭沫若《李白与杜甫·杜甫的地主生活》：“屈原是赴湘水支流而溺死的，古人称之为湘累。”；宋陈与义《晚步湖边》诗：“楚累经行地，处处余《离骚》。”；宋苏轼《次韵张舜民自御史出倅虢州留别》：“玉堂给札气如云，初起湘累后佩银。”；晋葛洪《抱朴子·名实》：“此古人之所以怀沙负石，赴流鱼葬，而不堪与之同世也已矣。”；唐李白《书情赠蔡舍人雄》诗：“投汨笑古人，临濠得天和。”；元张鸣善《脱布衫过小梁州》曲：“悼后世，追前辈，对五月五日，歌楚些，吊湘累。”；唐郑谷《蜀江有吊》诗：“折槛未为切，沉湘何足悲!”；清孔尚任《桃花扇·沉江》：“那滚滚雪浪拍天，流不尽湘累怨。”','[]',2),
(8500000000000000020,'青蝇营营',7,'典故','《诗·小雅·青蝇》：“营营青蝇，止于樊。岂弟君子，无信谗言。营营青蝇，止于棘。谗人罔极，交乱四国。营营青蝇，止于榛。谗人罔极，构我二人。”郑玄笺：“蝇之为虫，污白使黑，污黑使白，喻佞人变乱善恶也。”青蝇营营1:后以青蝇营营形容奸佞进谗，加害忠良，诽谤君子。
营蝇斐锦1:后因以“营蝇斐锦”比喻谗人颠倒黑白，诽谤诬陷，入人于罪。
止棘1:谓遭受谗谤。
白璧青蝇1:比喻小人用谗言诬害好人。
苍蝇1:比喻进谗言的小人。
苍蝇间白黑1:喻小人进谗，混淆是非，陷害好人。
谗蝇1:比喻谗人。
青蝇1:指谗佞。
青蝇相点，白璧成冤1:比喻小人用谗言诬害好人。
青蝇点素1:后以“青蝇点素”谓小人用谗言诬害好人。
罔极21:指谗言或谗人。','清黄鷟来《行路难》诗：“青蝇营营变白黑，淮阴钟室多烦冤。”；明李东阳《河阳战》诗：“营蝇斐锦难为忠，空中愤死田神功。”；唐吴融《赴阙次留献荆南成相公三十韵》诗：“痛知遭止棘，频叹委飘蓬。”；清钱谦益《封监察御史谢府君墓志铭》：“铙歌鼓吹，戎车在门。恺乐方献，谗言孔兴。君曰何伤，白璧青蝇。”清吴伟业《悲歌赠吴季子》：“词赋翩翩众莫比，白璧青蝇见排抵。”；唐高適《饯宋八充彭中丞判官之岭外》诗：“若将除害马，慎勿信苍蝇。”；三国魏曹植《赠白马王彪》诗：“苍蝇间白黑，谗巧令亲疏。”；宋宋庠《伤死马》诗：“故蹄休践雪，朽骨讵酬金。附尾谗蝇散，投鞍啮鼠侵。”；《楚辞·刘向〈九叹·怨思〉》：“若青蝇之伪质兮，晋骊姬之反情。”王逸注：“青蝇变白使黑，变黑使白，以喻谗佞。”；唐陈子昂《宴胡楚真禁所》诗：“青蝇一相点，白璧遂成冤。”；《后汉书·杨震传》：“故太尉震，正直是与，而青蝇点素，同兹在藩。”；清王士禛《元祐党籍碑》诗：“从来青蝇乱白黑，三代遗直今如弦。”；《艺文类聚》卷二六引三国魏丁仪《厉志赋》：“疾青蝇之染白，悲小弁之靡托。”；唐牟融《寄永平友人》诗之二：“青蝇点玉原非病，沧海遗珠世所嗟。”；明张居正《答司成姜凤阿书》：“昔在词林，宿承休问，中见青蝇点璧，每切不平。”；明冯惟敏《朝天子·感述》曲：“鄙夫，利徒，今古无其数。青蝇白璧岂能污?”；《后汉书·李杜传赞》：“道亡时晦，终离罔极。”唐刘禹锡《上杜司徒书》：“罔极泰甚，古今同途。”','[]',2),
(8500000000000000021,'龙伯钓鳌',7,'典故','《列子·汤问》：“〔勃海之东有五山〕而五山之根无所连著，常随潮波上下往还，不得暂峙焉。仙圣毒之，诉之于帝。帝恐流于西极，失群圣之居，乃命愚彊使巨鳌十五举首而戴之，迭为三番，六万岁一交焉，五山始峙。而龙伯之国有大人，举足不盈数步而暨五山之所，一钓而连六鳌，合负而趣归其国，灼其骨以数焉。于是岱舆、员峤二山流于北极，沈于大海。”龙伯钓鳌1:后以龙伯钓鳌指此传说，并喻超凡豪迈的行动举止。
钓鳌客1:后以“钓鳌客”指有远大抱负而豪迈不羁的人。
鳌抃1:后以“鳌抃”形容欢欣鼓舞。
一钓十五鳌1:喻豪迈的举止，非凡的气概。
三山巨鳌1:指神话中头顶三神山的海上巨龟。亦喻指海上岛屿。
六鳌1:指传说中负载五仙山的六只大龟。借指担负重任者。
冠三山1:比喻担负重任。
冠山鳌1:比喻所负重任。
冠鳌1:形容非凡之处。
巨鳌冠山1:指神话中巨鳌头顶仙山使之稳定在海上。借指力大无穷。
戴山鳌1:指神话中背负神山的海上灵龟。借指担负重任之材。
海上钓鳌1:借指有大志气，大作为。
神山鳌戴1:喻指海上岛屿的奇观。
神鳌1:指神话中头顶(一说背负)仙山的海上巨龟。
连六鳌1:形容善钓。
钓鳌1:喻抱负远大或举止豪迈。
鳌冠1:美喻海上岛屿。
鳌峰1:传说中海上仙山。亦形容江海上的岛屿。
鳌戴三山1:比喻负荷重任。
鳌戴方壶1:传说中的海上仙山。形容海上岛屿。
鳌洲1:传说中海上仙山。亦借指东海。
鳌海1:指大海。
鳌背1:借指大海。
鳌背三山1:借指海岛上的山。
鳌背楼台1:美喻海上岛屿。
鳌负三山1:指海上的奇景异观。
鳌钓1:比喻非凡举止或远大抱负。
龙伯1:指传说中<u>龙伯国</u>巨人。
龙伯2:亦喻指渔者。
龙伯国人1:喻巨人。','唐李白《大猎赋》：“龙伯钓其灵鳌，任公获其巨鱼。”清丘逢甲《送谢四之桃源》诗之二：“龙伯钓鳌后，三山今无存。”；李详《纫秋归自京师过访未值寄此奉问》诗：“嘉客自回龙伯钓，残科已占兔儿年。”；宋张元幹《水调歌头·追和》词：“举手钓鳌客，削迹种瓜侯。”叶玉森《一岛》诗：“不知何处钓鳌客，来此从荒辟蜃楼。”；清丘逢甲《仙屏中丞见和前诗感事述怀叠韵奉答》之二：“上书曾陨孤臣泪，怀刺新投钓客名。”；唐翁洮《赠方干先生》诗：“独向若耶溪上住，谁知不是钓鳌人。”元关汉卿《单刀会》二折：“本是个钓鳌人，倒做了扶犁叟。”；元关汉卿《陈母教子》二折：“二哥哥枉展污了你那折桂攀蟾的钓鳌手。”元无名氏《九世同居》二折：“吾心已休，甘心退守，老却当年钓鳌手。”；宋陆游《瑞庆节贺表》：“鳌抃嵩呼，共效寿祺之祝。”；唐李群玉《洞庭风雨》诗之二：“水将天共黑，云与浪争高。羽化思乘鲤，山漂欲抃鳌。”；清黄遵宪《感事》诗之三：“忽然大陆出平地，一钓手得十五鳌。”；唐李峤《海》诗：“三山巨鳌涌，万里大鹏飞。”；唐李白《登高丘而望远海》诗：“六鳌骨已霜，三山流安在?”明夏完淳《代人赠镇府》诗：“六鳌还镇澥，八柱独承天。”；元郝经《原古上元学士》诗：“昂首冠三山，俯瞰旭日晟。陆海辟文源，生民共涵泳。”；唐李群玉《龟》诗：“冠山期不小，铸印事宁虚。”此为咏龟。；清赵翼《七十自述》诗之九：“头衔已失冠山鳌，犹忝西清供奉劳。”；唐刘禹锡《浙西李大夫述梦四十韵并浙东元相公酬和斐然继声》诗：“南台资謇谔，内署选风骚。羽化如乘鲤，楼居旧冠鳌。”；唐李白《大鹏赋》：“〔大鹏〕猛势所射，徐风所吹……巨鳌冠山而却走，长鲸腾海而下驰。”；清丘逢甲《再叠前韵奉答仙屏中丞》之一：“无计消愁且买春，戴山鳌竟失三神。”；清丘逢甲《春尽夜次韵寄答实甫》之二：“戴鳌已叹沉三岛，嬉凤安能陋九夷?”；唐归仁《悼罗隐》诗：“管中窥豹我犹在，海上钓鳌君也沉。”；清赵怀玉《金缕曲·喜晤杨遵路》词：“澎湖东去涛千派，尽容看、扶桑日出，神山鳌戴。”；元王和卿《拨不断·大鱼》曲：“胜神鳌，卷风涛，脊背上轻负着蓬莱岛。”；宋刘攽《和罗著作渔翁》：“龙伯国人连六鳌，二山漂流不能止。”；唐张友正《钓鳌赋》：“谓优游以无穷，何瞬息而连六。”明杨基《钓鳌海客歌》：“重施龙伯国人技，一展丝纶连六归。”；唐李白《赠临洺县令皓弟》诗：“钓水路非远，连鳌意何深?”；唐李商隐《异俗》诗之二：“点对连鳌饵，搜求缚虎符。”；唐李白《悲清秋赋》：“临穷溟以有羡，思钓鳌于沧洲。”南唐陈陶《渡浙江》诗：“静寇思投笔，伤时欲钓鳌。”；清袁枚《春日杂吟》之五：“不曾闲着丝纶手，何必蓬山钓六鳌?”；明陈子龙《登神山仙馆同惠朗胜时作》诗之一：“鳌冠迢递海天分，缑岭笙歌彻夜闻。”；清屈大均《广东新语·灵洲山》：“西北二水之来，至广州，先以灵洲为砥柱，次以海印，次以禺珠，皆在水中央，所谓鳌峰也。”；唐王勃《拜南郊颂》序：“负鳌丘而峻壁，据鼋壑而深沟。”；北周庾信《谢赵王赉犀带等启》：“花开四照，唯见其荣;鳌戴三山，深知其重。”；唐司空图《淮西》诗：“鳌冠三山安海浪，龙盘九鼎镇皇都。”；清李调元《石匠行》：“自吾祖父供此役，日往高岩新度量。车辇夫扛百不停，巍巍鳌戴万人仰。”；元大䜣《送何彦敬赴山东宪幕》诗：“霆奔群蛰奋，鳌负五山浮。”；唐元稹《有酒十章》诗之八：“海苍苍兮路茫茫……鲸归穴兮渤溢，鳌载山兮低昂。”；宋沈遘《次韵和孙少述润州望海楼》：“北固峨峨铁瓮完，京口浩浩海门连。鹏抟羊角来天外，鳌戴方壶献几前。”；唐黄滔《秋色赋》：“上澄鹊汉以清浅，东莹鳌洲而渺弥。”唐皎然《杂兴》诗之二：“鹤驾何冥冥，鳌洲去浩浩。”；唐黄滔《水殿赋》：“还如玉关，控鳌海以峥嵘;稍类云楼，拔蜃江而耸峙。”；唐刘禹锡《送源中丞充新罗册立使》诗：“烟开鳌背千寻碧，日浴鲸波万顷金。”；元张翥《寄观志能照磨》诗：“鳌背三山最上峰，美人手把玉芙蓉。”；唐罗隐《寄窦泽处士》诗之二：“鳌背楼台拂白榆，此中槎客亦踟蹰。”；唐孟郊《石淙》诗之五：“飘飘鹤骨仙，飞动鳌背庭。”；宋陆游《泛三江海浦》诗：“鳌负三山碧海秋，龙骧万斛放翁游。”；唐元稹《酬独孤二十六送归通州》诗：“鳌钓气方壮，鹘拳心颇尊。”明李贽《又书使通州诗后》：“公独鳌钓通海，视等乡邻，不一引手投足，又何其忍耶!”；唐张说《入海》诗之二：“龙伯如人类，一钓两鳌连。”；清赵翼《晚泊》诗：“远火晚回龙伯驾，荒芦寒打雁奴更。”；民意《告非难民生主义者》：“是又梁氏所谓犹以千百之僬侥国人，与一二之龙伯国人抗，蔑有济也。”','[]',2),
(8500000000000000022,'阿戎',7,'典故','南朝宋刘义庆《世说新语·雅量》：“王戎七岁，尝与诸小儿游。看道边李树多子折枝。诸儿竞走取之，唯戎不动。人问之，答曰：‘树在道边而多子，此必苦李。’取之信然。”阿戎1:后因以阿戎美称他人之子。
阿戎可语1:后因以“阿戎可语”谓家有贤子。
阿戎碌碌1:后因以“阿戎碌碌”指平庸自安或谦称自己无所作为。','唐王维《送李员外贤郎》诗：“借问阿戎父，知为童子郎。”；宋李曾伯《摸鱼儿·壬子初度》词：“休直似，文渊、定远空怀土。阿戎可语。待乞得身还，屏伊世累，甘受作诗苦。”；宋方岳《八六子·子寿父》词：“阿戎碌碌功名。但要无灾无难，何曾著公卿。”</p></div>\\n','[]',2),
(8500000000000000023,'鸿渐',7,'典故','《易·渐》：“初六，鸿渐于干”，“六二，鸿渐于磐”，“九三，鸿渐于陆”，“六四，鸿渐于木”，“九五，鸿渐于陵”。鸿渐1:本谓鸿鹄飞翔从低到高，循序渐进，后因以鸿渐比喻仕宦的升迁。
鸿渐2:亦喻指仕进于朝的贤人。
鸿磐1:后因以“鸿盘”谓稍有升迁即安于其位。
鸿逵1:后遂以“鸿逵”称贤达君子的高超举止。
鸿渐之仪1:后以“鸿渐之仪”比喻居高位而有才德，被人尊重或堪为楷模。
渐鸿陆1:喻仕进。
鸿渐于干1:指始入仕途。
鸿陆11:指高位。','汉班固《幽通赋》：“皇十纪而鸿渐兮，有羽翼于上京。”宋陆游《答发解进士启》：“将鸿渐于天庭，始龙骧于学海。”；《后汉书·蔡邕传》：“君臣穆穆，守之以平;济济多士，端委缙綎。鸿渐盈阶，振鹭充庭。”；明高濂《玉簪记·促试》：“你是瑚琏虹霓，怎做狐首鸿磐，休恋燕友莺俦。”；唐李白《崇明寺佛顶尊胜陀罗尼幢颂》：“方将和阴阳于太阶，致吾君于尧舜;岂徒闭阁坐啸，鸿盘二千哉!”王琦注：“鸿盘二千，谓以二千石之职，为宴安之地也。”；明孙仁孺《东郭记·人之所以求富贵利达者》：“一般儿相投鱼水，转眼的勋名俊伟，羡高风鸿逵可仪，一任俺齐人骥尾攀跻。”；明张居正《答南列卿陈我度书》：“幸惟俯谅，天衢广阔，鸿渐之仪，岂有量哉!”；《汉书·叙传上》：“皇十纪而鸿渐兮，有羽仪于上京。”颜师古注引张晏曰：“成帝时，班況女为倢伃，父子并在京师为朝臣也。”唐韩愈《燕喜亭记》：“智以谋之，仁以居之，吾知其去是而羽仪于天朝也不远矣。”；《隋书·崔赜传》：“谬齿鸿仪，虚班骥阜。”；明汤显祖《奉举主刘中丞开府闽中》诗：“俪景渐鸿陆，扬蕤觌紫宸。”；宋叶適《次韵韩仲止》：“林迷久已随甡鹿，磬止何曾有渐鸿。”明吴本泰《帝京篇》：“渐鸿虽可仪，羔羊不闻赞。”；明海瑞《与博白大尹林仲和书》：“回思子平日节概，痴人说梦，尚是鸿渐于干而已，无足为异。”；北周庾信《小园赋》：“不雪雁门之踦，先念鸿陆之远。”《全唐文》卷九九四《珍州荣德县丞梁君墓志铭》：“鸿陆初渐，龙门早升。”','[]',2),
(8500000000000000024,'宣室召',7,'典故','《汉书·贾谊传》：“后岁余，文帝思谊，征之。至，入见，上方受釐，坐宣室。上因感鬼神事，而问鬼神之本。谊具道所以然之故。至夜半，文帝前席。既罢，曰：‘吾久不见贾生，自以为过之，今不及也。’”《史记·屈原贾生列传》亦载。宣室召1:后因以宣室召喻指君王召用才臣。
前膝1:后以“前膝”谓倾心听取意见。表示重视或亲近。
入宣室1:指受到君王的召见。
前席1:喻指受到君王的重视和亲近。
夜趋宣室1:谓贤才受到君主特别重视。
天子坐宣室1:借指君王临朝听政。
宣室征还1:指君王征召回朝为官。
宣室恩1:指君王对臣子的特殊恩遇。
宣室才华子1:指受君王宠遇的臣子。
宣室诏1:指君王征召才士的诏令。
宣室语1:喻指君王礼遇才士的旨意。
宣室问鬼神1:指<u>汉文帝</u>在<u>宣室</u>问鬼神之事。
朝宣室1:指朝见君王。
汉文思贾傅1:借指帝王思念贤士才臣。
汉皇前席1:泛指君王礼遇贤臣。
贾生前席召1:指受到君王的特别召见。','唐刘长卿《新安奉送穆谕德归朝赋得行字》：“九重宣室召，万里建溪行。”；明陈子龙《送钱大鹤还吴阊》诗：“五湖纵与家山近，宣室还劳召贾生。”；唐李白《江夏送倩公归汉东序》：“思亲遂行，流涕惜别。今圣朝已舍季布，当征贾生。”；《周书·寇俊传》：“帝与之谈论，不觉屡为前膝。”；唐李白《放后遇恩不沾》诗：“何时入宣室，更问洛阳才。”；唐王维《故右豹韬卫长史任君神道碑》：“一见天子，必为之前席;三说大臣，必为之解印。”；宋李曾伯《沁园春·送洪漕使宪闽》词：“如公样，盍夜趋宣室，昼对延英。”；唐李群玉《将之京国赠薛员外》诗：“天子坐宣室，夔龙奉谟猷。”；唐刘禹锡《和苏郎中寻丰安里旧居寄主客张郎中》：“漳滨卧起恣闲游，宣室征还未白头。”；唐褚秀《奉和圣制送张说上集贤学士赐宴》：“宣室恩尝异，金华礼更崇。”；唐裴耀卿《酬张九龄使风见示》：“宣室才华子，金闺讽议臣。”；唐白居易《寄题周至厅前双松》诗：“忽奉宣室诏，征为文苑臣。”；唐罗隐《淮南送节度卢端公将命之汴州端公常为汴州相公从事》诗：“到彼的知宣室语，几时征拜黑头公?”；清顾嗣立《贾傅故宅》诗：“洪炉久已为铜炭，宣室何劳问鬼神?”；唐方干《送郑端公》诗：“圣主伫知宣室事，岂容才子滞长沙。”；唐柳宗元《闻籍田有感》诗：“宣室无由问釐事，周南何处托成书?”；唐独孤及《奉和中书常舍人晚秋集贤院即事寄赠徐薛二侍御》：“早晚朝宣室，归时道路光。”；前蜀贯休《送吴融员外赴阙》诗：“汉文思贾傅，贾傅遂生还。今日又如此，送君非等闲。”；明杨慎《春兴》诗：“宣室鬼神思贾谊，中原将帅用廉颇。”；宋刘克庄《贺新郎·送黄成父还朝》词：“飞诏从天下。道中朝、名贤欲尽，君王思贾。”；宋阮秀实《酹江月·庄王漕六十九》词：“固是守约堂间，鲂斋亭下，要种归来柳。只恐夜深思贾傅，便有锋车迎候。”；清吴伟业《送曹秋岳以少司农迁广东》诗：“此去好看宣室召，汉皇前席问苍生。”；唐章八元《酬刘员外月下见寄》：“宣室思前席，行看拜主恩。”；唐钱起《喜李侍御拜郎官入省》诗：“汉主前瑶席，穰侯许凤池。”；清符兆纶《满江红·秋感》词：“虚说贾生前席召，可怜祖逖先鞭着。”','[]',2),
(8500000000000000025,'蓼莪废讲',7,'典故','《诗·小雅·蓼莪》：“蓼蓼者莪，匪莪伊蒿。哀哀父母，生我劬劳……欲报之德，昊天罔极。”毛传：“民人劳苦，孝子不得终养尔。”郑玄笺：“恨不得终养父母，报其生长己之苦。”又《晋书·王裒传》：“〔裒〕痛父非命(父仪被司马昭杀害)，未尝西向而坐，示不臣朝廷也……及读《诗》至‘哀哀父母，生我劬劳’，未尝不三复流涕，门人受业者并废《蓼莪》之篇。”蓼莪废讲1:后因以“《蓼莪》废讲”为孝子对亡故父母的悲痛哀思。
匪莪之心1:后借指对亡故父母的深切悼念。
废蓼莪诗1:谓伤悼亡故的父母。
愁断蓼莪篇1:谓悲痛父母去世。
泣诗1:谓深切悲悼亡故的父母。
王裒废读1:谓深切追念伤悼亡故的父母。
蓼莪罔极1:谓孝子对亡故父母的无穷哀思。','宋陆游《生日子聿作五字诗为寿追怀先亲》诗：“负米养亲无复日，《蓼莪》废讲岂胜悲。”；《艺文类聚》卷十五引三国魏曹植《上卞太后诔表》：“臣闻铭以述德，诔尚及哀，是以冒越谅闇之礼，作诔一篇，知不足赞扬明贵，以展臣《蓼莪》之思。”；宋苏轼《谢生日诗启》：“《蓼莪》之感，迨衰老而不忘。”；明夏完淳《寒日扫墓》诗：“王裒私教授，长起《蓼莪》哀。”；明高启《广陵孙孝子爱日堂》诗：“自惭不及君庆多，洒泪《蓼莪》空废诵。”；唐白居易《与从史诏》：“卿亡父早践班荣，久著声绩，永言褒赠，自叶典常。况卿孝友承家，勤劳事国;念兹忠节，皆禀义方。将慰匪莪之心，宜流自叶之泽。”；明李东阳《徐用和御史墓山八咏·茅屋时思》：“极德难忘寸草私，多愁长废《蓼莪》诗。”；清顾炎武《梓潼篇赠李中孚》诗：“尸饔常并日，废蓼拟填沟。”；宋陈与义《题董宗禹园先志亭》诗：“我已废《蓼莪》，感兹泪河翻。”清钱谦益《简侯研德并示记原》诗：“知君耻读《王裒传》，但使生徒废《蓼莪》。”；元邓文原《清明省墓》诗：“短棹吴歌花满川，春风愁断《蓼莪》篇。”；清顾炎武《酬徐处士元善新城之陷其母死焉故有此作》诗：“季子已无观乐地，伟元终是泣《诗》人。”伟元，王裒之字。；柳亚子《岁暮杂感》诗：“王裒常废读，原壤忍狂歌。”；三国魏曹植《求通亲亲表》：“终怀《蓼莪》罔极之哀。”','[]',2),
(8500000000000000026,'击壤歌',7,'典故','汉王充《论衡·艺增》载：相传唐尧时有老人击壤歌于路，观者曰：“大哉，尧德乎!”击壤者曰：“吾日出而作，日入而息，凿井而饮，耕田而食;尧何等力!”按，《艺文类聚》卷十一引晋皇甫谧《帝王世纪》所引歌辞略异，末句作“帝何力于我哉”!击壤歌1:后因以击壤歌为太平盛世之歌。
击壤鼓腹1:原谓人民吃得饱，有余闲游戏。后以“击壤鼓腹”称颂太平盛世。
击壤1:借指太平盛世的欢愉生活。
击壤世1:指太平盛世。
击壤年1:指太平盛世。
击壤情1:指上古人民的淳朴感情。
击壤曲1:自谦粗俗的作品。
击壤翁1:指远古先民。
凿饮耕食1:谓凿井而饮，耕田而食。指天下太平，百姓安居乐业。
壤父1:传说中<u>尧</u>时的田野老人。
尧舜力1:借指帝王施行仁政的功力。
帝力1:指帝王的作用或恩德。
忘帝力1:形容百姓安居乐业无所祈求。
歌击壤1:指歌颂太平盛世。
歌帝力1:谓歌颂帝王的恩泽。
耕凿1:形容百姓辛勤劳动，生活安定。
陶唐歌1:指太平盛世之歌。
鼓腹击壤1:形容太平盛世。','明无名氏《鸣凤记·幼海议本》：“息风波，固皇图，愿见康衢《击壤歌》。”；清赵翼《刊刻汪文端师集既就书以志愧》诗之三：“敢追汉殿凌云赋，聊付康衢击壤吟。”；南朝宋谢灵运《初去郡》诗：“即是羲唐化，获我击壤声。”；唐李峤《晚秋喜雨》诗：“野洽如坻咏，途喧击壤讴。”；唐杜甫《奉送王信州崟北归》诗：“《壤歌》惟海甸，画角自山楼。”；《续资治通鉴·宋仁宗景祐三年》：“为致治之本，使政令平简，民人熙洽，海内击壤鼓腹以歌太平，斯乃治古之乐，可得以器象求乎!”；唐李峤《田》诗：“瑞麦两岐秀，嘉禾同颖新。宁知帝王力，击壤自安贫。”；清方贞观《出宗阳》诗：“生逢击壤世，不得守耕桑。”；南朝陈徐陵《报尹义尚书》：“击壤之年，唯欣尧俗。”；唐柳宗元《游南亭夜还叙志七十韵》：“兹焉毕馀命，富贵非吾曹……苟伸击壤情，机事息秋豪。”；唐权德舆《奉和圣制重阳日即事六韵》：“多惭击壤曲，何以答尧聪。”；前蜀贯休《寿春进祝圣七首·大兴三教》诗：“击壤翁知否，吾皇即帝尧。”；《南齐书·王融传》：“臣亦遭逢，生此嘉运，凿饮耕食，自幸唐年。”；晋皇甫谧《高士传》卷上：“帝尧之世，天下太和，百姓无事。壤父年八十余而击壤于道中。”；唐宋之问《寒食还陆浑别业》诗：“野老不知尧舜力，酣歌一曲太平人。”；《汉书·张耳传》：“且先王亡国，赖皇帝得复国，德流子孙，秋豪皆帝力也。”唐高適《别杨山人》诗：“凿井耕田不我招，知君以此忘帝力。”；唐高適《酬庞十兵曹》诗：“雨泽感天时，耕耘忘帝力。”；唐钱起《山园栖隐》诗：“且忘尧舜力，宁顾尚书期。”；清赵翼《日计》诗：“留与熙朝歌《击壤》，含哺鼓腹作无怀。”；宋黄庭坚《次韵寅庵》之一：“闲与老农歌帝力，年年村落罢追胥。”；唐太宗《临层台赋》：“肆黎元于耕凿，一文轨于车书。”清查慎行《恩赐新刻御制诗集》诗：“耕凿万方民击壤，《箫韶》九奏帝垂裳。”；清徐夔《苦热》诗：“安得白雨洒秋令，击壤一和陶唐歌。”；《隋书·何妥传》：“上古之时，未有音乐，鼓腹击壤，乐在其间。”','[]',2),
(8500000000000000027,'曲突徙薪',7,'典故','汉刘向《说苑·权谋》：“臣闻客有过主人者，见其灶直堗，傍有积薪，客谓主人曰：‘曲其堗，远其积薪，不者，将有火患。’主人嘿然不应。居无几何，家果失火，乡聚里中人哀而救之，火幸息。于是杀牛置酒，燔发灼烂者在上行，馀各用功次坐，而反不录言曲堗者。向使主人听客之言，不费牛酒，终无火患。”汉桓谭《新论·见徵》、《汉书·霍光传》亦载，堗，均作“突”。曲突徙薪1:突，烟囱。后以曲突徙薪谓事先采取措施，防患于未然。
焦头烂额1:原形容因救火烧伤严重。后多以比喻受到沉重打击或处境险恶，以致狼狈不堪的情状。
曲突谋1:指防患于未然的谋虑或计策。
焦头上客1:指被优礼的在救火中严重烧伤的人。亦借指为挽回不必要的失误而作出贡献者。含有舍本逐末之意。
移突1:谓防患于未然。
移薪1:谓防患于未然。
谋曲突1:指防患于未然之策。','唐杜牧《李给事中敏》诗之一：“曲突徙薪人不会，海边今作钓鱼翁。”清黄遵宪《福州大火同张樵野丈龚霭人丈作》诗：“曲突徙薪广恩泽，愿亟靖海安天骄。”；晋葛洪《抱朴子·君道》：“勿惮徙薪之烦，以省焦烂之费。”；晋葛洪《抱朴子·知止》：“徙薪曲突于方炽之火，纚舟弭楫于冲风之前。”清林则徐《和嶰翁祀灶原韵》：“徙薪曲突付一叹，踞觚听者休相瞋。”；三国魏应璩《百一诗》：“曲突不见宾，焦烂为上客。”宋王安石《吴正肃公挽辞》之二：“曲突非无验，方穿有不行。”；清李渔《玉搔头·媲美》：“曲突移薪计未忠，焦头烂额敢居功?”；清丘逢甲《送何士果同年之京兼寄怀梁诗五孝廉》诗：“榑桑持节旧词臣，事去空怀曲突薪。”；柳亚子《恭谒孙先生之灵堂有感》诗：“曲突迁薪今已矣，一夫不杀血成江。”；《古今小说·汪信之一死救全家》：“这枢密院官都是怕事的，只晓得临渴掘井，那会得未焚徙薪?”；《宋书·桂阳王休范传》：“桂蠹必除，人邪必剪，枉突徙薪，何劳多力!”；宋陆游《戍卒说沉黎事有感》诗：“焦头烂额知何补，弭患从来贵未形。”；清钱谦益《病榻消寒杂咏》之二：“漆身吞炭依稀是，烂额焦头取次能。”；金元好问《壬辰十二月车驾东狩即事五首》之三：“焦头无客知移突，曳足何人与共船?”；宋黄庭坚《次韵子由绩溪病起被召寄王定国》：“必开曲突谋，满慰倾耳听。”；唐权德舆《读穀梁传》诗：“吾嘉徙薪智，祸乱何由生?”；清陈宝琛《送仲勉之官云南》诗：“夙疑大国患，或在西南陲。徙薪策不售，两纪空赍咨!”；清王闿运《独行谣三十章赠示邓辅纶》诗：“乡使并全力，武宣扫无馀。置此曲突计，焦头赏曾胡。”；清简朝亮《寄酬梁大鼎芬》诗之二：“焦头上客负前身，曲突累累告徙薪。”；清赵翼《戏咏火判官》诗：“人以头焦惊上客，世无灶养作中郎。”；清钱谦益《虫诗十二章·灯蛾》：“君看焦烂客，仍得坐高堂。”；金元好问《壬辰十二月车驾东狩即事》诗之三：“焦头无客知移突，曳足何人与共船?”；翟禹锡《对小吏持剑判》：“带昆吾之宝，宁惭挂树之人;弃回禄之烟，谁赏移薪之客?”；宋黄庭坚《辛酉憩刀坑口》诗：“烂额始论功，倘能谋曲突。”','[]',2),
(8500000000000000028,'分茅列土',7,'典故','《书·禹贡》“厥贡惟土五色”孔颖达疏引汉蔡邕《独断》：“天子大社，以五色土为坛。皇子封为王者，授之大社之土，以所封之方色。苴以白茅，使之归国以立社，谓之茅社。”《文选·李陵〈答苏武书〉》：“陵谓足下当享茅土之荐。”李善注引《尚书纬》：“天子社，东方青，南方赤，西方白，北方黑，上冒以黄土。将封诸侯，各取方土，苴以白茅，以为社。”分茅列土1:古代分封诸侯，用白茅裹泥土赐于被封者，象征授于土地和权力。后以分茅列土谓分封侯位和土地。
赤社1:赤为南方之色。古时封到南方立社建国称“赤社”。后因用为出任南方封疆大吏之典。
列土1:谓分封土地。
茅土1:指王侯的封爵和封地。
裂土拜爵1:指分赐土地、拜封爵位。
裂土称雄1:指割据土地自称雄长。
裂地1:借喻委派大吏割据一方土地。
裂地封1:指分一块土地封给大臣为采邑。','唐张说《延州豆卢使君万泉县主薛氏神道碑》：“大圣天后，炼石补天，有王母之神器;分茅列土，启弄孙之美色。”；《晋书·八王传赞》：“有晋郁兴，载崇藩翰，分茅锡瑞，道光恒典。”唐杨巨源《重送胡大夫赴振武》诗：“向年擢桂儒生业，今日分茅圣主恩。”；明刘若愚《酌中志·忧危竑议后纪》：“数公皆人杰，无不望分茅胙土如姚广孝，岂止富贵终其身而已乎!”；元高文秀《渑池会》四折：“官封极品禄千钟，分茅裂土人堪羡。”；清李渔《夺锦楼》五回：“不止分茅赐土，允宜并位于中宫。”；清李渔《玉搔头·飞舸》：“只要你忙上紧赶得那人近至尊，便是分茅锡土也非吾吝。”；元郑光祖《三战吕布》一折：“军前累立功劳大，列土分茅受大封。”；唐杜牧《李叔玫除太仆卿高征除均州刺史等制》：“我西平王功存社稷，庆流后嗣，子孙多贤，裂土分茅。”宋辛弃疾《洞仙歌·赵晋臣和李能伯韵嘱余同和》词：“况满屋、貂蝉未为荣，记裂土分茅，是公家世。”；《商君书·赏刑》：“汤与桀战于鸣条之野，武王与纣战于牧野之中，大破九军，卒裂土封诸侯。”；宋叶適《任子》：“古者裂地分茅，以报人臣之有功，使其子孙嗣之。”；《汉书·黥布传》：“臣请与大王杖剑而归汉王，汉王必裂地而分大王，又况淮南，必大王有也。”；南朝齐王融《赠族叔卫军》诗：“建兹赤社，俾侯南昌。”元黄镇成《投赠郑守光远三十韵》：“赤社分南服，清都拱北辰。”；《汉书·谷永传》：“方制海内非为天子，列土封疆非为诸侯，皆以为民也。”；《后汉书·陈蕃传》：“近习以非义授邑，左右以无功传赏，授位不料其任，裂土莫纪其功。”《新唐书·李百药传》：“时议裂土与子弟功臣，百药上《封建论》，理据详切，帝纳其言而止。”；南朝梁沈约《刘领军封侯诏》：“宜锡圭裂壤，允副佥属。”；唐李颀《行路难》诗：“汉家名臣杨德祖，四代五公享茅土。”；《晋书·汝南王亮等传序》：“徒分茅社，实传虚爵。”宋苏轼《皇叔皇兄追封制》：“没享茅社，所以宠绥其子孙。”；清陈康祺《燕下乡脞录》卷二：“当事者且谓捣穴擒渠，功在眉睫，人人有裂土拜爵之想。”；吴恭亨《诸将》诗之四：“裂土称雄各一方，无端兄弟鬩于墙。”；郭沫若《豕蹄·楚霸王自杀》：“昨天的敌人，只要肯做扶持自己的爪牙，今天便封王裂地。”；《晏子春秋·问上十九》：“裂地而封之，疏爵而贵之。”唐元稹《出门行》：“在楚裂地封，入赵连城贵。”','[]',2),
(8500000000000000029,'辋川',7,'典故','《旧唐书·王维传》：“〔王维〕得宋之问蓝田别墅，在辋口，辋水周于舍下。”又《新唐书·王维传》：“别墅在辋川，地奇胜，有华子冈、欹湖、竹里馆、柳浪、茱萸沜、辛夷坞，与裴迪游其中，赋诗相酬为乐。”辋川1:后因以辋川指代<u>王维</u>。
辋川2:亦指《辋川图》。
辋川图1:《辋川图》本为<u>唐</u>诗人<u>王维</u>画的名画。后借指风景幽胜之处。
辋口渔人1:指退隐之人。','宋张元幹《跋〈山居图〉》：“后十二年，青社赵无量通守晋安，出示叔毅所图《山居》，开卷恍然，殆前身辋川，今代龙眠欤!”明王世贞《艺苑卮言》四：“王半山‘山中十日雨，雨晴门始开。坐看苍苔色，欲上人衣来’。后二语全用辋川，已是下乘。”；清高士奇《题卢徵君嵩山草堂图》诗：“在昔右丞妙诗画，《辋川》旧本留清风。”清魏源《富阳董文恪山水屏风歌》：“摩诘《辋川》独难步，郭熙《清明》何足道!”；宋苏轼《李伯时画其弟亮工旧隐宅图》诗：“五亩自栽池上竹，十年空看《辋川图》。”高增《君介有武林之游诗以送之》：“分明一幅《辋川图》，便倩王维画得无?”；明王衡《郁轮袍》七折：“前日在科场中，见考官将我哥哥奈何，我叹了一口气，便不递俺这文章，竟买舟归家，做个辋口渔人。”','[]',2),
(8500000000000000030,'尸位素餐',7,'典故','《书·五子之歌》：“太康尸位，以逸豫，灭厥德，黎民咸贰。”《诗·魏风·伐檀》：“不稼不穑，胡取禾三百廛兮?不狩不猎，胡瞻尔庭有县貆兮?彼君子兮，不素餐兮。”毛传：“素，空也。”陈奂传疏：“今俗以徒食为白餐。餐，犹食也。赵岐注《孟子·尽心篇》云：‘无功而食，谓之素餐。’”尸位素餐1:后因以尸位素餐为无功受禄，居位食禄而不尽职的典故。
尸利素餐1:谓居官食禄而不尽职。
尸素之禄1:指无功而受之俸禄。
悬貆素飡1:喻无功受禄。
滥尸1:自谦才弱滥居官位。
滥尸2:亦指居其位而未尽其责。','《汉书·朱云传》：“今朝廷大臣，上不能匡主，下亡以益民，皆尸位素餐。”颜师古注：“尸位者，不举其事，但主其位而已。素餐者，德不称官，空当食禄。”三国魏曹植《矫志》诗：“芳树虽香，难以饵鱼。尸位素餐，难以成居。”；唐韦嗣立《偶游龙门呈诸大僚》诗：“短才叨重寄，尸禄愧妨贤。”；汉刘向《说苑·至公》：“久践高位，妨群贤路。尸禄素飡，贪欲无厌。”；宋王禹偁《让西京留守表》之二：“非不眷恋明代，盖忧逼近死期，述度德量力之心，减尸禄素餐之咎。”；唐白居易《让绢状》：“臣食国家厚禄，居陛下清官，每月俸钱，尚惭尸素，无名之货，岂合苟求?”；宋黄庭坚《赣上食莲有感》诗：“甘飡恐腊毒，素食则怀惭。”明刘基《题李伯时画渊明归来图》诗：“陶公节义士，素食岂其心?”；《三国志·郤正传》：“虽时献一策，偶进一言，释彼官责，慰此素飧。”；汉桓宽《盐铁论·盐铁箴石》：“今有司以不仁，又蒙素餐，无以更责雪耻矣。”宋范仲淹《上执政书》：“官实素餐，民则菜色。”；汉王符《潜夫论·思贤》：“又不得治民效能，以报百姓，虚食重禄，素餐尸位。”；《孔丛子·论势》：“尸利素餐，吾罪深矣。”《资治通鉴·周赧王五十六年》：“言不当于主，居人之官，食人之禄，是尸利素餐，吾罪深矣。”；林纾《答某公书》：“岂忍割弃可恋之日，冒沾尸素之禄，以遽远老母?”；汉焦赣《易林·复之屯》：“悬貆素飡，食非其任。”；北周庾信《哀江南赋》：“谬掌卫于中军，滥尸丞于御史。”；宋欧阳修《国学试策第三道》：“贤者旌之以劝善，不贤者罚之以去恶，则列职虽云至众，取人安不尽贤，禄何由而滥尸，官诚难于充选。”','[]',2),
(8500000000000000031,'盐梅和鼎',7,'典故','《书·说命下》载：殷高宗武丁命傅说作相，曰：“若作和羹，尔惟盐梅。”孔传：“盐咸梅醋，羹须咸醋以和之。”盐梅和鼎1:后因以盐梅和鼎为称颂宰相的典故。
调鹄1:谓出任宰相。
佐鼎调梅1:指辅佐君王治理政事。
傅说羹1:借指良相。
和商鼎1:借以咏梅。
和殷羹1:比喻辅佐君王执掌国政。
和羹傅鼎1:指作君王的宰辅之臣。
和羹梅1:比喻大臣辅助君王综理国政。
和鼎1:指宰辅重臣。
梅羹1:指宰辅之位。
济川调鼎1:比喻辅佐帝王治理国家。
盐梅1:喻指国家所需的贤才。
盐梅之寄1:喻指可托付重任。
盐梅事业1:指宰辅所主持的国计民生大事。
盐梅处1:指宰相议事处，即门下省政事堂。
盐梅相成1:盐味与酸味相调和。喻指济世的贤臣。
盐梅舟楫1:盐和梅调和，舟和楫配合，喻指辅佐的贤臣。
调殷鼎1:指拜相。
调盐1:喻任宰相治理国政。
调羹鼎1:喻治理政事。
调胹1:烹调食物，喻治理政事。胹，烹煮，引申为调和。
调鼎1:喻任宰相治理国家。
调鼎2:亦指治国才能。
调鼎为霖1:指担任宰辅重臣。
鼎梅助味1:指宰辅重任。
鼎鼐1:喻指宰相等执政大臣。
鼎鼐调和1:比喻处理国政。','唐沈佺期《和户部岑尚书参迹枢揆》：“盐梅和鼎食，家声众所归。”；明邵璨《香囊记·看策》：“堂堂舟楫济川材，落落盐梅调鼎手。”；宋宋庠《寄长安端明王左丞》诗：“才包扬马思，政续赵张神。鼎饪终调鹄，天文尚剪鹑。”；宋李曾伯《沁园春·乙未代寿尤制帅》词：“佐鼎调梅，参帷借箸，略试斯文经济功。”；前蜀贯休《送卢舍人朝觐》诗：“既握钟繇笔，须调傅说羹。”；唐羊士谔《东渡早梅一树岁华如雪酣赏成咏》：“晚实和商鼎，浓香拂寿杯。”；唐李白《纪南陵题五松山》诗：“当时版筑辈，岂知傅说情。一朝和殷羹，光气为列星。”；元白朴《朝中措》词：“任是和羹傅鼎，争如漉酒陶巾。”；唐孟浩然《韩大使东斋会岳上人诸学士》诗：“徒攀朱仲李，谁荐和羹梅?”；唐钱起《陪郭常侍令公东亭宴集》诗：“不愁欢乐尽，积庆在和羹。”；《魏书·任城王澄传》：“臣诚才非台躬，智阙和鼎。”；唐令狐楚《将赴洛下旅次汉南献上相公二十兄言怀八韵》：“龙衮期重补，梅羹伫再和。”；明张居正《再谢御书疏》：“期少效济川调鼎之用，庶以答天高地厚之恩。”；唐沈佺期《哭苏眉州崔司业二公》诗：“崔昔挥宸翰，苏尝济巨川。”按，苏眉州(味道)曾任宰相。唐皇甫澈《门下侍郎平章事王缙》诗：“舟楫济巨川，山河资秀色。”按，“平章事”即宰相。；《梁书·庾诜传》：“勒州县时加敦遣，庶能屈志，方冀盐梅。”清李渔《玉搔头·分任》：“急递盐梅信，飞传鼎鼐家。”因盐梅为调味品，故又喻指调和、和谐。南朝梁刘勰《文心雕龙·声律》：“声得盐梅，响滑榆槿。”宋苏辙《除冯京彰德军节度使制》：“和而不同，性有盐梅之德。”；《隋书·刘昉郑译等传论》：“暨夫帝迁明德，义非简在，盐梅之寄，自有攸归。”；宋严仁《水龙吟·题连州翼然亭呈欧守》词：“尽江山识赏，盐梅事业，焕青毡旧。”；唐沈佺期《自考功员外授给事中》诗：“何幸盐梅处，唯忧对问机。”按给事中乃门下省属官。；宋罗大经《鹤林玉露》卷十二：“窃意二老(太公、伯夷)受文王之养，平居暇日，同堂合席，念王室之如煆，固欲起而救乱;思冠冕之毁裂，又恐因而阶乱。故水火相济，盐梅相成，各以一事自任。”；元柯丹丘《荆钗记·春科》：“际风云，盐梅舟楫，一德务臣君。”；唐贾岛《谢令狐绹相公赐衣九事》诗：“即日调殷鼎，朝分是与非。”；宋王安石《送郓州知府宋谏议》诗：“治装行入觐，金鼎重调盐。”；明张凤翼《红拂记·仗策渡江》：“囊中黄石包玄妙，腰下青萍射斗牛。调羹鼎，济川舟，云龙风虎岂难投。”；唐李乂《奉和幸望春宫送朔方军大总管张仁亶》：“上宰调梅寄，元戎细柳威。”；宋赵善括《醉蓬莱·魏相国生日》词：“补衮工夫，调羹手段，如今重试。”；《旧唐书·陆贽传论》：“贽居珥笔之列，调饪之地，欲以片心除众弊，独手遏群邪。”；宋王安石《送刘贡父赴秦州清水》诗：“刘郎高论坐嘘枯，幕府调胹用绪余。”；唐孟浩然《都下送辛大之鄂》诗：“未逢调鼎用，徒有济川心。”；唐杜甫《上韦左相二十韵》：“沙汰江河浊，调和鼎鼐新。”《天雨花》一回：“长成必定功名显，调和鼎鼐济苍生。”；宋方岳《瑞鹤仙·寿丘提刑》词：“但丁宁，留取微酸，调商鼎也。”；唐李端《喜皇甫郎中拜谕德兼集贤学士》诗：“几日调金鼎，诸君欲望尘。”；唐权德舆《仲秋朝拜昭陵》诗：“良将授兵符，直臣调鼎𫗧。”；唐皇甫冉《彭祖井》诗：“闻道延年如玉液，欲将调鼎献明光。”；宋李纲《苏武令》词：“调鼎为霖，登坛作将，燕然即须平扫。”；宋李曾伯《沁园春·送洪漕使宪闽》词：“自檄草参筹，宾筵领袖，鼎梅助味，省闼权衡。”；唐苏颋《唐紫微侍郎赠黄门监李乂神道碑》：“鼎鼐递袭，簪缨相望。”；元郑光祖《老君堂》二折：“鼎鼐调和理庶民，安邦定国立功勋。”；唐权德舆《故司徒兼侍中赠太傅北平王挽词》：“授律勋庸盛，居中鼎鼐和。”','[]',2),
(8500000000000000032,'宅相',7,'典故','《晋书·魏舒传》：“〔舒〕少孤，为外家宁氏所养。宁氏起宅，相宅者云：‘当出贵甥。’外祖母以魏氏甥小而慧，意谓应之。舒曰：‘当为外氏成此宅相。’”宅相1:后因以宅相代称外甥。
宁家宅1:指舅氏。','唐赵元一《奉天录》卷四：“王贲侍郎，即令公之宅相也，志大气雄，酷似其舅。”；唐权德舆《奉和崔评事寄外甥刘同州》：“谢公尝乞墅，宁氏终相宅。”；唐司空曙《哭苗员外呈张参军》诗：“思君宁家宅，久接竹林期。”；唐卢纶《送从舅成都丞广归蜀》诗：“魏舒终有泪，还识宁家衣。”','[]',2),
(8500000000000000033,'望夫石',7,'典故','《初学记》卷五引南朝宋刘义庆《幽明录》：“武昌北山有望夫石，状若人立。古传云：昔有贞妇，其夫从役，远赴国难，携弱子饯送北山，立望夫而化为立石。”按，望夫石相传有多处，如辽宁省兴城市西南望夫山之望夫石，传为孟姜女望夫所化;江西省鄱阳西有望夫冈，传为陈明妻梅氏望夫之处。参阅《嘉庆一统志·锦州府》及刘澄之《鄱阳记》等。此外，安徽省当涂县西北、湖北省阳新县西南等地均有望夫石或望夫山。望夫石1:后以望夫石为妻子思夫之典。
一上青山便化身1:形容妇人的坚贞。
似人石1:指望夫石。
化石1:比喻妇女对丈夫用情的坚贞和思念。
化石妇1:比喻对丈夫坚贞和思念的女子。
山头石1:指传说中守盼夫归之妇所化的望夫石。
望夫化去1:喻指一去不返。
石望夫1:形容矢志不二，精诚至极。
青山石妇1:指望夫石。借以象征妻子对丈夫用情坚贞不二。','明朱有燉《香囊怨》二折：“凭着我志诚身端正，便化作望夫石也，坚等到河清。”明谢谠《四喜记·翠阁耽思》：“仰望惟君子，无邪不害思。甘为望夫石，何日是归期?”；唐李白《长干行》：“十五始展眉，愿同尘与灰。常存抱柱信，岂上望夫台!”明汤显祖《牡丹亭·婚走》：“叹孤坟何处是俺望夫台?”；宋刘弇《大孤山》诗：“至以孤为姑，考究初无端……神固不可诬，何得正以女子观。吾言庶几不悠谬，不然兹山徒与望夫女石争巑岏?”；唐李白《别内赴征》诗之一：“白玉高楼看不见，相思须上望夫山。”唐慎氏《感夫诗》：“便是孤帆从此去，不堪重上望夫山。”；唐吴曾《望夫山》诗：“一上青山便化身，不知何代怨离人。”；唐刘损《愤惋诗》之二：“愿作山头似人石，丈夫衣上泪痕深。”；明何景明《结肠赋》：“泪陨血而崩城兮，身立枯而化石。”苏曼殊《无题》诗之七：“分明化石心难定，多谢云娘十幅笺。”；宋梅尧臣《雪中发江宁浦至采石》诗：“山头化石妇，忽变素质光。岂复愿闻笛，莫逢桓野王。”；宋贺铸《陌上郎》词：“挥金陌上郎，化石山头妇。”；唐李商隐《妓席暗记送同年独孤云之武昌》诗：“武昌若有山头石，为拂苍苔检泪痕。”；元贡师泰《挽陈尧》诗：“望夫化去孤石裂，死与韩凭誓同穴。”；宋黄庭坚《次韵杨明叔》之四：“窃观今日事，君与古人俱：气类莺求友，精诚石望夫。”；唐鲍溶《期尽》诗：“青山石妇千年望，雷雨曾知来不来。”','[]',2),
(8500000000000000034,'李膺门',7,'典故','《后汉书·李膺传》：“是时朝庭日乱，纲纪颓阤，膺独持风裁，以声名自高。士有被其容接者，名为登龙门。”李膺门1:后因以李膺门誉称名高望重之家。
一世龙门1:称为世人所景仰的名高望重之人。
元礼许登门1:谓得到高士、贤者的青睐。
元礼龙门1:借指高士、贤者之门。
御李1:谓得以亲近贤者。
接李膺杯1:喻指受名流接待。
李膺客1:喻指受到名人青睐之客。
登龙客1:指得到名人接待、援引的人。
登龙门1:谓得到名人的接待或援引而身价提高。
膺门1:借指名高望重者的门下。
门下化龙1:称誉名人援引贤才。
龙门1:誉称官高品正者的高门望第。
龙门2:亦指众望所归者。
龙门客1:指高门的上客。
龙门礼士1:谓贤尊援引，提拔后生。','唐杜牧《川守大夫刘公早岁寓居敦行里肆今之置第乃获旧居辄献此诗》：“昔为扬子宅，今是李膺门。”；唐王季友《酬李十六岐》诗：“于何车马日憧憧，李膺门馆争登龙。千宾揖对若流水，五经发难如叩钟。”；唐杜正伦《冬日宴于庶子宅各赋一字得节》诗：“李门余妄进，徐榻君恒设。”；《晋书·王衍传》：“衍既有盛才美貌，明悟若神，常自比子贡，兼声名藉甚，倾动当世。妙善玄言，明谈《老》《庄》为事……朝野翕然，谓之‘一世龙门’矣。”；唐刘禹锡《武陵书怀》诗：“士安曾重赋，元礼许登门。”；唐王勃《秋晚入洛毕公之宅》诗：“高扃向术，似元礼之龙门;甲第临衢，有当时之驿骑。”；唐权德舆《和王祭酒太社宿斋不得赴李尚书宅会戏书见寄》：“元礼门前劳引望，句龙坛下阻欢娱。”；唐黄滔《上卢员外启》：“岂可坚期御李，确慕依刘，志空切于投林，丑难逃于侧管。”明杨珽《龙膏记·开阁》：“我谅才未达，名愧诸生，自喜登龙成饰，御李生辉。”；唐孟浩然《荆门上张丞相》诗：“坐登徐孺榻，频接李膺杯。”；唐杨炯《宴皇甫兵曹宅》诗序：“累代通家，咸言李膺之客;百年何计，相知在于我心。”；唐许浑《怀旧居》诗：“朱门迹忝登龙客，白屋新期失马翁。”；唐李白《与韩荆州书》：“一登龙门，声价十倍。”；唐李商隐《五言述德抒情诗》：“登门惭后至，置驿恐虚迎。”；唐李端《元丞宅送胡浚及第东归觐省》诗：“登龙兼折桂，归去当高车。”；唐元稹《陪诸公游通德湖》诗：“唯有满园桃李下，膺门偏拜阮元瑜。”前蜀贯休《别卢使君》诗：“幸到膺门下，频蒙俸粟分。”；唐孟球《和主司王起》诗：“当年门下化龙成，今日余波进后生。”；唐张九龄《故刑部李尚书挽词》之二：“龙门不可望，感激涕沾衣。”；清张明弼《冒姬董小宛传》：“虞山钱牧斋先生维时不惟一代龙门，实风流教主也。”；唐杜甫《奉赠鲜于京兆二十韵》：“凤穴雏皆好，龙门客又新。”；赵宗瀚《寄怀李印泉先生日本二首》诗之二：“龙门礼士膺名重，猿臂封侯广数奇。”','[]',2),
(8500000000000000035,'一丘一壑',7,'典故','《汉书·叙传上》：“渔钓于一壑，则万物不奸其志;栖迟于一丘，则天下不易其乐。”一丘一壑1:后因以一丘一壑为退隐在野、放情山水的典故。
一丘自足1:谓满足于退隐在野，放情山水。
丘壑1:谓隐逸。
丘壑之念1:指隐逸的心愿。
丘壑志1:指隐居的志向。
丘壑趣1:指退隐在野、放情山水的情趣。
幼舆丘壑情1:指隐逸之情。
擅壑专丘1:谓放情山水。
胸中一壑1:谓怀有隐居之志。','南朝宋刘义庆《世说新语·品藻》：“明帝问谢鲲：‘君自谓何如庾亮?’答曰：‘端委庙堂，使百官准则，臣不如亮;一丘一壑，自谓过之。’”唐王勃《上明员外启》：“一丘一壑，同阮籍于西山;一啸一歌，列嵇康于北面。”；唐崔涂《题嵩阳隐者》诗：“四十年高梦，生涯指一丘。无人同久住，有鹤对冥修。”；宋辛弃疾《蓦山溪·昌父赋一丘一壑格律高古因效其体》词：“高处看浮云，一丘壑、中间甚乐。功名妙手，壮也不如人，今老矣，尚何堪，堪钓前溪月。”；宋辛弃疾《感皇恩·读庄子有所思》词：“一壑一丘，轻衫短帽，白发多时故人少。”清陈书《西楼夜坐》诗之一：“江山信美非吾土，一壑一丘聊置身。”；宋赵以夫《沁园春·次方时父》词：“喜支离得佚，散材可寿，一丘自足，万象中涵。”；南朝宋谢灵运《斋中读书》诗：“昔余游京华，未尝废丘壑。”；金王若虚《茅先生道院记》：“予世之散人也，才能无取于人，而功名不切于己，虽寄迹市朝，而丘壑之念未尝一日忘。”；宋晁冲之《东阳山人僻居》诗：“平生丘壑心，水竹不满眼。”；清陈豪《子寿先生招隐乃园同子缜赓甫迟菊》诗：“平生丘壑志，眷焉怀在昔。”；唐钱起《罢章陵令山居过中峰道者》诗之二：“丘壑趣如此，暮年始栖偃。”；幼舆，晋谢鲲的字。宋刘子翚《游龙潭》诗：“幼舆丘壑情，陶令琴觞趣。”；清陈宝琛《次韵答实甫见赠即送备兵钦廉》：“擅壑专丘犹未餍，可堪尘土涴衰颜。”；宋朱斌《书永和寺壁》诗：“胸中一壑本超然，投迹尘埃只可怜。”','[]',2),
(8500000000000000036,'泥封函谷',7,'典故','《东观汉记·隗嚣载记》：“嚣将王元说嚣曰：‘……今天水完富，士马最强，北取河西，东收三辅，案秦旧迹，表里山河。元请以一丸泥，为大王东封函谷关，此万世一时也。’”泥封函谷1:后以泥封函谷称关隘把守严密坚固。
一丸泥1:比喻以极少的力量，可以防守险要的关隘。
丸封1:谓防守严密。
丸泥塞1:指可防守的险要关塞。
关塞泥封1:指用少数人把守住要塞关隘。
函谷丸1:指有勇士把守的险隘。
函谷无泥1:犹言无泥封之固，谓难以固守。
塞丸泥1:谓可据险把守关隘。
封丸泥1:谓守险拒敌。
封泥1:谓关隘把守坚固。
封泥谷1:谓把守牢固的关隘。
请泥1:表示坚守关隘。
隗嚣泥1:指据险固守。','北周庾信《周大将军赵公墓志铭》：“赵失东渔，胡亡南牧，箭下辽城，泥封函谷。”宋黄庭坚《寄曹元忠》诗之三：“沙拥大江水，泥封函谷关。古来世上雄，宰木风雨寒。”；南朝梁刘孝威《倚宴赋得龙沙宵月明》诗：“请谢函关吏，行当泥一丸。”；清曹贞吉《百字令》：“泥丸封未得，渔阳鼙鼓，响入华清。”；唐唐彦谦《送樊琯司业归朝》诗：“未见泥函谷，俄惊火建章。”；清赵翼《南天门》诗：“险叶泥封谷，危如栈架桥。”；《晋书·吐谷浑传》：“以一丸泥封东关，封燕赵之路，迎天子于西京以尽遐藩之节。”唐李益《再赴渭北使府留别》诗：“平戎三尺剑，封缄一丸泥。”；宋王安石《西帅》诗：“一丸岂虑封函谷，千骑无由饮渭桥。”明夏完淳《大哀赋》：“封函谷之一丸，据雍州之九郡。”；清顾炎武《潼关》诗：“关中尚可一丸封，奉诏东征苦仓卒。”；明张煌言《山头重建海塘碑记》：“当我国家盛时，海波不扬，邑多贤长吏。而滨海丸封，又鲜戎马骚驿。”；清黄遵宪《题樵野丈运甓斋话别图》诗：“丸泥封函关，划道分鸿沟。”；清丘逢甲《三饶述怀》诗：“距关民气勇，乃过丸泥塞。”；卢前《折桂令·狮峰将台明傅友德讲武之所》曲：“指挥定边民多勇，更何须关塞泥封。”；南朝梁徐悱《古意酬到长史溉登瑯琊城诗》：“少年负壮气，耿介立冲冠。怀纪燕山石，思开函谷丸。”；宋杨亿《成都》诗：“张载勒铭堪作戒，莫矜函谷一丸封。”；南朝陈徐陵《劝进梁元帝表》：“洛阳未复，函谷无泥。旋驾金陵，方膺天眷。”；清王树枏《入子午谷》诗：“当关塞丸泥，诸葛不敢窥。”；明阮大铖《燕子笺·守溃》：“百二雄关，临风一剑寒。老当益壮，只手塞泥丸。”；宋陆游《书悲》诗：“何当受诏出，函谷封丸泥。”；唐太宗《入潼关》诗：“弃繻怀远志，封泥负壮情。”；唐骆宾王《北眺舂陵》诗：“既出封泥谷，还过避雨陵。”；元范梈《王继学晚过舍下翌日惠诗用韵答贶》：“自足封函谷，聊须垒受降。”；明海瑞《白下即事》诗：“北门宰相堪称钥，函谷将军罢请泥。”；唐罗隐《南园题》诗：“病怜王猛畚，愚笑隗嚣泥。”','[]',2),
(8500000000000000037,'弃书捐剑',7,'典故','《史记·项羽本纪》：“项籍少时，学书不成，去学剑，又不成。项梁怒之。籍曰：‘书足以记名姓而已，剑一人敌，不足学，学万人敌。’于是项梁乃教籍兵法。”弃书捐剑1:后因以弃书捐剑比喻立大志者不屑细事。
一书一剑1:喻局于一隅，气度狭隘。
一夫之敌1:指剑或剑术。
万人敌1:指兵法。战胜万人之术。
万人敌2:亦指勇力可敌万人。
敌万人1:喻指志向宏大。','宋苏轼《赠李彦威秀才》诗：“弃书捐剑学万人，纨袴儒冠皆误身。”；黄葆祯《杨哲商烈士悼歌》：“丈夫当学万人敌，一书一剑将何为?”；唐元稹《授杨元卿泾原节度使制》：“尝求三略之师，耻学一夫之敌。”；《三国演义》六六回：“昔战国时赵人蔺相如无缚鸡之力，于渑池会上，觑秦国君臣如无物，况吾曾学万人敌者乎!”；《三国志·程昱传》：“刘备有英名，关羽、张飞皆万人敌也。”；清丘逢甲《题易实甫所藏四叠前韵》：“此身未愿谋三窟，吾学原期敌万人。”','[]',2),
(8500000000000000038,'冯妇',7,'典故','《孟子·尽心下》：“晋人有冯妇者，善搏虎，卒为善士。则之野，有众逐虎。虎负嵎，莫之敢撄。望见冯妇，趋而迎之;冯妇攘臂下车。众皆悦之，其为士者笑之。”冯妇1:<u>冯妇</u>，古男子名，善搏虎，后用以称勇猛、凶狠的人。
一作冯妇1:喻重操旧业。
下马冯妇1:称重操旧业的人。
再作冯妇1:比喻重操旧业。
冯妇下车1:谓重操旧业。
冯妇车1:指善搏虎者所乘之车。
搏虎1:比喻同强敌作英勇斗争。
负隅顽抗1:谓依靠某种条件顽固抵抗。','宋黄庭坚《乙未移舟出》诗：“刘郎弓石八，猛气厌冯妇。”清林昌彝《市价行》：“贫民如瘦羊，商贾如饿虎。长官如冯妇，攘臂面如土。”；《聊斋志异·某乙》：“邑西某乙，故梁上君子也。其妻深以为惧，屡劝止之;乙遂翻然自改。居二三年，贫窭不能自堪，思欲一作冯妇而后已。”；《儿女英雄传》三三回：“我家虽不宽余，也还可以勉强温饱，都因我无端的官兴发作，几乎弄得家破人亡;还仗天祖之灵，才幸而作了个‘失马塞公’，如今要再去学那‘下马冯妇’，也就似乎大可不必了!”；清李元度《粉蝶儿·散勇归田留别诸好友》套曲：“休道是急流退勇，誓不做发棠攘臂下车冯。”；鲁迅《而已集·反“漫谈”》：“曾经有一位总长，听说，他的出来就职，是因为某公司要来立案，表决时可以多一个赞成者，所以再作冯妇的。”；《镜花缘》五一回：“愚姐久已心灰，何必又做冯妇?”；宋王安石《虎图》诗：“山墙野壁黄昏后，冯妇遥看亦下车。”；元李俊民《宣差射虎》诗：“眈眈来此被谁驱?不防邂逅冯妇车。”；柳亚子《有怀章太炎邹威丹两先生狱中》诗：“泣麟悲凤佯狂客，搏虎屠龙革命军。”；徐海东《奠基礼》：“最后牛元峰逃到镇东头的小寨里，指挥着一个多营负隅顽抗，死不投降。”；沈昌眉《和弟》：“北军豺当道，南军虎负隅。”','[]',2),
(8500000000000000039,'借寇恂',7,'典故','《后汉书·寇恂传》载：寇恂曾为颍川太守，颇著政绩，后离任。建武七年，光武帝南征隗嚣，恂从行至颍川，百姓遮道谓光武曰：“愿从陛下复借寇君一年。”借寇恂1:后因以借寇恂为地方百姓挽留良吏的典故。
一借之情1:指百姓挽留良吏的情思。
寇恂留1:称颂地方官深得民心。
州人借留1:称颂地方官德政卓著，深受人民爱戴挽留。
怀仁道并遮1:称赞地方官德政卓著，深受人民爱戴挽留。
河内之借1:称赞地方官德政卓著，深受人民爱戴。
遮道更借1:称颂地方官德政卓著，深受人民爱戴挽留。','唐元稹《代曲江老人百韵》：“内史称张敞，苍生借寇恂。”；南朝梁何逊《哭吴兴柳恽》诗：“霞区两借寇，贪泉一举卮。”；元李孝光《青玉案》词：“清都虎豹，借恂无计，衮职须君补。”；南朝梁沈约《齐故安陆昭王碑文》：“攀车卧辙之恋，争涂忘远;去思一借之情，愈久弥结。”；宋李曾伯《水调歌头·代寿昌州守叔祖》词：“谁为语廊庙，且许寇恂留。”；唐白居易《乔弁可巴州刺史制》：“州人借留，廉使置奏。既因会课，宜及陟明。”；《宋史·何承矩传》：“〔咸平〕三年，召还，拜引进使，州民百余诣阙贡马，乞借留承矩。”；唐柳宗元《同刘二十八院长述旧言怀》诗：“褒德符新换，怀仁道并遮。”；北周庾信《周柱国大将军长孙俭神道碑》：“河内之借，寇恂更惭谒帝;交州之请，士燮还著上表。”；唐王维《魏郡太守上党苗公德政碑》：“官吏百姓等或守阙乞留，或遮道更借。”','[]',2),
(8500000000000000040,'一傅众咻',7,'典故','《孟子·滕文公下》：“有楚大夫于此，欲其子之齐语也，则使齐人傅诸?使楚人傅诸?曰：使齐人傅之。曰：一齐人傅之，众楚人咻之，虽日挞而求其齐也，不可得矣;引而置之庄岳之间数年，虽日挞而求其楚，亦不可得矣。”一傅众咻1:一傅众咻，谓一人施教，众人喧扰。比喻所处环境不好，外来干扰太多。
一傅齐1:比喻势单力薄，支持赞同者少。
众人咻1:谓众口纷纭，妄加议论。
众楚群咻1:指众多外来的干扰。
咻已伙1:喻指众口纷纭，妄加议论。
咻楚1:喻外来众人干扰。
庄岳1:比喻好的合适环境。
楚人咻1:比喻所处环境不好，做事不能有所成就。','明陈确《答张考夫书》：“譬之与释子非佛教，与婆子言无阎王，一傅众咻，只自取困耳。”；明王守仁《与辰中诸生书》：“绝学之馀，求道者少，一齐众楚，最易摇夺。”；严复《癸丑上巳梁任公禊集万生园分韵流觞曲水》之三：“由来一傅齐，不救群吠蜀。椒兰各容长，屈景胥放逐。”；清黄遵宪《己亥续怀人诗》：“优孟衣冠笑沐猴，武陵胡服众人咻。”；清李渔《闲情偶寄·词曲上》：“百工居肆，欲其专也;众楚群咻，喻其散也。”；清黄遵宪《和周朗山见赠之作》：“立志不明随沉浮，一齐足敌众楚咻。”；宋王令《寄王正叔》诗：“奈何众好殊，未语咻已伙。”；宋陈三聘《三登乐·一品归来》词：“想当年、持汉节，众齐咻楚。丹忠此日，盛名千古。”；庄，战国时齐国的街名;岳是其里名。严复《与外交报主人论教育书》：“必欲使之大成，则亦有法，道在置之庄岳之间也。”；宋王安石《寓言》诗之二：“不得君子居，而与小人游……如傅一齐人，以万楚人咻。云复学齐言，定复不可求。”；清李渔《乔复生王再来二姬合传》：“随行婢仆皆南人，众音嘈嘈，我方病若楚咻。”','[]',2),
(8500000000000000041,'猿鹤沙虫',7,'典故','《艺文类聚》卷九十引晋葛洪《抱朴子》：“周穆王南征，一军尽化，君子为猿为鹤，小人为虫为沙。”今本《抱朴子·释滞》为“山徙社移，三军之众，一朝尽化，君子为鹤，小人成沙”。猿鹤沙虫1:后以猿鹤沙虫喻指阵亡将士或死于战乱的人。
一军猿鹤1:喻全军尽战死的将士。
化猿化鹤1:喻指逝世。
化虫沙1:喻指将士阵亡。
君子猿1:喻指有才德的阵亡将士。
君子猿鹤1:喻指阵亡的将士。
沙虫1:喻战乱死亡之人或因战乱而遭殃的民众。
猿啼鹤怨1:形容将士悲苦。
虫沙1:比喻战死的兵卒或死于战乱者。亦泛指一般百姓。
虫沙猿鹤1:指战死的将卒。','清黄遵宪《述闻》诗之二：“螟蛉果蠃终谁抚，猿鹤沙虫总可哀。”周实《痛哭》诗之四：“猿鹤沙虫同一烬，累累七十二荒坟。”；清沈钦圻《童奴石义托身于阮怀宁》诗：“沙虫猿鹤总消沉，大地旋看换涂轨。”；北周庾信《哀江南赋》：“小人则将及水火，君子则方成猿鹤。”；清孙致弥《同晙思大年访华天御先生》诗：“沧桑廿载衣冠在，猿鹤三军事业非。”；宋苏轼《咏郁孤台》诗：“不随猿鹤化，甘作贾胡留。”；清朱琦《关将军挽歌》：“猿鹤幻化那忍论，我为剪纸招忠魂。”；柳亚子《喜李直夫过谈》诗：“獭鱼鹯雀千秋史，猿鹤虫沙一例愁。”；清丘逢甲《秋怀次前韵》之八：“百战鱼龙残局短，一军猿鹤故山遥。”；傅尃《次韵答今希见过玉仙馆中留别》诗之三：“化猿化鹤朋游尽，一死一生交好希。”；金元好问《石岭关书所见》诗：“已化虫沙休自叹，厌逢豺虎欲安逃。”；陈毅《三十五岁生日寄怀》诗：“半壁河山沉血海，几多知友化沙虫。”；清赵翼《愍忠寺石坛相传唐太宗征高丽回瘗战骨处》诗：“岂乏功臣狗，兼多君子猿。”；北周庾信《和张侍中述怀》：“生民忽已鱼，君子徒为鹤。”；唐李白《古风》之二八：“君子变猿鹤，小人为沙虫。”；清赵翼《愍忠寺石坛相传唐太宗征高丽回瘗战骨处》诗：“邱貉尸难认，沙虫命总冤。”陶牧《和朴庵见答韵》：“沙虫吾辈归何用?风鹤人间郁不平。”；明汤显祖《牡丹亭·御淮》：“听得猿啼鹤怨，泪湿征袍如汗。”；唐罗隐《投湖南于常侍启》：“物汇虽逃于刍狗，孤寒竟陷于虫沙。”唐黄滔《周以龙兴赋》：“子蛮貊而虫沙附，甲忠信而鬐鬣张。”；唐韩愈《送区弘南归》诗：“穆昔南征军不归，虫沙猿鹤伏似飞。”清陈康祺《郎潜纪闻》卷十四：“虫沙猿鹤，忠义如林。”；蛤笑《息争篇》：“呜呼!一军虫鹤，犹争傀首之雌雄;两戒河山，知是谁家之门户。”','[]',2),
(8500000000000000042,'挂冠',7,'典故','晋袁宏《后汉纪·光武帝纪五》：“〔逢萌〕闻王莽居摄，子宇谏，莽杀之。萌会友人曰：‘三纲绝矣，祸将及人。’即解衣冠，挂东都城门，将家属客于辽东。”《后汉书·逢萌传》亦载此事。又《南史·陶弘景传》载：南朝梁陶弘景，于齐高帝作相时，曾担任诸王侍读。他家贫，求作县令不得，乃“脱朝服挂神武门”，弃官而隐。挂冠1:后以挂冠指辞官、弃官。
一冠神虎悬1:谓辞官退隐。
冠宜挂1:谓适宜于辞官隐退。
挂朝衣1:指弃官。
挂衣冠1:指辞官。
神武挂衣冠1:谓辞官。
神武衣冠1:借指在朝为官。
衣冠挂神武1:指辞去朝官。
逢萌挂冠1:指弃官避祸。','宋叶適《祭韩子师尚书文》：“愤发挂冠，龠米自炊。”清孔尚任《桃花扇·入道》：“贫道张瑶星，挂冠归山，便住这白云庵里。”；唐孟云卿《新安江上寄处士》诗：“深潭与浅滩，万转出新安……即事遂幽赏，何必挂儒冠!”；北齐祖鸿勋《与杨休之书》：“东都有挂冕之臣，南国见捐情之士。”《春在堂随笔》卷二引《唐开成五年往生碑》：“遗民挂冕，康乐投簪，史氏称之，其风不泯。”；宋陆游《丁未除夕前二日休假感怀》诗：“挂冠神武莫踌躇，家具何妨载鹿车。”；南朝梁江淹《去故乡赋》：“出汀州而解冠，入溆浦而捐视。”；神虎，即神武。明徐渭《乐闲园》诗：“一冠神虎悬薇幕，五树鸣蝉种柳门。”；元白朴《庆东原》曲：“忘忧草，含笑花，劝君闻早冠宜挂。”；宋陆游《病中偶得名酒小醉作此篇》诗：“早挂朝衣归去是，贵人谁记接茵凭?”；南朝梁任昉《〈王文宪集〉序》：“三年，解丹阳尹……挂服捐驹，前良取则。”；唐钱起《酬陶六辞秩归旧居见柬》诗：“吾当挂朝服，同尔缉荷衣。”；宋刘克庄《最高楼》词：“辛亥后，六请挂衣冠。”；宋楼钥《访留昭文于范村山间不得见》诗：“可叹山中真宰相，未容神武挂衣冠。”；宋陆游《闻韩无咎下世》诗：“凭高老泪无挥处，神武衣冠挂已迟。”宋陈三聘《满江红·冬至》词：“神武衣冠惊梦里，江湖鱼钓论心曲。”；宋苏轼《次韵范纯父涵星砚月石风林屏诗》：“欲留衣冠挂神武，便击云水归南溟。”；明周履靖《锦笺记·协奏》：“我愿诸君学那逢萌挂冠。”','[]',2),
(8500000000000000043,'祢衡怀刺',7,'典故','《后汉书·祢衡传》：“〔祢衡(字正平)〕建安初，来游许下，始达颍川，乃阴怀一刺，既而无所之适，至于刺字漫灭。”祢衡怀刺1:后用为求人引荐的典故。
一刺空磨1:指无人可访，得不到接纳。
名纸毛生1:比喻长时间求谒而不得见。
怀刺1:谓准备谒见名流谋求功名。
抱刺于怀1:谓准备求人引荐。
漫刺1:指名刺。
灭刺1:指投靠无门。
祢刺1:谓士人耿介有节操，不愿奔走权门。','清尤侗《放歌五首》之一：“冯驩弹铗不见听，祢衡怀刺谁能投?丈夫出门无知己，不如还家对妻子。”；清赵翼《廉船老友不见三十年矣兹来晤扬州斐然有作》诗之二：“敬礼定文期后世，正平怀刺向何方?”；宋王令《上杭帅吕舍人》诗：“毛生祢衡刺，麻系吕毉鞋。”；清赵翼《壬申下第作》诗之三：“笑看祢衡名刺在，已经磨灭字都湮。”；清黄景仁《重至当涂怀稚存》诗之二：“六棺未葬悲元振，一刺空磨叹祢衡。”；唐刘鲁风《江西投谒所知为典客所阻因赋》诗：“无钱乞与韩知客，名纸毛生不肯通。”；《魏书·元顺传》：“顺曾怀刺诣肇门，门者以其年少……不肯为通。”唐王绩《晚年叙志示翟处士》诗：“弱龄慕奇调，无事不兼修……弃襦频北上，怀刺几西游。”；《聊斋志异·叶生》：“抱刺于怀，三年灭字;侧身以望，四海无家。”；宋欧阳修《上胥学士启》：“是宜殚重趼宿舂之劳，怀漫刺署里之字。”元白珽《湛渊静语》卷二：“韩侂胄为相时，尝招致水心叶適，已在坐，忽门外有以漫刺求谒者，题曰：‘水心叶適候见。’”；清黄景仁《六叠前韵和余少云作》：“廿载行藏羞灭刺，两家骨肉笑围灯。”；唐黄滔《与蒋先辈启》之二：“足以雪曩岁之湮沉，恢张祢刺;壮平生之意气，弃掷终繻。”；唐司空曙《送卢堪》诗：“莫使祢生刺，空留怀袖中。”','[]',2),
(8500000000000000044,'铅刀一割',7,'典故','《后汉书·班超传》：“〔班超〕乃上疏请兵。曰：‘……昔魏绛列国大夫，尚能和辑诸戎，况臣奉大汉之威，而无铅刀一割之用乎?’”铅刀一割1:因以铅刀一割比喻虽然钝驽无能，但是还可一用。多用为自谦。
一割1:比喻行使一次或负责一次。
磨铅策蹇1:磨钝刀，鞭蹇驴。谦词，比喻勉力而为。
铅刀1:比喻无用的人或物。常用为谦词。
铅驽1:喻低微的能力。多为自谦。','晋左思《咏史》诗之一：“铅刀贵一割，梦想骋良图。”章炳麟《革命道德说》：”若曰是尚可行，则请与二三君子守此迂介，幸而时济，庶几比于铅刀一割。”；赵朴初《周总理挽诗》：“我惭驽骀姿，期效铅刀用。”；《梁书·孔休源传》：“臣以庸鄙，曲荷恩遇，方揣丹诚，效其一割。”明梅鼎祚《玉合记·赠处》：“陆则破驷，水则歼蛟，能忘一割之司，久作双函之秘。”；唐白居易《与陈给事书》：“可与进也，乞诸一言，小子则磨铅策蹇，骋力于进取矣。”；唐骆宾王《咏怀古意上裴侍郎》：“磨铅不沾用，弹铗欲谁申?”宋曾巩《英宗实录院谢赐御筵表》：“甫磨铅而就职，遽置醴以均恩。”；唐杨乘《甲子岁书事》：“腐儒一铅刀，投笔时感激。”；《宋史·朱昂传》：“愿在握而为剑，每辅衽而保裾。殊铅铦之效用，比硎刃而有余。”；《南齐书·王融传》：“但千祀一逢，休明难再，思策铅驽，乐陈涓壒。”','[]',2),
(8500000000000000045,'吴练',7,'典故','《太平御览》卷八一八引《韩诗外传》：“孔子、颜渊登鲁东山望吴昌门，渊曰：‘见一匹练，前有生蓝。’子曰：‘白马，芦蒭也。’”吴练1:后因以吴练代指白马。
吴练2:亦借指<u>吴</u><u>阊门</u>。
一匹练1:形容奔驰的白马。
吴门白马1:形容极目远眺。
白马之望1:指远眺。
白马吴阊1:形容登山极目远眺。
白马如练1:咏<u>吴</u>地风光。
辨练光1:形容有极强的洞察力。
辨马之峰1:指<u>泰山</u>。','唐刘威《伤曾秀才马》诗：“吴练已知随影没，朔风犹想带嘶闻。”；清徐晟《春感和舍弟漳州来韵》：“几曾极目观吴练，最是伤心续楚词。”；唐李白《赠武十七谔》诗：“马如一匹练，明日过吴门。”；清蒲松龄《登岱行》：“吴门白马望依稀，沧溟一掬堆琉璃。”；北周庾信《谢赵王示新诗启》：“曳练且观，无劳白马之望;流泉欲委，伫见青凫之飞。”；明袁宏道《出燕别大哥三哥》诗：“白马望吴门，惨淡无边际。”；明王世贞《登岱》诗：“依微白马吴阊在，欲向秋风问羽翰。”；北周庾信《哀江南赋》：“拥狼望于黄图，填卢山于赤县。青袍如草，白马如练。”；唐骆宾王《上廉察使启》：“登小鲁之山，辨练光于乱马;临大吴之国，识宝气于连牛。”；唐骆宾王《为齐州父老请陪封禅表》：“境接青畴，俯瞰获麟之野;山开翠屺，斜连辨马之峰。”','[]',2),
(8500000000000000046,'约法三章',7,'典故','《史记·高祖本纪》：“与父老约，法三章耳：杀人者死，伤人及盗抵罪。馀悉除去秦法。”约法三章1:后因用约法三章谓订立简明的条款，共同遵守。
一卒之令1:指死罪只有一条的法令。
三章法1:本指<u>汉高祖</u><u>刘邦</u>进入<u>咸阳</u>时与民约定的三条法律。后泛指法律或规章制度。
关中约法1:指<u>汉高祖</u><u>刘邦</u>初入关与父老订的约法三章。比喻简明法规。
汉三章1:借指国法。','元耶律楚材《怀古一百韵寄张敏之》：“约法三章日，恩垂四百基。”周克芹《许茂和他的女儿们》：“既是他自己求上门来，总得给他个约法三章。”；唐李商隐《赠送前刘五经映三十四韵》：“鼎新麾一举，革故法三章。”；汉桓宽《盐铁论·诏圣》：“高皇帝时，天下初定，发德音，行一卒之令，权也。”；明许自昌《水浒记·遣讯》：“速移文都城预约三章法，期上寿得荣夸。”《天雨花》五回：“堪怜已犯三章法，官牌火票要登门。”；《汉书·叙传下》：“革命创制，三章是纪，应天顺民，五星同晷。”《南史·袁昂传》：“莫不严五辟于明君之朝，峻三章于圣主之日。”；唐杨炯《奉和上元酺宴应诏》：“汉后三章令，周王五伐兵。”；唐骆宾王《畴昔篇》诗：“慎罚宁凭两造辞，严科直挂三章律。”；唐李商隐《今月二日不自量度辄以诗一首四十韵干<span class="PUC03_e0">&#xe060;</span>尊严》：“愿守三章约，还期九译通。”；宋汪元量《贾魏公府》诗：“关中新约法，江左旧清谈。”；唐李商隐《故番禺侯以赃罪致不辜事觉》诗：“杀人须显戮，谁举汉三章?”','[]',2),
(8500000000000000047,'燕市悲歌',7,'典故','《史记·刺客列传》载：“荆轲既至燕，爱燕之狗屠及善击筑者高渐离。荆轲嗜酒，日与狗屠及高渐离饮于燕市，酒酣以往，高渐离击筑，荆轲和而歌于市中，相乐也;已而相泣，旁若无人者。”后经田光推荐，被燕太子丹尊为上卿，并担当了出使秦国行刺秦王的重任。“太子及宾客知事者，皆白衣冠以送之。至易水之上，既祖，取道，高渐离击筑，荆轲和而歌，为变徵之声，士皆垂泪涕泣。又前而为歌曰：‘风萧萧兮易水寒，壮士一去兮不复还!’复为羽声忼慨，士皆瞋目，发尽上指冠。于是荆轲就车而去，终已不顾。”《战国策·燕策三》亦载。燕市悲歌1:后以燕市悲歌抒发慷慨悲世之情。
一去不复返1:本谓一去之后就不再回来。后亦指事物已成陈迹，不会再出现或大势已去，不能挽回。
击筑1:喻指慷慨悲歌或悲歌送别。
击筑人1:借指慷慨悲歌的豪侠之士。
击筑悲歌1:形容慷慨悲歌。
壮发冲冠1:形容气概豪迈雄伟。
悲歌击筑1:抒写悲壮苍凉的气氛或情怀。
易水1:借指饯行送别之地。
易水2:亦借指<u>荆轲</u>。
易水别1:借指生离死别。
易水客1:指刺<u>秦王</u>的壮士<u>荆轲</u>。
易水歌1:借指离别的悲歌。用以表现慷慨悲壮的气概或悲壮苍凉的气氛。
易水萧萧1:形容悲壮苍凉的氛围。
易水风1:借指悲壮侠勇的气概。
歌易水1:吟唱悲壮之歌，抒发悲壮慷慨的情怀。
渐离击筑1:形容悲壮凛然的气概。
燕市筑1:指豪侠之士所奏演的悲壮之声。
燕市荆高1:借指慷慨激昂之义士。
燕歌1:借指慷慨悲壮之歌。
荆卿1:指<u>荆轲</u>。
荆卿2:亦指行险之人。
荆卿歌1:指慷慨悲壮的《易水歌》。亦借指抒发悲壮情怀的歌。
荆卿燕市1:指侠士的豪放行为。
荆卿适秦1:指壮士视死如归，慷慨赴难。
荆歌高筑1:借指豪侠之士的慷慨悲壮的行为。
荆高1:指<u>荆轲</u>与<u>高渐离</u>。借指任侠行义之士。
萧萧易水1:形容悲壮苍凉的气氛。
高歌酒市1:指侠义之士慷慨激昂的行为。','明徐渭《寄京中诸公援者》诗：“夷门老监屠存赵，燕市悲歌泪数君。”也用以抒写惜别的友情。唐李涉《送魏简能东游》诗之二：“燕市悲歌又送君，目随征雁过寒云。”；唐崔颢《黄鹤楼》诗：“黄鹤一去不复返，白云千载空悠悠。”老舍《最值得歌颂的事》：“她们享受着自由、平等与幸福的家庭生活，她们以泪洗面的日子一去不复返了。”；明张煌言《愁泊》诗：“往事分明堪击筑，浮生那得数衔杯。”郁达夫《金缕曲·寄北京丁巽甫杨金甫仿顾梁汾寄吴季子》词：“记离时，都门击筑，汉皋赌酒。”；明陈子龙《春晚王京兆邀游城南韦园》诗之三：“我思击筑人，萧条千里暮。”清孔尚任《桃花扇·草檄》：“三更忽遇击筑人，无故悲歌必有因。”；宋刘过《贺新郎》词：“男儿事业无凭据，记当年、击筑悲歌，酒酣箕踞。”；唐杨炯《遂州长江县先圣孔子庙堂碑》：“公雄心烈眦，壮发冲冠，按东海之金刀，飞北斗之石箭。”；宋陆游《老将》诗：“百战西归变姓名，悲歌击筑醉湖城。”；清丘逢甲《十一月用久旱得雨初霁饮人境庐时闻和局将定诗韵》之二：“悲歌易水无豪侠，买骨金台有钝驽。”；明何景明《易水行》：“寒风夕吹易水波，渐离击筑荆轲歌。”；清吴伟业《又咏古》之五：“古来有烈士，轵里与易水。”；唐李白《留别于十一兄逖裴十三游塞垣》诗：“耻作易水别，临歧泪滂沱。”；唐骆宾王《咏怀古意上裴侍郎》诗：“徒歌易水客，空老渭川人。”；唐骆宾王《夏日游德州赠高四》诗：“白雪《梁山曲》，寒风《易水歌》。”；北魏杨衒之《洛阳伽蓝记·法云寺》：“延伯每临阵，常令僧超作壮士声，甲胄之士莫不踊跃。”；北魏杨衒之《洛阳伽蓝记·法云寺》：“有田僧超者善吹笳，能为‘壮士歌’、‘项羽吟’。征西将军崔延伯甚爱之。”；唐李白《结客少年场行》诗：“羞道易水寒，从今日贯虹。”；唐李白《发白马》诗：“武安有振瓦，易水无寒歌。”；宋陆游《读史有感》诗：“隆中高卧人千载，易水悲歌泪数行。”；元刘秉《清风十韵》：“易水离歌阕，齐纨怨思新。”；明张煌言《挽华吉甫明经》诗：“更闻锻炼神偏壮，慷慨如歌《易水辞》。”；宋辛弃疾《贺新郎·别茂嘉十二弟》词：“易水萧萧西风冷，满座衣冠似雪。”；唐许浑《送从兄归隐兰溪》诗之二：“夜忆萧关月，行悲易水风。”；宋陆游《遣怀》诗：“积愤有时歌易水，孤忠无路哭昭陵。”；《后汉书·延笃传》：“虽渐离击筑，傍若无人，高凤读书，不知暴雨，方之于吾，未足况也。”；清黄景仁《将之京师》诗：“吴市箫声燕市筑，一般凄断有谁怜?”；李详《湘绮先生却聘南下暂居上海赋此奉简》诗：“商山绮甪原难致，燕市荆高不可求。”；北周庾信《哀江南赋》序：“燕歌远别，悲不自胜。”宋梅尧臣《送李阁使知冀州》诗：“将军守汉法，壮士发燕歌。”；北周庾信《咏怀》之十：“李陵从此去，荆卿不复还。”；梁启超《上粤督李傅相书》：“公试一自思，则尽其全力为若曹作荆卿，于公何利焉?”；唐元稹《说剑》诗：“高唱荆卿歌，乱击相如缶。”；宋陆游《东屯高斋记》：“嗟呼，辞之悲乃至是乎!荆卿之歌，阮嗣宗之哭，不回于此矣!”；南朝梁江淹《泣赋》：“若夫景公齐山，荆卿燕市，孟尝闻琴，马迁废史。”；清黄鷟来《赠陈省斋》诗之四：“荆卿适秦时，白虹贯阳精。”；明陈子龙《寄郢中郑澹石座师》诗：“扼腕燕市何足贤，荆歌高筑徒茫然。”；清黄景仁《沁园春·王述庵先生斋头》词：“叹名场已醒，梦中蕉鹿;酒徒难觅，市上荆高。”；北周王褒《高句丽》诗：“萧萧易水生波，燕赵佳人自多。”；唐罗隐《黄鹤驿偶题》诗：“高歌酒市非狂者，大嚼屠门亦偶然。”','[]',2),
(8500000000000000048,'陈宝雄',7,'典故','《史记·秦本纪》：“〔文公〕十九年，得陈宝。”司马贞索隐：“按：《汉书·郊祀志》云：‘文公获若石云，于陈仓北阪城祠之，其神来，若雄雉，其声殷殷云，野鸡夜鸣，以一牢祠之，号曰陈宝。”张守节正义：“《括地志》云：宝鸡祠在岐州陈仓县东二十里故陈仓城中。《晋太康地志》云：秦文公时，陈仓人获得兽，若彘，不知名，牵以献之。逢二童子，童子曰：‘此名为媦，常在地中，食死人脑。’即欲杀之，拍捶其首。媦亦语曰：‘二童子名陈宝，得雄者王，得雌者霸。’陈仓人乃逐二童子，化为雉，雌上陈仓北阪，为石，秦祠之。《搜神记》云：其雄者飞至南阳，其后光武起于南阳，皆如其言也。”陈宝雄1:后以陈宝雄为王者之象征。
一双童子1:指传说中<u>战国</u><u>陈仓</u>人得怪物道遇的两童子。
天宝1:借指示瑞之兽。
宝鸡1:借誉鸡中之雄者。
宝鸡之瑞1:谓成就帝王之业的瑞应。
得雄之祥1:指王者之瑞。
瑞宝下陈仓1:谓天降祥瑞于帝王。
碧宝鸡1:戏称报晓的雄鸡。
秦祠1:指<u>秦穆公</u>(一说<u>秦</u><u>文公</u>)为<u>陈宝</u>所立之祠。
秦鸡1:指<u>陈宝</u>。
陈仓雉1:美称雉。
陈宝1:借指帝业。
飞雄雉1:指<u>东汉</u>王朝的发祥地<u>南阳</u>。','唐玄宗《幸凤泉汤》诗：“不重鸣岐凤，谁重陈宝雄?”；后用以咏陈仓。唐褚载《陈仓驿》诗：“锦翼花冠安在哉，雄飞雌伏尽尘埃。一双童子应惆怅，不见真人更猎来。”；唐李白《大猎赋》：“获天宝于陈仓，载非熊于渭滨。”；南朝陈徐陵《斗鸡诗》：“陈仓若有信，为觅宝鸡来。”；《北齐书·樊逊传》：“我太祖收宝鸡之瑞，握凤皇之书，体一德以匡朝，屈三分而事主，荡此妖寇，易如沃雪。”；晋潘岳《西征赋》：“宝鸡前鸣，甘泉后涌。”；唐刘肃《大唐新语·聪敏》：“汉光武膺得雄之祥，遂起南阳而有四海。”；唐贺知章《奉和御制春台望》诗：“尚有灵蛇下鄜畤，还征瑞宝下陈仓。”；唐李商隐《西南行却寄相送者》诗：“明朝惊破还乡梦，定是陈仓碧宝鸡。”；唐卢照邻《赠许左丞从驾万年宫》诗：“汉畤光如月，秦祠听似雷。”；秦穆公(一说秦文公)大猎，得其雌者，称霸。后用以咏秦地。唐沈佺期《夏日梁王席送张岐州》诗：“秦鸡常下雍，周凤昔鸣岐。”；南朝陈张正见《雉子斑》诗：“陈仓雉未飞，敛翮依芳甸。”；清王士禛《怀古诗三篇》之一：“七雄既龙斗，陈宝归嬴秦。”；清王士禛《南阳》诗：“炎精十世飞雄雉，鼎足三分起卧龙。”','[]',2),
(8500000000000000049,'一叶知秋',7,'典故','《淮南子·说山训》：“以小明大，见一叶落而知岁之将暮，睹瓶中之冰而知天下之寒。”一叶知秋1:看见一片落叶，就知道秋天来临。比喻由小见大，由细微的迹象就能推知事物发展变化的趋势。
一叶报秋1:喻年华流逝，行将衰老。
一叶秋1:指秋令。','宋赵长卿《品令·秋日感怀》词：“那堪更、一叶知秋后，天色儿、渐冷落。”郭沫若《洪波曲》六章：“要说梧桐一叶落而知秋的话，徐寿轩这一走也就表明了三厅的秋天的到来。”；唐鲍溶《始见二毛》诗：“百川赴海返潮易，一叶报秋归树难。”唐柳氏《杨柳枝》词：“一叶随风忽报秋，纵使君来岂堪折。”；唐元稹《赋得九月尽》：“霜降三旬后，蓂余一叶秋。”宋苏轼《过海得子由书》诗：“门外三竿日，江关一叶秋。”','[]',2),
(8500000000000000050,'索米长安',7,'典故','《汉书·东方朔传》载：东方朔(字曼倩)对汉武帝说：“朱儒长三尺余，奉一囊粟，钱二百四十;臣朔长九尺余，亦奉一囊粟，钱二百四十。朱儒饱欲死，臣朔饥欲死。臣言可用，幸异其礼;不可用，罢之，无令但索长安米也。”索米长安1:后因用索米长安指在京城谋求俸禄。
一囊1:谓官俸低微。
东方朔饿1:喻指官小俸微，生活窘困。
东方米1:指俸禄。
东方索米1:谓求取俸禄。
乞米长安1:指在京城谋求俸禄。
侏儒1:借指庸碌小人。
侏儒粟1:借指对国家贡献甚小之人的俸禄。
侏儒饱1:谓无用之人常得温饱。
方朔米1:指微薄的俸禄。
方朔苦饥1:指俸薄艰苦。
曼倩饥1:谓收入低微生活贫寒。
朔饥欲死1:形容俸微挨饿。
朔饥索米1:指小吏求俸。
索米1:谓求禄谋生。
臣朔苦饥1:借指俸薄生活难度。
苦饥方朔1:借指薪微生活贫苦的小吏。
金门索米1:谓在京城谋求俸禄。
长安米1:指京城俸禄。
长安米空索1:谓求利禄而不得。
长安索米1:谓在京城谋求俸禄。
长饥方朔1:借指低薪小吏。
饥曼倩1:指贫穷饥饿的低俸官员。
饱朱儒1:指得到温饱的无用之人。','宋杨亿《汉武》诗：“待诏先生齿编贝，那教索米向长安。”东方朔曾“待诏金马门”，故称。明沈德符《野获篇·吏部》：“劳苦已满考，且索米长安，冀增薄禄糊口耳。”；宋陆游《郊居》诗：“索米官仓例坐愚，东方未可戏侏儒。”；唐李贺《勉爱行二首送小季之庐山》之二：“辞家三载今如此，索米王门一事无。”；清尤侗《十二时·观猎》词：“索米金门，摊书玉局，见猎空欢喜。”；元马祖长《丁卯上京四绝》之四：“何如坐索长安米，只有诗歌满翰林。”；唐骆宾王《在江南赠宋五之问》诗：“犹轻五车富，未重一囊贫。”宋苏轼《张庖民挽词》：“故自轻千户，何曾羡一囊!”；清陈维崧《沁园春·为高汝敬尊公季远题像并赠汝敬》词：“北郭骚贫，东方朔饿，一片空庭扁豆花。”；清王摅《上宋寥天少宰》诗：“公孙早晚待开阁，吾知必念东方饥。”；宋王安石《次韵酬昌叔羁旅之作》：“自索东方米，谁多季子金?”；清尤侗《别长安》诗之八：“东方索米饥还甚，南郭吹竽病未能。”；清周士琦《玉漏迟·耦庚席上赋葛仙米》词：“相看勾漏云封，只乞米长安，甑尘闲笑。”；清钱谦益《送郭中书赵督师袁公幕》诗：“丈夫九尺身，岂肯随侏儒。”；清唐孙华《赠商州丞》诗之二：“终年未饱侏儒粟，昏夜频麾伯起金。”；宋黄庭坚《秘阁观苏子美题壁》诗：“不甘老天禄，试欲叫未央。小臣胆如斗，侏儒俸一囊。”；宋黄庭坚《次韵感春》之二：“东方九尺长，不得侏儒禄。”；宋陆游《晓出城东》诗：“包羞强索侏儒米，豪举何人记少年?”；唐白居易《得微之到官后书》诗：“侏儒饱笑东方朔，薏苡谗忧马伏波。”；清赵翼《吟芗殁于京邸》：“又停方朔米，谁斫蔡邕碑?”；清尤侗《得家信人有传予地震死者戏为作此》诗：“方朔苦饥后山冻，寒热小病皆行休。”；唐寒山《诗》之一二八：“只取侏儒饱，不怜方朔饥。”；唐许浑《早秋》诗之二：“老信相如渴，贫忧曼倩饥。”；唐卢照邻《双槿树赋》：“侏儒何功兮短饱，曼倩何负兮长贫。”；清尤侗《无酒歌》：“何况臣朔饥欲死，樵苏不爨突无烟。”；清赵怀玉《夺锦标·癸丑五日病中》词：“唐老为郎，朔饥索米，佳节又逢人病。”；宋杨万里《得小儿寿俊家书》诗：“汝翁在官缘索米，吾儿在家勉经史。”；徐道政《端阳顾竹侯招食粽》诗：“自到长安米如珠，臣朔苦饥涎空嗌。”；清王鹏运《摸鱼子》词：“叹臣朔常饥，将军负腹，奇气向谁吐?”；戴德章《补题三十二岁衣冠小影》诗之一：“独怜扪此皤然腹，举世谁知臣朔饥?”；清曹贞吉《百字令·朱锡鬯过访不值怅然有寄》词：“日跳如丸，臣饥似朔，那得名心热?”；清尤侗《沁园春·和阮亭偶兴》词之二：“奈举国侏儒，臣饥欲死;满堂酒汉，公醒而狂。”；宋张耒《次韵奉酬无咎兼呈慎思天启》：“苦饥方朔身漫长，颠毛种种颜欲苍。”；清吴绮《喜迁莺·次原韵送闳文归里》词：“回首处，是金门索米，凤池联翼。”；明徐渭《赠府吴公诗》：“诙谐并谢长安米，懒散犹供记室文。”；北周庾信《和张侍中述怀》：“汉阳钱遂尽，长安米空索。”；闽徐夤《嘉运》诗：“晨炊一箸红银粒，忆着长安索米秋。”；宋张元幹《再用韵奉留聪父》诗：“长饥方朔笑侏儒，岁晚还惊大小馀。”；清赵翼《七十自述》诗：“斗食敢嫌饥曼倩，书生荣誉是词曹。”；明徐渭《约观水阁往迟遂虚冯太常饭》诗：“何从一饱饥方朔，自买鱼虾入醉乡。”；清黄遵宪《新加坡杂语》诗之五：“人奴甘十等，只愿饱朱儒。”','[]',2),
(8500000000000000051,'一囊钱',7,'典故','《后汉书·赵壹传》载：赵壹，汉阳人。“作《刺世疾邪赋》，以舒其怨愤。曰……有秦客者，乃为诗曰：河清不可俟，人命不可延。顺风激靡草，富贵者称贤。文籍虽满腹，不如一囊钱。伊优北堂上，抗脏倚门边。”一囊钱1:后因以一囊钱为世风不正、重财轻才的典故。
一囊贫1:指些许钱财。
囊钱赵壹轻1:指世风不正，重财轻才。
汉阳钱1:<u>汉阳</u>，借指<u>赵壹</u>。泛指钱囊或钱财。
赵壹囊1:泛指贫士的钱囊。
赵壹钱1:指些许钱财。','宋陆游《秋兴》诗：“百岁犹穿几两屐，千诗不及一囊钱。”；唐骆宾王《在江南赠宋五之问》诗：“犹轻五车富，未重一囊贫。”；清顾炎武《子德李子闻余在难》诗：“禄位扬雄小，囊钱赵壹轻。”；北周庾信《和张侍中述怀》：“漂流从木梗，风卷随秋箨。张翰不归吴，陆机犹在洛。汉阳钱遂尽，长安米空索。”；宋陆游《次韵郑盱眙见寄》：“两章英妙同时到，赵壹囊中却未贫。”；宋王禹偁《谢赐御书字样钱表》：“臣等名惭夷甫，才谢鲁褒。实赵囊而空荷君恩，探禹穴而难穷圣作。”；宋陆游《夜酌》诗：“腰下苏秦印，囊中赵壹钱。”','[]',2),
(8500000000000000052,'壶中天',7,'典故','《后汉书·费长房传》载：费长房为市掾时，市中有老翁卖药，悬一壶于肆头，市罢，跳入壶中。费长房于楼上见之，知为非常人。壶中天1:次日复诣翁，翁与俱入壶中，唯见玉堂严丽，旨酒甘肴盈衍其中，共饮毕而出。
一壶中1:喻仙境、胜境。
入壶1:谓进入仙境。
壶中客1:喻指仙人。
壶公1:传说中的仙人。
壶公术1:指仙道变化。
天地一壶1:指仙家通神变化。
小壶天1:指仙境、胜境。
悬壶1:古代指行医卖药。
玉壶1:用指仙境。
玉壶先生1:指神仙<u>壶公</u>，亦泛指得道高人。','又《云笈七签》卷二八引《云台治中录》：“施存，鲁人。夫子弟子，学太丹之道……常悬一壶如五升器大，变化为天地，中有日月，如世间。夜宿其内，自号‘壶天’，人谓曰‘壶公’。”后以壶中天谓仙境，胜境。唐白居易《酬吴七见寄》诗：“谁知市南地，转作壶中天。”宋陆游《壶天阁》诗：“乃知壶中天，端胜缩地脉。”；宋孔平仲《小庵初成奉酬元师》诗：“自有琴书增道气，别开世界在仙壶。”；唐王起《赠毛仙翁》诗：“壶中世界青天近，洞里烟霞白日间。”；唐宋之问《送田道士使蜀投龙》诗：“人隔壶中地，龙游洞天里。”；宋范成大《浙东参政寄示会稽蓬莱阁诗轴次韵》：“尘埃不隔壶中境，功业犹关物外身。”；唐元稹《幽栖》诗：“壶中天地乾坤外，梦里身名旦暮间。”；唐钱起《送柳道士》诗：“海上春应尽，壶中日未斜。”；唐吕岩《七言》诗之九：“物外烟霞为伴侣，壶中日月任婵娟。”；唐许浑《赠萧炼师》诗：“壶中知日永，掌上畏年侵。”；唐许浑《移摄太平寄前李明府》诗：“娇歌自驻壶中景，艳舞长留海上春。”；唐戴叔伦《赠韩道士》诗：“东城南陌频相见，应是壶中别有家。”；明邵璨《香囊记·题诗》：“开山种玉，点石成金。壶中甲子潜消，洞里乾坤不老。”；唐李端《游终南山因寄苏奉礼士尊师苗员外》诗：“壶中开白日，雾里卷朱旗。”；唐窦常《茅山赠梁尊师》诗：“上象壶中阔，平生醉里忙。”；宋张炎《青玉案·闲居》词：“尘留不住，云留却住，壶内藏古今。”；唐张乔《题古观》诗：“洞水流花早，壶天闭雪春。”；唐钱起《柏崔老人号无名先生男削发女黄冠自以云泉独乐命余赋诗》：“鹤前飞九转，壶里住三光。”；明杨慎《折桂令·道情》曲：“壶里乾坤，物外云林，平地烟霞，山水清音。”；元王恽《仙游曲》之五：“金简朝元拥玉华，碧壶香满谪仙家。”；宋苏轼《刁景纯席上和谢生》之一：“误入仙人碧玉壶，一欢那复问亲疏。”；唐王维《赠焦道士》诗：“坐知千里外，跳向一壶中。”；元许有壬《琳宫词次安南王韵》：“一壶天地浑无迹，只有清风动竹声。”；唐储嗣宗《送道士》诗：“药炉经月净，天路入壶深。”；唐马戴《谒仙观》诗之二：“愿值壶中客，亲传肘后方。”；唐李商隐《题道静院写真存焉》诗：“壶中别有仙家日，岭上犹多隐士云。”；北魏郦道元《水经注·汝水》：“昔费长房为市吏，见王壶公悬壶郡市，长房从之，因而自远，同入此壶，隐沦仙路。”明高启《鹤瓢》诗：“壶公本解飞腾术，丁令宁为濩落材!”；唐钱起《药堂秋暮》：“勉事壶公术，仙期待赤龙。”；唐吴融《湖州晚望》诗：“他年若得壶中术，一簇汀洲尽贮将。”；南唐李中《寄杨先生》诗：“莫把壶中秘诀，轻传尘里游人。”；元宋无《寄眠云处士》诗：“蓟子家尝历，壶公诀尽传。”；宋刘克庄《汉宫春·吴侍郎生日》词：“试问取，壶翁仙诀，几时传与君房?”；唐刘禹锡《寻汪道士不遇》诗：“笙歌五六里，天地一壶中。”；宋仲并《水调歌头》词：“华栋一何丽，移下小壶天。几多曲房新户，缥缈似当年。”；明吴承恩《寿王可斋七秩幛词》：“膝下儿孙，庆悬壶之有继。”；清侯方域《赠武林陈文学》诗：“远志分明为采药，携壶不尽是逃名。”；唐陈子昂《感遇》诗之五：“曷见玄真子，观世玉壶中。”清孔尚任《桃花扇·入道》：“玉壶琼岛，万古愁人少。”；唐鲍溶《周先生画洞庭歌》诗：“疑君如有长生路，玉壶先生在何处?”','[]',2),
(8500000000000000053,'玉壶冰',7,'典故','南朝宋鲍照《代白头吟》：“直如朱丝绳，清如玉壶冰。”玉壶冰1:后因以玉壶冰喻人品格高洁。
一壶冰1:喻品格高洁之人。
一片冰心1:指高洁之心。
冰壶1:借指清白廉洁的品德。
白玉壶冰1:喻品格高洁。
鲍壶冰1:喻高洁的品格。
冰壶秋月1:后因以比喻心地清明洁净。','唐李商隐《别薛岩宾》诗：“清规无以况，且用玉壶冰。”宋黄庭坚《奉和公择舅氏送吕道人研长韵》：“奉身玉壶冰，立朝朱丝弦。”；唐李商隐《闻著明凶问哭寄飞卿》诗：“空馀双玉剑，无复一壶冰。”；唐王昌龄《芙蓉楼送辛渐》诗：“洛阳亲友如相问，一片冰心在玉壶。”；唐姚崇《冰壶诫序》：“内怀冰清，外涵玉润，此君子冰壶之德也。”明孙柚《琴心记·王孙作醵》：“官况托冰壶，友谊敦芳醑。数载梦中孤，今日樽前聚。”；唐李白《赠清漳明府侄聿》诗：“白玉壶冰水，壶中见底清。”；唐李商隐《今年二日不自量度》诗：“鲍壶冰皎洁，王佩玉丁东。”；宋苏轼《赠潘谷》诗：“布衫漆黑手如龟，未害冰壶贮秋月。”《宋史·李侗传》：“愿中如冰壶秋月，莹彻无瑕，非吾曹所及。”','[]',2),
(8500000000000000054,'食鸡肋',7,'典故','《三国志·魏武帝纪》“备因险拒守”裴松之注引晋司马彪《九州春秋》：“时王(指曹操)欲还，出令曰：‘鸡肋’。官属不知所谓。主簿杨修便自严装，人惊问修：‘何以知之?’修曰：‘夫鸡肋，弃之如可惜，食之无所得，以比汉中，知王欲还也。’”食鸡肋1:后因以食鸡肋比喻做无多大意义而又不忍舍弃的事情。
一官鸡肋1:形容对为官兴趣的淡薄。
曹瞒说鸡肋1:指无多大价值的事物。
鸡肋11:比喻无多大意义而又不忍舍弃的事物。','宋苏轼《相视新河秉道有诗次韵》之一：“从来自笑画蛇足，此事何殊食鸡肋。”；清徐乾学《请告得旨留别诸公》诗：“一官鸡肋中情淡，万卷牛腰远道难。”；宋黄庭坚《又借答送蟹》诗：“恐似曹瞒说鸡肋，不比东阿举肉山。”瞒，曹操小名。；宋杨万里《晓过皂口岭》诗：“半世功名一鸡肋，平生道路九羊肠。”李存葆《高山下的花环》三：“某些领导对咱看不惯，把咱当成‘鸡肋’!”','[]',2),
(8500000000000000055,'绨袍惠',7,'典故','《史记·范雎蔡泽列传》载：战国魏人范雎先事魏中大夫须贾，遭其谤，被笞辱，逃秦，改名张禄，仕秦为相。魏派须贾出使秦国，范雎乔装，敝衣往见。须贾意哀之，留与坐饮食，曰：“范叔一寒如此哉!”绨袍惠1:乃取其一绨袍以赐之。
一寒如此1:谓贫困潦倒至极。
寒范叔1:喻指贫寒落魄之人。
恋绨袍1:指不忘救助之恩。
有意袍1:喻指友人所赠深含情意的寒衣。
望绨袍1:指期待别人救助。
绨袍信1:喻指老友念旧，守信。
绨袍恋恋1:形容在贫困中旧友情深，关怀备至。
绨袍故1:指贫困相助的故人旧友。
绨袍范叔1:借指急需救助的困中之人。
绨袍高义1:指济人困厄的高尚情义。
范叔寒1:借指士人处境贫寒。
范叔袍1:指敝衣薄袍。
解绨1:借指济困。
赠绨袍1:喻指友人馈赠寒衣。
遗绨袍1:借指济人困厄。
问绨袍1:谓关怀友人嘘寒问暖之意。','后贾知雎即秦相张禄，乃惶恐请罪。雎以贾尚有绨袍念旧之情，终宽释之。后因以绨袍惠为贫困中有人念旧施惠之典。唐白居易《醉后狂言酬赠萧殷二协律》诗：“宾客不见绨袍惠，黎庶未沾襦裤恩。”；清查慎行《敝裘》诗之一：“布褐不妨为替代，绨袍何取受哀怜?”柳亚子《自题辽东夜猎图》诗：“题诗却念旧王孙，绨袍怜我交情负。”；宋刘克庄《贺新郎·六用韵叙谪仙事为宫教兄寿》词：“叹今日布衣交薄，绨袍情少。”；宋王安石《和耿天骘》：“故人恋恋绨袍意，岂为哀怜范叔寒。”《聊斋志异·嫦娥》：“曩试君心耳，幸绨袍之意犹存。”；唐高適《咏史》：“尚有绨袍赠，应怜范叔寒。”唐岑参《尚书念旧垂赐袍衣》诗：“绨袍更有赠，犹荷故人怜。”；宋范成大《再游上方》诗：“范叔一寒如此，刘郎前度曾来。”元方回《次韵许大初见赠》：“赖是同乡复同味，一寒如此遽还春。”；清吴绮《水调歌头·别其年》词：“贫孺子，寒范叔，漫求怜。丈夫豪气，自应举步有云烟。”；宋范成大《次韵姜尧章雪中见赠》诗：“当时访戴舟，却访一寒范。”；唐柳宗元《游南亭夜还叙志七十韵》：“知罃怀褚中，范叔恋绨袍。”；宋范成大《春晚即事留游子明王仲显》诗：“笑我生尘甑，惭君有意袍。”；清方文《赠章翌兹司理》诗：“岂不望绨袍?欲语心悲酸。”；宋苏轼《用旧韵送鲁元翰知洺州》：“永谢十年旧，老死三家村。惟君绨袍信，到我雀罗门。”；清黄景仁《丰乐楼·闻龚梓树携室之河南》：“当年落魄，头蒙败絮，身被短褐，非足下，绨袍恋恋何人者?”；宋黄庭坚《和答魏道辅寄怀》：“谅无绨袍故，尽是白头新。”；明李东阳《春寒二十韵》：“绨袍范叔谁相恋，大被姜郎且共荣。”；清宋琬《赠吴伯成》诗：“此夕论文重下榻，绨袍高义未能忘。”；明李东阳《困暑次韵白洲》诗：“亦有岁寒交，绨袍义思范。”；清宋琬《满江红·王西樵客游武林曹顾庵赋词志喜属予和之》词之二：“庄舄悲歌燕市外，灵均憔悴江潭上。问绨袍高谊还有无，谁曾饷?”；唐刘长卿《送张判官罢使东归》诗：“范叔寒犹在，周王岁欲除。”宋陈师道《简杨安国》诗：“侯门谁预识冯谖，岁晚宁知范叔寒。”；清毛奇龄《冬日过上海署故人任明府制衣衣我感赋》：“顾此短褐不至骭，恻然为念范叔僵。”；清归庄《与顾宁人书》：“不忧苏季裘敝，范叔衣寒。”；宋苏轼《崔文学甲携文见过萧然有出尘之姿》诗：“敝衣破冠履，可怜范叔贫。”；清黄景仁《赠陈秋士》诗：“投布识范寒，分金补颜空。”；清方文《与小范集任克家斋头》诗：“索酒共眠任昉宅，解衣谁念范雎寒?”；宋苏轼《雪诗》之三：“半夜欺陵范叔袍，更兼风力助威豪。”清赵翼《前守韦缘事罢官诗以送别》之二：“民犹争诵廉公裤，我敢相矜范叔袍?”；清顾炎武《酬归祚明等四子韭溪草堂联句见怀二十韵》：“卧冷王章被，穷馀范叔绨。”；明李东阳《畏吾村先墓忽枉刘司马见过感而有诗》：“巨卿白马期再到，范叔绨袍义可忘?”；李光《河山四律》诗之三：“丘坟我已悬徐剑，湖海人犹著范袍。”；清杜岕《雪兴》诗：“愁披周穆传，寒忍范雎袍。”；清李邺《万考叔客寓明州有赠》诗：“座上解绨徒有意，市中击筑竟谁逢?”；清徐文烜《浙东别友人》诗：“感君多意气，不必赠绨袍。”；清吴伟业《途中遇雪即事言怀》诗：“久病人贻药，长途友赠绨。”；唐杜甫《王阆州筵奉酬》诗：“吾舅惜分手，使君寒赠袍。”；宋陆游《雨欲作步至浦口》诗：“宋清捐善药，须贾遗绨袍。”；元李孝光《饮濡须守子衡君宅》诗：“赖有使君持玉节，未须故旧问绨袍。”','[]',2),
(8500000000000000056,'寸草春晖',7,'典故','唐孟郊《游子吟》诗：“慈母手中线，游子身上衣，临行密密缝，意恐迟迟归。谁言寸草心，报得三春晖。”寸草春晖1:后以寸草春晖喻子女报答不尽父母养育之恩。
一寸春晖1:喻儿女对父母的深恩所报甚少。
三春寸草1:喻父母养育之恩。
三春晖1:指春天的阳光。比喻母爱。亦喻深厚的恩情。
寸草之心1:指子女对父母回报的微小心意。
寸草心1:指子女回报父母的心意。
报春晖1:喻报答父母养育之恩。
春晖1:比喻慈母之恩。
春晖寸草1:比喻母亲对子女的恩情。
游子线1:比喻母爱。','明何景明《过先人墓示彭天章》诗：“此身如寸草，何以答春晖?”明汪廷讷《种玉记·荣寿》：“爱寸草春晖，衣紫拖朱满膝前。”；明张煌言《追慕》诗之一：“金革三年泪，冰霜寸草晖。”；清董元凯《沁园春·寸草》词：“色想罗裙，叶成书带，一寸春晖报未曾。”；宋苏舜钦《送子履》诗：“君亲恩大须荣报，学取三春寸草微。”；《诗刊》1977年6期：“何当得报三春晖，献给恩人毛泽东。”；明梁辰鱼《浣纱记·论侠》：“孝道略尽，忠诚未孚，思欲报寸草之心，申倾葵之意。”；清方文《祀灶夜泊鲁港》诗：“瓣香无处迎先祖，寸草何时报老亲?”；明汤显祖《牡丹亭·训女》：“眼见春如许，寸草心，怎报得春光一二。”；宋孔平仲《次韵和常父发越州》诗：“薄宦牵挛不得已，此心何以报春晖?”；明朱鼎《玉镜台记·寄家书》：“念我曹，还待要报答春晖，克全子道。”；清唐孙华《进呈御览诗》：“高厚恩何报，春晖寸草茎。”；明何景明《过先墓》诗：“一寸未忘游子线，万年难觅老莱衣。”','[]',2),
(8500000000000000057,'新丰客',7,'典故','《旧唐书·马周传》：“〔马周字宾王〕舍新丰逆旅，主人不之顾。周命酒一斗八升，悠然独酌，众异之。至长安，舍中郎将常何家。贞观五年，诏百官言得失。何，武人，不涉学问，周为条二十余事，皆当世所切。太宗怪问何，何曰：‘此非臣所能，家客马周教臣言之。客，忠孝人也。’帝即召之……与语，帝大悦，诏直门下省。明年，拜监察御史。”新丰客1:后因以新丰客指怀才不遇、行旅在外遭冷落的人。
一尊独酌1:形容怀才未遇寒士的旷达情怀。
买酒醉新丰1:指文士的豪气。
倦客新丰1:指富有才干而壮志难酬的人物。
呼酒新丰1:形容穷士的旷达豪爽。
困马周1:喻指怀才未遇之士。
新丰旧雨1:指困于羁旅的老朋友。
新丰独酌1:形容怀才未遇的穷士以酒浇愁。','唐李贺《致酒行》：“吾闻马周昔作新丰客，天荒地老无人识。”元杨云鹏《秋晚登宪陵台》诗：“布衣谁识新丰客，独对秋风酒一杯。”；宋张耒《马周》诗：“一尊独酌岂无意，俗子不解知英雄。”；宋陆游《谢王子林院判惠诗编》诗：“骑驴上灞桥，买酒醉新丰。”；宋辛弃疾《满江红》词：“倦客新丰貂裘敝，征尘满目。”；元周权《次韵令尹解官归九江》：“解官彭泽如元亮，呼酒新丰似马周。”；明单本《蕉帕记·备聘》：“你不要把龙生看左了，他是个困马周未把才华显。”；宋张炎《台城路·寄姚江太白山人陈文卿》词：“太白闲云，新丰旧雨，多少英游消歇。”；宋陆游《十一月三日过升仙桥作》诗：“纷纷满座谁能识，大似新丰独酌时。”；宋陆游《秋雨叹》诗：“公车自荐心实耻，新丰独饮人所惊。”','[]',2),
(8500000000000000058,'百万呼卢',7,'典故','《晋书·刘毅传》：“后于东府聚摴蒲大掷，一判应掷数百万……毅次投得雉，大喜，褰衣绕床，叫谓同座曰：‘非不能卢，不事此耳。’裕恶之，因挼五木久之，曰：‘老兄试为卿答。’既而四子俱黑，其一子转跃未定，裕厉声喝之，即成卢焉。”《宋书·武帝纪》：“玄自闻军起，忧惧无复为计。或曰：‘刘裕等众力甚弱，岂办之有成……’玄曰：‘刘裕足为一世之雄;刘毅家无担石之储，摴蒲一掷百万;何无忌，刘牢之甥，酷似其舅。共举大事，何谓无成?’”百万呼卢1:本形容赌注极大，后亦用以形容举动非凡，气概豪迈。
一掷成卢1:喻取胜占先。
一掷百万1:形容赌注极大或举动非同一般。
呼卢胜1:指欢宴嬉戏。
成卢1:指赌博获胜。','宋陆游《武昌感事》诗：“百万呼卢事已空，新寒拥褐一衰翁。”；唐李白《少年行》之三：“呼卢百万终不惜，报仇千里如咫尺。”；清王士禛《丹徒行吊宋武帝》诗：“摴蒲百万皆人豪，龙行虎步非凡理。”；明杨基《醉歌行赠朱彦明别》诗：“英雄百万赌一掷，肯对儿童夺升斗。”清唐孙华《时世公子行》：“呼卢博簺穷昼夜，百万一掷同秋毫。”；宋陆游《三山卜居今三十有三年矣》诗：“再见封侯未成快，一掷成卢安用再?”；《醉醒石》七回：“到那赌，刘毅一掷百万，是顷刻间可以破家的。”；唐吴象之《少年行》：“一掷千金混是胆，家无四壁不知负。”老舍《四世同堂》三十：“甘心作奴隶的人是不会豪放的;敢一掷千金的人必不肯由敌手下乞求一块昭和糖吃。”；宋刘筠《夜宴》诗：“笑逐呼卢胜，歌随解佩狂。”；清吴伟业《哭志衍》诗：“绝叫忽成卢，众手皆敛却。”','[]',2),
(8500000000000000059,'八斗才',7,'典故','宋无名氏《释常谈·八斗之才》：“文章多，谓之‘八斗之才’。谢灵运尝曰：‘天下才有一石，曹子建独占八斗，我得一斗，天下共分一斗。’”八斗才1:后以八斗才比喻高才，有学问。
一斗之才1:比喻才能平庸一般。
才夸八斗1:谓夸耀才华出众。
才当曹斗1:谓高才，才学出众。
才无一斗1:喻才能平庸一般。
才高八斗1:形容富于文才。
计斗负才1:比喻才高。
陈思八斗1:称誉高才。
陈思才藻1:称誉文才出众之士。','闽徐夤《献内翰杨侍御》诗：“欲言温署三缄口，闲赋宫词八斗才。”；唐赵嘏《广陵答崔琛》诗：“八斗已自传姓字，一枝何足计行藏。”；宋刘筠《代意》诗：“纵使多才如子建，只能援笔赋惊鸿。”；唐李瀚《蒙求》：“仲宣独步，子建八斗。”；元王实甫《西厢记》四本一折：“小生无宋玉般容，潘安般貌，子建般才。”；清蒲松龄《八月为李大厅复孙俊服启》：“生无一斗之才，慵开书卷;坐受五穷之累，羞掷莺花。”；清李渔《闲情偶寄·词曲上》：“吾谓技无大小，贵在能精……否则才夸八斗，胸号五车，为文仅称点鬼之谈，著书惟供覆瓿之用，虽多亦奚以为?”；唐陆龟蒙《江南秋怀寄华阳山人》诗：“才当曹斗怯，书比惠车盈。”；宋陈师道《古墨行》：“明窗净几风日暖，有愁万斛才八斗。”；宋管鉴《水调歌头·同子仪韦之登舟青阁》词：“坐间客，才论斗，气如虹。”；清蒲松龄《又与邹平张启》：“才调无能一斗，头颅犹是当年。”；明陈汝元《金莲记·偕计》：“不佞姓苏，名轼，字子瞻，眉州眉山人也。学富五车，才高八斗。”；唐黄滔《卢员外浔启》：“伏以员外断籯积学，计斗负才;龟镜词林，梯航陆海。”；孙为霆《满庭芳·亦友》词：“君比陈思八斗，我夸元礼同舟。”；唐李宗谔《馆中新蝉》诗：“八斗陈思饶赋咏，二毛潘岳易悲凉。”；柳亚子《誓墓行》诗：“沈孔张韩俪侣双，陈思八斗才宁后?”；清纪昀《阅微草堂笔记·滦阳消夏录一》：“黄金屈戌雕胡锦，不信陈王八斗才。”；清宋琬《满江红·王西樵客游武林曹顾庵赋词志喜属予和之》词之六：“况陈思、才藻气如虹，诗堪饷。”','[]',2),
(8500000000000000060,'斗酒博凉州',7,'典故','汉赵岐《三辅决录》卷二载：汉灵帝时中常侍张让专朝政，宾客多苦不得见。孟佗尽以家财贿赂张让监奴，因得见让。众以为佗与让善，争以珍物贿赂佗，佗尽以贿让，让大喜。斗酒博凉州1:<u>佗</u>又以葡萄酒一斗遗<u>让</u>，<u>让</u>即拜<u>佗</u>为<u>凉州</u>刺史。后以斗酒博凉州为贿赂得官之典。
一斗得凉州1:谓以行贿得官。
一斗胜凉州1:形容酒美或以酒为乐。
刺史葡萄酒1:指行贿求官。
博凉州1:谓贿赂得官或称赞酒美。
取凉州牧1:谓设法行贿，谋取官职。','清和邦额《夜谭随录·陆水部》：“古人斗酒博梁(凉)州，君不破一文，成此奇缘，自受多福。”；宋苏轼《次韵秦观秀才见赠》：“将军百战竟不侯，伯郎一斗得凉州。”；元周权《蒲萄酒》诗：“纵教典却鹔鹴裘，不将一斗博凉州。”；宋辛弃疾《雨中花慢·吴子似见和再用韵为别》词：“笑千篇索价，未抵葡萄，五斗凉州。”；宋苏轼《和刘长安题薛周逸老亭周最善饮酒未七十而致仕》诗：“自言酒中趣，一斗胜凉州。”；宋陈与义《道中寒食》诗：“刺史葡萄酒，先生苜蓿盘。”；宋陆游《比从人觅酒皆酸薄戏作此诗》：“酒尽聊凭折简求，不知人要博凉州。”；宋刘克庄《汉宫春·吴侍郎生日》词：“此老先生，尚不留东阁，肯博西凉?”；唐刘禹锡《葡萄歌》：“为君持以斗，往取凉州牧。”','[]',2),
(8500000000000000061,'一斛贮槟榔',7,'典故','《南史·刘穆之传》载：穆之世居京口(丹徒)，少时家贫，常就岳家乞食。一日食饱求槟榔，其妻兄弟戏之曰：“槟榔消食，君乃常饥，何忽须此?”及穆之为丹阳尹，召妻兄弟饮，至醉饱，令厨人以金盘盛槟榔一斛进之。一斛贮槟榔1:后因以一斛贮槟榔谓不以旧恶为念。
一斛荐槟榔1:谓饱食美味佳肴。
丹徒布衣1:本指<u>南朝</u><u>宋</u><u>刘穆之</u>。泛指贫困未遇之士。
乞槟榔1:谓乞食他人。
哂食槟榔1:谓讥人贫困。
满斛进槟榔1:谓饱食美味佳肴。
索槟榔1:泛指白吃他人酒席。','宋辛弃疾《水调歌头·席上为叶仲洽赋》词：“怨调为谁赋，一斛贮槟榔。”；宋陆游《蔬食》诗：“人生饥饱初何校，一斛槟榔笑汝痴。”；唐李白《玉真公主别馆苦雨赠卫尉张卿》诗之二：“何时黄金盘，一斛荐槟榔?”；宋黄庭坚《次韵胡彦明同年》：“谁料丹徒布衣侣，今朝忽有酒如川。”；清唐孙华《寄示颐儿》诗：“性拙只愁餐澡豆，家贫慎勿乞槟榔。”；唐卢纶《酬赵少尹戏示诸侄元阳等因以见赠》诗：“且请同观舞鸲鹆，何须竟哂食槟榔。”；宋陆游《晓出湖边摘野蔬》诗：“且胜堆盘供苜蓿，未言满斛进槟榔。”；宋陈克《南歌子》词：“惭愧年年高会、索槟榔。”','[]',2),
(8500000000000000062,'一言悟主',7,'典故','《汉书·车千秋传》：“会卫太子为江充所谮败，久之，千秋上急变讼太子冤，曰：‘子弄父兵，罪当笞;天子之子过误杀人，当何罪哉!臣尝梦见一白头翁教臣言。’是时，上颇知太子惶恐无他意，乃大感悟，召见千秋……立拜千秋为大鸿胪。数月，遂代刘屈氂为丞相，封富民侯。千秋无他材能术学，又无伐阅功劳，特以一言悟意，旬月取宰相封侯，世未尝有也。”汉蔡邕《让尚书乞在闲冗表》：“田千秋(车千秋，本姓田氏，故称)有神明感动，贞梦至言，以寤圣听，昭发上心，故有一日九迁。”一言悟主1:后因以一言悟主为大臣进谏得皇帝宠爱的典故。
一日九迁1:形容升迁迅速。
九迁1:形容升迁之快。
悟主一言1:谓大臣进谏致宠。','明高启《读史·田千秋》诗：“高寝郎官头已白，一言悟主即封侯。”；明高启《寓感》诗之十八：“千秋取丞相，一语悟君衷。”；南朝梁任昉《为范尚书让吏部封侯第一表》：“虽千秋之一日九迁，荀爽之十旬远至，方之微臣，未为速达。”；《南史·到撝传》：“上又数游撝家，怀其旧德，至是一岁三迁。”；唐韩愈《上张仆射书》：“苟如是，虽日受千金之赐，一岁九迁其官，感恩则有之矣。”；明张居正《谢赐玉带疏》：“冒此殊恩，感奚若啻于九迁，惧实深于三褫。”；唐窦牟《秋夕闲居对雨赠别卢七侍御坦》诗：“悟主一言那可学，从军五首竟徒为。”','[]',2),
(8500000000000000063,'子猷惜此君',7,'典故','晋裴启《语林》：“王子猷(王徽之)尝暂寄人空宅住，使令种竹。或问：‘暂住何烦尔?’啸咏良久，直指竹曰：‘何可一日无此君?’”又南朝宋刘义庆《世说新语·简傲》：“王子猷尝行过吴中，见一士大夫家极有好竹，主已知子猷当往，乃洒扫施设，在听事坐相待。王肩舆径造竹下，讽啸良久，主已失望，犹冀还，当通，遂直欲出门。主人大不堪，便令左右闭门不听出。王更以此赏主人，乃留坐，尽欢而去。”子猷惜此君1:后因以子猷惜此君为雅士爱竹之典。
一日无1:指爱竹之好。
何可一日无此君1:形容文人名士爱竹的雅兴。
墨君1:指画中之竹。
子猷1:借指知音者。
子猷竹1:雅称竹。
子猷风1:指竹风。
子猷风调1:指高风逸韵。
居士竹1:美称竹。也借指种竹的闲适生活。
此君1:指竹。
此君一日不可无1:形容爱竹的雅兴。
爱此君1:谓爱竹，表示爱竹的人情怀高雅。
爱竹啸园1:咏竹的典故。
爱竹子猷1:借指高人雅士。
王家看不足1:形容竹清雅可爱。
王家看竹1:表示情趣高雅。
王家种竹1:借指寄居所借之宅。
王猷爱1:美称竹。
王猷爱竹1:指情怀高雅。
王猷竹林1:指高洁之士的清雅居处。
竹君1:美称竹。
篮舆爱竹深1:形容对竹子的酷爱或表示文人名士的雅兴。
青君1:指竹子。','明高启《水龙吟·画红竹》词：“再相逢子猷还惜，此君未老，岁寒犹有少年颜色。”；唐刘兼《新竹》诗：“自是子猷偏爱尔，虚心高节雪霜中。”；唐元稹《寺院新竹》诗：“未遭伶伦听，非安子猷宠。威凤来有时，虚心岂无奉。”；唐陆希声《阳羡杂咏·苦竹径》：“世上何人怜苦节，应须细问子猷看。”；唐牟融《题陈侯竹亭》诗：“岁寒高节谁能识，独有王猷爱此君。”；宋王十朋《点绛唇·细香竹》词：“一日才无，便觉生尘态。”；唐宋之问《绿竹引》：“含情傲睨慰心目，何可一日无此君。”；宋苏轼《送文与可出守陵州》诗：“壁上墨君不解语，见之尚可消百忧。而况我友似君者，素节凛凛欺霜秋。”；五代齐己《溪斋》诗之一：“子猷何处在，老尽碧琅玕。”；宋吴潜《满江红·和吕居仁侍郎东里先生韵》词：“且休𣨼，陶令菊;也休羡，子猷竹。”；宋辛弃疾《水调歌头·题赵晋臣敷文真得归方是闲二堂》词：“王家竹，陶家柳，谢家池，知君勋业未了，不是枕流时。”；宋毛滂《摊声浣溪沙·吴兴僧舍竹下与王明之饮》词：“不奈晚来萧瑟意，子猷风。”；宋毛滂《青玉案·竹间戏作》词：“子猷风调全相称，是彼此、无凡韵。”；宋朱敦儒《诉衷情》词：“居士竹，故侯瓜，老生涯。自然天地，本分云山，到处为家。”；唐白居易《东楼竹》诗：“楼上夜不归，此君留我宿。”；元岑安卿《求叶仲舆写墨竹扇面》诗：“此君一日不可无，子猷笃爱心欢愉。”；唐杜牧《题刘秀才新竹》诗：“不是山阴客，何人爱此君?”；唐李白《题金陵王处士水亭》诗：“好鹅寻道士，爱竹啸名园。”；宋吕胜己《临江仙·同王侯二公登裴公亭》词：“爱竹子猷参杖履，能诗侯喜同登。”；唐韦式《一字至七字诗·竹》：“渭曲偏种多，王家看不足。”；唐李群玉《题王侍御宅》诗：“绿阴十里滩声里，闲自王家看竹来。”；唐吴融《岐阳蒙相国借宅因抒怀投献》诗：“虽非宋玉诛茅至，且学王家种竹来。”；宋王十朋《点绛唇·细香竹》词：“一日才无，便觉生尘态。轩窗外，数竿相对，不减王猷爱。”；元顾瑛《和岳季坚韵》：“王猷爱竹非无宅，山简观鱼别有池。”；清朱彝尊《哭王处士》诗之四：“王猷竹林在，旧径不堪过。”；宋李亿《征招·梅》词：“这奇绝，好唤苍髯，与竹君来共。”；唐羊士谔《酬卢司门晚夏过永宁里弊居林亭见寄》诗：“苔甃窥泉少，篮舆爱竹深。”；清褚人获《坚瓠八集·碧芦》：“〔蔡珪〕于官舍东堂，种碧芦以寄意，因作长短句曰：‘青君那肯顾寒乡，试着葭芦拟汶篁。”','[]',2),
(8500000000000000064,'司空见惯',7,'典故','唐孟启《本事诗·情感》：“刘尚书禹锡罢和州……李司空罢镇在京，慕刘名，尝邀至第中，厚设饮馔。酒酣，命妙妓歌以送之。刘于席上赋诗曰：‘䰀鬌梳头宫样妆，春风一曲《杜韦娘》。司空见惯浑闲事，断尽江南刺史肠。’”司空见惯1:后因以司空见惯称事之常见者，或对事物习以为常，不足为怪。
一曲杜韦娘1:比喻席上闻歌的惆怅共鸣之情。
杜韦娘1:本为<u>唐</u>歌女名。
见惯司空1:谓经常看到，不足为奇。','宋苏轼《满庭芳》词：“人间，何处有?司空见惯，应谓寻常。”；宋晁补之《绿头鸭·韩师朴相公会上观佳妓轻盈弹琵琶》词：“算从来、司空惯，断肠初对云鬟。”；宋陆文圭《水龙吟·再次韵一首寄药房》词：“更《韦娘》一曲，司空惯见，也应回眸。”；宋李廷忠《卜算子·萧计议席上》词：“雅兴杂鱼龙，妙舞回鸾凤。莫道司空眼惯□，还入清宵梦。”；宋吴文英《婆罗门引·为怀宁赵仇香赋》词：“奈司空经惯，未畅高情。”；宋晁补之《行香子·赠轻盈》词：“司空自惯，狂眼须惊。”；宋谢薖《菩萨蛮·陈虚中席上别李商老》词之三：“一曲《杜韦娘》，有人空断肠。”；宋刘将孙《沁园春》词：“流水断桥，坏壁春风，一曲《韦娘》。”；唐教坊用为曲名。亦借指名妓。元王实甫《西厢记》三本一折：“杜韦娘不似旧时，带围宽清减了瘦腰肢。”；清孔尚任《桃花扇·媚座》：“妙部新奇，见惯司空自品题。”','[]',2),
(8500000000000000065,'生刍致祭',7,'典故','《后汉书·徐稚传》：“林宗(郭泰字)有母忧，稚往吊之，置生刍一束于庐前而去。众怪，不知其故。林宗曰：‘此必南州高士徐孺子(徐稚字)也。《诗》不云乎：生刍一束，其人如玉。吾无德以堪之。’”生刍致祭1:后因以生刍致祭为祭吊的典故。
一束生刍1:指祭奠之物。
千里生刍1:指奔赴远方祭奠亡友。
奠生刍1:指祭奠。
徐穉吊1:指亲赴死者坟墓前祭吊。
束刍1:指祭品。
束刍吊1:指祭奠。
生刍1:指祭品。
生刍絮酒1:指祭悼亡友的祭品。
置蒭1:指致送吊丧礼物。
遗生刍1:馈赠祭品。指祭奠。','《宋史·路振传》：“生刍致祭，弊帏成礼。瘗尔崇冈，全尔具体。”；清赵翼《到扬州追悼西岩前辈》诗之一：“半年迟作生刍吊，来补桥玄酒一浇。”；宋杨万里《四十九祖母朱氏挽词》：“眼底生刍奠，身前泛柏舟。”；清尤侗《哭宋俦三》诗：“聊以代驴鸣，少佐生刍祭。”；傅尃《题陈母沈太君行述寄慰巢南》诗：“惭愧生刍驰吊晚，江南春草又离离。”；清方文《麻孟璿墓上》诗：“一束生刍迟五年，今朝匍匐恸君前。”；清袁枚《后知己诗·华亭县知县程明愫》：“我有一束刍，何处招魂奠!”；清毛奇龄《吊姜贞毅诗》之五：“长窥封事泪如流，千里生刍愧未投。”；明李东阳《闻彭侍讲敷五丧已过直沽追吊不及悼之以诗》：“欲奠生刍竟不成，匆匆一哭便长行。”；清赵翼《李雨村观察挽诗》之二：“万里难为徐穉吊，一编重检蜀州诗。”；明袁宏道《哭江进之》诗序：“欲躬致束刍，值有邑乘之役，素车白马，未卜何日。”；清蒲松龄《挽朱子青》诗：“未能束刍吊，雪涕赋《招魂》。”；唐褚亮《伤始平李少府正己》诗：“禅草回中使，生刍引吊宾。”清赵翼《哭杭应龙先生墓》诗：“奔问已悲新宿草，酬恩空托一生刍。”；清方文《谢皋羽恸哭西台》诗：“严子滩头风雪飘，生刍一束蓟门遥。”；明吴廷翰《追悼良用》诗：“生刍絮酒终难致，一束遥凭双泪传。”；宋黄彻《䂬溪诗话》卷九：“牛斗气沉龙已化，置蒭人去榻犹悬。”；清顾炎武《冬至寓汾州之阳城里中尉敏泘家祭毕而饮有作》诗：“荒庭依老桧，空谷遗生刍。”','[]',2),
(8500000000000000066,'流霞',7,'典故','汉王充《论衡·道虚》：“曼都(项曼都)好道学仙，委家亡去，三年而返。家问其状，曼都曰：‘……有仙人数人，将我上天，离月数里而止，见月上下幽冥，幽冥不知东西。居月之劳，其寒凄怆，口饥欲食，仙人辄饮我以流霞一杯。每饮一杯，数月不饥。不知去几何年月，不知以何为过，忽然若卧，复下至此。’河东号之曰‘斥仙’。”流霞1:后遂以流霞指仙人饮料，亦借指美酒。
一杯霞1:指一杯美酒。
斥仙1:指居人间的仙人。
流霞酒1:指美酒。
酌流霞1:谓饮美酒。
霞影入仙杯1:借指仙酒、美酒。
霞杯1:盛满美酒的酒杯。亦借指美酒。
霞酌1:指仙酒。
霞醴1:指美酒。
饮流霞1:谓饮美酒。
饮霞1:谓饮美酒。','晋葛洪《抱朴子·逸民》：“安得悬虚空餐，咀流霞，而使之不居乎地，不食乎谷哉?”北周庾信《卫王赠桑落酒奉答》诗：“愁人坐狭邪，喜得送流霞。”；宋王安石《春雨》诗：“幽期无可奈，强嚼一杯霞。”；宋陆游《书适》诗：“太平固自多遗老，独往何妨是斥仙。”；唐李商隐《武夷山》诗：“只得流霞酒一杯，空中箫鼓当时回。”；隋鲁范《神仙篇》诗：“霜分白鹿驾，日映流霞杯。”；唐韦述《奉和圣制送张说上集贤学士赐宴》：“赋诗开广宴，赐酒酌流霞。”；唐孟浩然《与王昌龄宴王道士房》诗：“酌霞复对此，宛似入蓬壶。”；唐骆宾王《春晚从李长史游》诗：“云光栖断树，霞影入仙杯。”；宋吕渭老《念奴娇·赠希文宠姬》词：“短短霞杯，温温罗帕，妙语书裙幅。”柳亚子《浣溪沙》词：“空对彩笺笼壁句，何曾醇酒醉霞怀?”；宋吕渭老《选冠子》词：“谁念少年，齿怯梅酸，病疏霞盏。”；唐曹唐《送刘尊师祗诏阙庭》诗之二：“霞觞共饮身虽在，风驭难倍迹未开。”清洪昇《长生殿·定情》：“金屋妆成，玉楼歌彻，千秋万岁捧霞觞。”；唐王勃《七夕赋》：“奏云和，泛霞酌。”；五代欧阳炯《〈花间集〉序》：“是以唱云谣则金母词清，挹霞醴则穆王心醉。”；唐武则天《早春夜宴》诗：“务使霞浆兴，方乘泛洛归。”；唐吴均《游仙》诗之七：“霞液朝可饮，虹芝晚堪食。”；宋王安石《用乐道舍人韵书十日事呈乐道舍人圣从待制》：“归去莫言天上事，但知呼客饮流霞。”；唐孟郊《招文士饮》诗：“相劝罢吟雪，相从愁饮霞。”','[]',2),
(8500000000000000067,'南柯梦',7,'典故','唐李公佐《南柯太守传》载：淳于棼一日醉卧宅前大槐树下，恍惚间被二紫衣人引至槐安国，娶公主，封南柯太守，荣华富贵，显赫一时。后率师出征战败，公主已死，遭国王疑忌，被遣归。醒后，在槐树下掘得蚁穴，即梦中之槐安国。南柯郡为槐树南枝下另一蚁穴。南柯梦1:后因以南柯梦指虚幻的梦境。比喻人生如梦，富贵得失虚幻无常。
一枕南柯1:指一场幻梦。
一枕槐根1:指美梦。
侯王蚁1:喻人生如梦，富贵无常。
南柯国1:指南柯梦中的<u>槐安国</u>。寓追求虚幻的富贵荣华之意。
南柯太守1:南柯梦中的太守。常用作浮生无常的典实。
南柯姻1:<u>淳于棼</u>在南柯梦中娶公主，显赫一时。因以“南柯姻”指梦中荣华。
大槐1:指虚幻的梦境。喻人生如梦，富贵无常。
大槐国1:指南柯梦中的<u>槐安国</u>。借指虚幻无常的富贵权势。
大槐宫1:<u>大槐安国</u>之宫，原是槐树下一蚁穴，比喻富贵权势虚幻无常。
大槐枕1:借指睡梦。
官蚁穴1:指梦中富贵。
枕上南柯1:指美梦。
枯槐聚蚁1:“南柯梦”中的<u>槐安国</u>蚁民。比喻弱国微民。
柯下梦1:虚幻之梦。喻虚幻无常之富贵荣华。
梦断槐安1:谓美梦破灭。
梦槐安1:比喻进入美妙的境界。多寓富贵虚幻无常之意。
梦里南柯1:指虚无缥缈之处。
槐南梦1:虚幻的梦。形容时光易逝，岁月短暂。
槐壤1:指蚁穴。暗喻人世虚幻无常的名利场。
槐安国1:<u>唐</u><u>李公佐</u>《南柯太守传》中的虚构之国。寓人生如梦，富贵得失无常之意。
槐安梦1:虚幻之梦。亦用以喻人生如梦，富贵得失无常。
槐柯蚁穴1:喻指富贵无常的名利场。
槐根封蚁1:喻指虚幻的功名富贵。
槐根洞1:指南柯梦中的<u>槐安国</u>。
槐根蚁1:指南柯梦中之蚁。比喻追求暂时富贵的人。
淳于梦中人1:指追求虚幻的富贵权势之人。
玄驹国1:南柯梦中的<u>槐安国</u>。玄驹，蚁的别名。寓功名虚幻无常之意。
聚蚁功名1:指梦中功名。
蚁丘罢战1:喻停止无意义的争斗。
蚁战1:喻为名利而起的争斗。
蚁梦1:指虚幻的梦境。喻梦中荣华，富贵无常。
蚁梦槐1:形容时光短暂，年华易逝。
蚁窠1:蚂蚁栖息之处。亦喻梦幻。
蚁聚1:喻名利场藐小，富贵荣华虚幻无常。
蝼蚁梦1:虚幻的美梦。喻指虚幻无常的荣华。
蝼蚁王侯1:喻世事如梦，富贵得失无常。
蝼蚁郡1:指<u>唐</u><u>李公佐</u>《南柯太守传》中所说<u>南柯郡</u>。喻梦里功名富贵。
车旋蚁穴1:谓美梦破灭。
高卧南柯穴1:谓睡觉。','宋朱敦儒《水龙吟》词：“念伊嵩旧隐，巢由故友，南柯梦，遽如许!”明无名氏《闺中四梦八空》词：“恩多也是空，情多也是空，都做了南柯梦。”；宋苏轼《九日次定国韵》：“朝菌无晦朔，蟪蛄疑春秋。南柯已一世，我眠未转头。”宋范成大《题成山晚对轩壁》诗：“一枕清风梦绿萝，人间随处是南柯。”；元郑光祖《倩女离魂》三折：“分明见王生，说得了官也，醒来却是南柯一梦。”；周恩来《送蓬仙兄返里有感》诗：“东风催异客，南浦唱骊歌。转眼人千里，消魂梦一柯。”；元石君宝《紫云亭》：“自从这人北渡，浑一似梦南柯。”；元关汉卿《鲁斋郎》四折：“蜗牛角上人我，梦魂中一枕南柯。”；元无名氏《盆儿鬼》二折：“想人生总是一南柯。”董必武《写在辛亥革命回忆录前面》诗：“帝制已如花堕溷，两番复辟一南柯。”；元范康《竹叶舟》二折：“分明是一枕槐安，怎么的倒做了两下离愁?”；明郑若庸《玉玦记·诏封》：“雌雄蜀垅，一觉南槐。图王业霸，而今安在!”；宋赵希迈《八声甘州·竹西怀古》词：“锦缆残香在否?枉被白鸥猜。千古扬州梦，一觉庭槐。”；清钱谦益《己丑元旦试笔二首》之一：“三杯竹叶朝歌后，一枕槐根午梦余。”；宋王奕《贺新郎·金陵怀古》词：“老媚幽花栖断础，睇故宫、空拊英雄髀。身世蝶，侯王蚁。”；清袁枚《遣兴》诗之二：“不是诗人谁救我，南柯国里把门敲。”；五代刘兼《偶有下殇因而自遣》诗：“南柯太守知人意，休问陶陶塞上翁。”；元揭傒斯《题张彦辅枯木》诗：“湖上飞仙疑有耳，梦中太守已无柯。”；宋苏轼《再和孙志举》诗：“醉眠中山酒，结梦南柯姻。宠辱能几何，悲欢浩无垠。”；宋黄庭坚《题太和南塔寺壁》诗：“万事尽还杯酒里，百年俱在大槐中。”；宋吴潜《贺新郎·和赵丞相见寿》词：“安得结庐相近傍，买闲田、数亩躬耕筑。已梦断，大槐国。”；清赵翼《夜梦从军为贼所执》诗：“噩梦无端破胆寒，兵氛阑入大槐安。”；宋黄庭坚《元丰癸亥经行石潭寺见旧和栖蟾诗甚可笑因别和一章》：“千里追奔两蜗角，百年得意大槐宫。”；宋廖行之《如梦令·记梦》词：“雨歇凉生枕簟，不梦大槐宫殿。惟对谪仙人，一笑高情睠睠。”；元揭傒斯《宿华盖山赠赵尊师》诗：“我有大槐枕，相见东蓬莱。”；宋黄庭坚《次韵幾复答予所赠三物》之二：“薰衣作家想，伏枕梦闺姝。游子官蚁穴，谪仙居匏壶。”；清杨潮观《黄石婆授计逃关》：“劫灰楼炭战尘多，搅醒俺枕上南柯。”；金元好问《眼中》诗：“枯槐聚蚁无多地，秋水鸣蛙自一天。”；宋刘辰翁《满江红·寿某翁》词：“依枕不寻柯下梦，举头自爱橘中名。”；元李溥光《秋日过景光禄墓》诗之二：“金天一代盛豪华，梦断槐安事可嗟。”；宋黄庭坚《题槐安阁》诗：“功成事遂人间世，欲梦槐安到此游。”金刘瞻《子文致君九日用安字韵聊亦同赋》：“旅食京华秋又残，旧游真似梦槐安。”；清赵翼《阅欧阳五代史》诗：“忽然梦入大槐安，竟似身登上将坛。”；元薛汉《和郑应奉杂诗》之六：“宦游梦入槐，宴坐柳生肘。”；元许谦《春夜次韵》之一：“饥乌惊鹊起南枝，梦入槐柯觉亦悲。”；明郑若庸《玉玦记·行刺》：“箭穿杨叶知无失，梦入槐根定不归。”；明徐渭《洞岩入鳖口有石枰石桥及石池诸景》诗：“星河作影当归路，疑是淳于梦大槐。”；宋范成大《除夜书怀》诗：“床头新历日，衣上旧尘埃。摇落何堪柳，纷纭各梦槐。隙光能几许，世事剧悠哉!”；宋范成大《题药方》诗：“孤童亦复梦槐柯，无德无功用福多。”；宋黄庭坚《次韵十九叔父台源》诗：“闻道台源境，锄荒三径通。人曾梦蚁穴，鹤亦怕鸡笼。”；宋陆游《对酒戏作》诗：“身闲取醉真当勉，莫学痴人梦蚁窠。”；元王实甫《西厢记》二本三折：“谁承望月底西厢，变了梦里南柯。”；清刘嗣绾《金缕曲·题陈迦陵洗桐图》词：“百年弹指槐南梦。猛思量，迦陵仙鸟，几场吟讽。”；元王恽《滕王蝶蚁图》诗之一：“槐壤纷纷事暂歇，枕中栩栩伴周闲。”；元鲜于枢《困学斋杂录》引田时秀《感兴》诗：“百年身世槐安国，千古人情羹颉侯。”；明文徵明《张梦晋庄子梦蝶图》诗：“却笑黄粱待炊者，漫将车马入槐南。”；元曹伯启《梦酒诗会》诗：“乌蚁混游槐国市，绿醅初泼汉江涛。”；宋范成大《次韵宗伟阅香乐》：“尽遣馀钱付桑落，莫随短梦到槐安。”元范康《竹叶舟》二折：“分明是一枕槐安，怎么的倒做了两下离愁。”；宋陆游《秋晚》诗：“幻境槐安梦，危机竹节滩。”金路铎《汴梁公廨西楼》诗之二：“薄宦槐安梦，浮名剑首炊。”；清黄鷟来《秋感》诗：“一世槐中梦，纷纷斗蚁尊。”；明王錂《春芜记·宸游》：“寡人适方饮酒之间，想起大夫所谭神女之事，不觉神情恍惚，睡思懵腾……正是只将桑海千秋事，付与槐南一梦中。”；清李元度《粉蝶儿·散勇归田留别诸好友》套曲：“鱼书情惓惓，鹗荐话重重，都只算槐柯一梦。”；元乔吉《殿前欢·里西瑛号懒云窝自叙有作奉和》曲：“槐根梦觉兴亡破，依旧南柯。”；宋虞俦《再和以莲心茶送巩使君小诗将之》：“','[]',2),
(8500000000000000068,'黄粱梦',7,'典故','唐沈既济《枕中记》载：卢生在邯郸客店遇道士吕翁。自顾衣装敝亵，乃长叹息曰：“大丈夫生世不谐，困如是也!”吕翁探囊中青色瓷枕授之曰：“子枕吾枕，当令子荣适如志。”黄粱梦1:时店主正蒸黍(去皮后北方人称黄小米，即黄粱)，生梦入枕中，享尽富贵荣华。
一枕黄粱1:一场幻梦。或喻人生的短暂，或喻人生富贵的虚幻或喻不可能实现的梦想。
一梦炊黄粱1:形容人生短暂。
一梦觉黄粱1:谓梦幻破灭。
一梦黄粱1:谓做个好梦。比喻闲适遂意。
一觉黄粱熟1:形容人生富贵虚幻、无常。
卢生梦1:幻梦。喻虚幻的富贵荣华。
卢生逐梦1:喻追逐虚幻的荣华富贵。
吕公枕1:喻人生如在梦中，万事终归虚幻。
客窗炊黍1:谓仙人点化。
拜卢生1:谓追逐虚幻的功名富贵。
旅枕梦1:指追逐荣华富贵的幻梦。
枕上黄粱1:指幻梦，美梦。
枕中梦1:喻富贵荣华皆虚幻，转眼成空。
梦熟黄粱1:喻进入梦乡，熟睡。
梦觉黄粱1:指幻梦醒悟之时。
梦里荣华1:形容人生荣华富贵的虚幻无常。
梦里说邯郸1:喻虚幻之事。
梦里黄粱1:喻虚幻的事、痴心妄想。
炊熟黄粱1:喻指醒悟之时。
炊粱梦1:指梦幻。喻虚幻的人生富贵。
炊黍枕1:指《枕中记》中人物<u>吕翁</u>给<u>卢生</u>的青磁枕，枕此枕可荣适如志。借指幻梦。
百年炊未熟1:喻人生的虚幻短暂。
粱炊1:比喻虚幻的梦境。
赠枕1:喻富贵如幻梦。
邯郸入梦1:喻沉迷于虚幻的人生富贵。
邯郸吕公枕1:指虚无短暂。
邯郸富贵1:指梦中虚幻的荣华富贵。
邯郸景1:指虚幻的梦境。
邯郸梦1:指梦幻。喻虚幻之事或不能实现的梦想。
邯郸粱未熟1:喻梦想的破灭。
邯郸道1:比喻虚幻之路。
邯郸重步1:比喻进入梦乡。
饭熟邯郸1:喻人生荣华富贵终归虚幻。
高枕熟黄粱1:指美梦。喻闲适遂意。
鹿走邯郸1:喻指争夺天下，终归虚幻。
黄粮1:指美好的梦。
黄粱一瞬1:形容虚幻，短暂。
黄粱入梦1:喻沉迷于虚幻的人生富贵。
黄粱境1:指美好的梦境。
